fn acm_details_lines(
    cert: &AcmCertificate,
    details_state: Option<&crate::lazy::Lazy<crate::aws::services::acm::AcmCertDetails>>,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("ARN".to_string(), cert.certificate_arn.clone()),
        ("Domain".to_string(), cert.domain_name.clone()),
        ("Status".to_string(), cert.status.clone()),
        (
            "Type".to_string(),
            match cert.cert_type.as_str() {
                "AMAZON_ISSUED" => "Amazon Issued".to_string(),
                "IMPORTED" => "Imported".to_string(),
                "PRIVATE" => "Private CA".to_string(),
                other => other.to_string(),
            },
        ),
        (
            "Expires".to_string(),
            cert.not_after.clone().unwrap_or_else(|| "—".to_string()),
        ),
    ];
    if let Some(days) = cert.days_until_expiry {
        rows.push((
            "Days Remaining".to_string(),
            if days < 0 {
                format!("Expired {} days ago", days.abs())
            } else {
                format!("{}", days)
            },
        ));
    }
    rows.push(("".to_string(), "".to_string()));

    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("".to_string(), "Loading certificate details…".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(crate::lazy::Lazy::Loaded(d)) => {
            rows.push(("Key Algorithm".to_string(), d.key_algorithm.clone()));
            rows.push((
                "Renewal Eligibility".to_string(),
                d.renewal_eligibility.clone(),
            ));
            if let Some(issued) = &d.issued_at {
                rows.push(("Issued At".to_string(), issued.clone()));
            }
            if let Some(nb) = &d.not_before {
                rows.push(("Not Before".to_string(), nb.clone()));
            }
            rows.push(("".to_string(), "".to_string()));
            if d.in_use_by.is_empty() {
                rows.push(("In Use By".to_string(), "Not in use".to_string()));
            } else {
                rows.push(("In Use By".to_string(), "".to_string()));
                for arn in &d.in_use_by {
                    rows.push((format!("  {}", arn), "".to_string()));
                }
            }
        }
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

fn acm_domains_lines(
    cert: &AcmCertificate,
    details_state: Option<&crate::lazy::Lazy<crate::aws::services::acm::AcmCertDetails>>,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Primary Domain".to_string(), cert.domain_name.clone()),
        ("".to_string(), "".to_string()),
    ];

    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("".to_string(), "Loading SANs…".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(crate::lazy::Lazy::Loaded(d)) => {
            if d.subject_alternative_names.is_empty() {
                rows.push(("SANs".to_string(), "None".to_string()));
            } else {
                rows.push((
                    "SANs".to_string(),
                    format!("({} domains)", d.subject_alternative_names.len()),
                ));
                for san in &d.subject_alternative_names {
                    rows.push((format!("  {}", san), "".to_string()));
                }
            }
        }
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

fn acm_validation_lines(details_state: Option<&crate::lazy::Lazy<crate::aws::services::acm::AcmCertDetails>>) -> Vec<(String, String)> {
    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            vec![("".to_string(), "Loading validation details…".to_string())]
        }
        Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
        Some(crate::lazy::Lazy::Loaded(d)) => {
            let mut rows = vec![];
            if d.validation_options.is_empty() {
                rows.push(("".to_string(), "No validation options available.".to_string()));
            }
            for opt in &d.validation_options {
                rows.push(("Domain".to_string(), opt.domain_name.clone()));
                rows.push(("Method".to_string(), opt.validation_method.clone()));
                rows.push(("Status".to_string(), opt.validation_status.clone()));
                if let Some(rr) = &opt.resource_record {
                    rows.push(("".to_string(), "".to_string()));
                    rows.push(("CNAME Name".to_string(), rr.name.clone()));
                    rows.push(("CNAME Value".to_string(), rr.value.clone()));
                    rows.push(("Record Type".to_string(), rr.record_type.clone()));
                }
                rows.push(("".to_string(), "".to_string()));
            }
            rows
        }
    }
}

fn acm_tags_lines(details_state: Option<&crate::lazy::Lazy<crate::aws::services::acm::AcmCertDetails>>) -> Vec<(String, String)> {
    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            vec![("".to_string(), "Loading tags…".to_string())]
        }
        Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
        Some(crate::lazy::Lazy::Loaded(d)) => {
            let mut rows = vec![];
            if d.tags.is_empty() {
                rows.push(("".to_string(), "No tags".to_string()));
            } else {
                let mut sorted: Vec<(&String, &String)> = d.tags.iter().collect();
                sorted.sort_by_key(|(k, _)| k.as_str());
                for (key, value) in sorted {
                    rows.push((format!("  {}", key), value.clone()));
                }
            }
            rows.push(("".to_string(), "".to_string()));
            rows
        }
    }
}

// ── Step Functions state-machine split pane ────────────────────────────────────

fn render_sfn_split(app: &App, sm: &SfnStateMachine, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");

    let mut block = theme::pane_block("State Machine", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = build_sfn_header_lines(sm);
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);
    render_sfn_section_tabs(app, chunks[2], frame);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn build_sfn_header_lines(sm: &SfnStateMachine) -> Vec<Line<'static>> {
    let mut lines = vec![Line::raw("")];

    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            sm.name.clone(),
            Style::default()
                .fg(crate::ui::theme::text_primary())
                .add_modifier(Modifier::BOLD),
        ),
    ]));

    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            SfnStateMachine::type_label(&sm.kind).to_string(),
            Style::default().fg(theme::text_dim()),
        ),
    ]));

    lines.push(Line::raw(""));
    lines
}

fn render_sfn_section_tabs(app: &App, area: Rect, frame: &mut Frame) {
    render_section_tab_bar(
        app,
        area,
        frame,
        &descriptor_tabs(app, &crate::aws::services::step_functions::SFN_SECTIONS),
    );
}

pub fn sfn_section_lines(
    sm: &SfnStateMachine,
    section: SfnDetailSection,
    details_state: Option<&crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnDetails>>>,
    executions: &[&crate::aws::services::step_functions::SfnExecution],
) -> Vec<(String, String)> {
    match section {
        SfnDetailSection::Details => sfn_details_lines(sm, details_state),
        SfnDetailSection::Definition => sfn_definition_lines(details_state),
        SfnDetailSection::Executions => sfn_executions_lines(sm, executions),
        SfnDetailSection::Tags => sfn_tags_lines(details_state),
    }
}

fn sfn_details_lines(
    sm: &SfnStateMachine,
    details_state: Option<&crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnDetails>>>,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Name".to_string(), sm.name.clone()),
        ("ARN".to_string(), sm.arn.clone()),
        (
            "Type".to_string(),
            SfnStateMachine::type_label(&sm.kind).to_string(),
        ),
    ];

    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("".to_string(), "".to_string()));
            rows.push(("".to_string(), "Loading state machine details…".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(crate::lazy::Lazy::Loaded(d)) => {
            // Prefer the authoritative type from describe over the list summary.
            if let Some(type_row) = rows.iter_mut().find(|(k, _)| k == "Type") {
                type_row.1 = SfnStateMachine::type_label(&d.kind).to_string();
            }
            rows.push(("Status".to_string(), d.status.clone()));
            if let Some(created) = &d.created {
                rows.push(("Created".to_string(), created.clone()));
            }
            rows.push(("IAM Role".to_string(), d.role_arn.clone()));

            // Logging — the `t` tail resolves the same group, so surfacing it
            // here doubles as the explanation when `t` says logging is off.
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Logging".to_string(), "".to_string()));
            rows.push(("  Level".to_string(), d.logging_level.clone()));
            match &d.log_group {
                Some(g) => {
                    rows.push(("  Log Group".to_string(), g.clone()));
                    rows.push((
                        "  Execution Data".to_string(),
                        if d.include_execution_data {
                            "included".to_string()
                        } else {
                            "not included".to_string()
                        },
                    ));
                    rows.push(("".to_string(), "  · t to tail these logs".to_string()));
                }
                None => {
                    rows.push((
                        "".to_string(),
                        "  ⚠ No CloudWatch Logs destination — execution logs aren't recorded"
                            .to_string(),
                    ));
                }
            }
            rows.push((
                "  X-Ray Tracing".to_string(),
                if d.tracing_enabled {
                    "✓ enabled".to_string()
                } else {
                    "disabled".to_string()
                },
            ));
        }
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

fn sfn_definition_lines(details_state: Option<&crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnDetails>>>) -> Vec<(String, String)> {
    match details_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            vec![("".to_string(), "Loading definition…".to_string())]
        }
        Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
        Some(crate::lazy::Lazy::Loaded(d)) => {
            let line_count = d.definition.lines().count();
            vec![
                (
                    "Amazon States Language definition".to_string(),
                    "".to_string(),
                ),
                ("".to_string(), "".to_string()),
                ("Lines".to_string(), line_count.to_string()),
            ]
        }
    }
}

/// Executions are first-class rows on the Executions sub-tab, so this section
/// filters the siblings already loaded — zero fetch, and every ARN row is
/// `Enter`-jumpable into that execution's own pane.
fn sfn_executions_lines(
    sm: &SfnStateMachine,
    executions: &[&crate::aws::services::step_functions::SfnExecution],
) -> Vec<(String, String)> {
    if sm.is_express() {
        return vec![
            (
                "".to_string(),
                "EXPRESS executions aren't retained by ListExecutions.".to_string(),
            ),
            (
                "".to_string(),
                "Tail the state machine's CloudWatch log group with `t` instead.".to_string(),
            ),
        ];
    }

    if executions.is_empty() {
        return vec![("".to_string(), "No recent executions.".to_string())];
    }

    let running = executions.iter().filter(|e| e.is_running()).count();
    let failed = executions.iter().filter(|e| e.failed()).count();

    let mut rows = vec![(
        "Recent Executions".to_string(),
        format!("{} shown", executions.len()),
    )];
    if running > 0 || failed > 0 {
        let mut parts = Vec::new();
        if running > 0 {
            parts.push(format!("{} running", running));
        }
        if failed > 0 {
            parts.push(format!("{} failed", failed));
        }
        rows.push(("  Status".to_string(), parts.join(", ")));
    }
    rows.push(("".to_string(), "".to_string()));

    for e in executions {
        rows.push((e.name.clone(), e.status.clone()));
        // Key-value so the ARN classifies as a jump into the execution pane.
        rows.push(("  Execution".to_string(), e.arn.clone()));
        if let Some(started) = &e.started {
            rows.push(("  Started".to_string(), started.clone()));
        }
        rows.push(("  Duration".to_string(), e.duration_label()));
        rows.push(("".to_string(), "".to_string()));
    }
    rows
}

