pub fn sfn_exec_section_lines(
    exec: &SfnExecution,
    section: SfnExecDetailSection,
    detail_state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnExecutionDetail>>,
    >,
    history_state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnHistory>>,
    >,
) -> Vec<(String, String)> {
    match section {
        SfnExecDetailSection::Overview => sfn_exec_overview_lines(exec, detail_state),
        SfnExecDetailSection::Input => sfn_exec_payload_lines(detail_state, true),
        SfnExecDetailSection::Output => sfn_exec_payload_lines(detail_state, false),
        SfnExecDetailSection::History => sfn_exec_history_lines(exec, history_state),
    }
}

fn sfn_exec_overview_lines(
    exec: &SfnExecution,
    detail_state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnExecutionDetail>>,
    >,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Name".to_string(), exec.name.clone()),
        ("Status".to_string(), exec.status.clone()),
        ("ARN".to_string(), exec.arn.clone()),
        // Key-value so the ARN jumps back to the State Machines sub-tab.
        ("State Machine".to_string(), exec.state_machine_arn.clone()),
    ];
    if let Some(started) = &exec.started {
        rows.push(("Started".to_string(), started.clone()));
    }
    match &exec.stopped {
        Some(stopped) => rows.push(("Stopped".to_string(), stopped.clone())),
        None => rows.push(("Stopped".to_string(), "— still running".to_string())),
    }
    rows.push(("Duration".to_string(), exec.duration_label()));
    if let Some(map_run) = &exec.map_run_arn {
        rows.push(("Map Run".to_string(), map_run.clone()));
    }
    if let Some(n) = exec.item_count {
        rows.push(("Map Items".to_string(), n.to_string()));
    }
    // From the list item, so a redriven execution reads as one before the
    // describe lands (which then adds the date and eligibility).
    if exec.redrive_count.unwrap_or(0) > 0 {
        rows.push((
            "Redriven".to_string(),
            format!("{} time(s)", exec.redrive_count.unwrap_or(0)),
        ));
    }

    match detail_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("".to_string(), "".to_string()));
            rows.push(("".to_string(), "Loading execution details…".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => rows.extend(error_rows(e)),
        Some(crate::lazy::Lazy::Loaded(d)) => {
            if d.error.is_some() || d.cause.is_some() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Failure".to_string(), "".to_string()));
                if let Some(err) = &d.error {
                    rows.push(("  Error".to_string(), err.clone()));
                }
                if let Some(cause) = &d.cause {
                    // The cause is often a stack trace or a nested JSON blob —
                    // show it in full as content lines rather than truncating.
                    push_wrapped_content(&mut rows, cause, 40);
                }
            }
            if d.redrive_count.unwrap_or(0) > 0 || d.redrive_status.is_some() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Redrive".to_string(), "".to_string()));
                if let Some(n) = d.redrive_count {
                    rows.push(("  Count".to_string(), n.to_string()));
                }
                if let Some(date) = &d.redrive_date {
                    rows.push(("  Last Redriven".to_string(), date.clone()));
                }
                if let Some(status) = &d.redrive_status {
                    rows.push(("  Eligible".to_string(), status.clone()));
                }
                if let Some(reason) = &d.redrive_status_reason {
                    rows.push(("  Reason".to_string(), reason.clone()));
                }
            }
            if d.state_machine_alias_arn.is_some() || d.state_machine_version_arn.is_some() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Revision".to_string(), "".to_string()));
                if let Some(a) = &d.state_machine_alias_arn {
                    rows.push(("  Alias".to_string(), a.clone()));
                }
                if let Some(v) = &d.state_machine_version_arn {
                    rows.push(("  Version".to_string(), v.clone()));
                }
            }
            if let Some(trace) = &d.trace_header {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("X-Ray Trace".to_string(), trace.clone()));
            }
        }
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

/// Input and Output share one `DescribeExecution`, so they share a renderer.
fn sfn_exec_payload_lines(
    detail_state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnExecutionDetail>>,
    >,
    input: bool,
) -> Vec<(String, String)> {
    let what = if input { "input" } else { "output" };
    match detail_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            vec![("".to_string(), format!("Loading {}…", what))]
        }
        Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
        Some(crate::lazy::Lazy::Loaded(d)) => {
            let (payload, truncated) = if input {
                (&d.input, d.input_truncated)
            } else {
                (&d.output, d.output_truncated)
            };
            let mut rows = Vec::new();
            if truncated {
                rows.push((
                    "".to_string(),
                    format!(
                        "  ⚠ The {} exceeded the inline size limit and was written to S3",
                        what
                    ),
                ));
                rows.push(("".to_string(), "".to_string()));
            }
            match payload {
                Some(p) if !p.is_empty() => {
                    rows.push(("".to_string(), "  · e opens the raw JSON".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    push_wrapped_content(&mut rows, p, 400);
                }
                _ if !input => {
                    // A running or failed execution has no output at all; say
                    // which, rather than showing an empty section.
                    rows.push((
                        "".to_string(),
                        if d.error.is_some() {
                            "No output — the execution failed (see Overview for the cause)"
                                .to_string()
                        } else {
                            "No output yet — the execution hasn't completed".to_string()
                        },
                    ));
                }
                _ => rows.push(("".to_string(), format!("No {}", what))),
            }
            rows
        }
    }
}

fn sfn_exec_history_lines(
    exec: &SfnExecution,
    history_state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::step_functions::SfnHistory>>,
    >,
) -> Vec<(String, String)> {
    use crate::aws::services::step_functions::{fmt_duration, fmt_epoch_time};

    match history_state {
        None | Some(crate::lazy::Lazy::Loading) => {
            vec![("".to_string(), "Loading execution history…".to_string())]
        }
        Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
        Some(crate::lazy::Lazy::Loaded(h)) => {
            let mut rows = Vec::new();

            if h.capped {
                rows.push((
                    "".to_string(),
                    "  ⚠ Long history — showing the most recent events only".to_string(),
                ));
                rows.push(("".to_string(), "".to_string()));
            }

            if let Some((error, cause)) = &h.failure {
                rows.push(("Failure".to_string(), "".to_string()));
                rows.push(("  Error".to_string(), error.clone()));
                if !cause.is_empty() {
                    push_wrapped_content(&mut rows, cause, 20);
                }
                rows.push(("".to_string(), "".to_string()));
            }

            // ── The states, in order, with how long each took. The one still
            // open on a RUNNING execution is what it's doing right now.
            rows.push(("States".to_string(), format!("{}", h.spans.len())));
            if h.spans.is_empty() {
                rows.push((
                    "".to_string(),
                    "  No state transitions recorded yet".to_string(),
                ));
            }
            for span in &h.spans {
                let marker = if span.error.is_some() {
                    "✗"
                } else if span.is_open() {
                    if exec.is_running() {
                        "▸"
                    } else {
                        // Not running and never exited — the execution ended
                        // inside this state.
                        "⚠"
                    }
                } else {
                    "✓"
                };
                let timing = match span.duration_secs {
                    Some(d) => fmt_duration(d),
                    None if exec.is_running() => "running".to_string(),
                    None => "did not complete".to_string(),
                };
                rows.push((
                    format!("  {} {}", marker, span.name),
                    format!("{}  ({})", timing, fmt_epoch_time(span.entered_secs)),
                ));
                if let Some(res) = &span.resource {
                    // Key-value so a Lambda / SNS / ECS ARN is Enter-jumpable.
                    rows.push(("      Resource".to_string(), res.clone()));
                }
                if let Some(err) = &span.error {
                    rows.push(("      Error".to_string(), err.clone()));
                    if let Some(cause) = &span.cause {
                        push_wrapped_content(&mut rows, cause, 12);
                    }
                }
            }

            // ── The raw event stream underneath, for when the span view isn't
            // enough (choice evaluations, retries, wait states).
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Events".to_string(), format!("{}", h.events.len())));
            for e in &h.events {
                let mut label = format!("  {}  #{} {}", fmt_epoch_time(e.ts_secs), e.id, e.kind);
                if let Some(state) = &e.state {
                    label.push_str(&format!("  {}", state));
                }
                rows.push((label, String::new()));
                if let Some(err) = &e.error {
                    rows.push(("".to_string(), format!("      ✗ {}", err)));
                }
            }

            rows.push(("".to_string(), "".to_string()));
            rows
        }
    }
}

/// Push a multi-line blob as plain content lines, capped. Long single lines are
/// hard-wrapped on a char boundary so a minified JSON cause doesn't render as
/// one unreadable row.
fn push_wrapped_content(rows: &mut Vec<(String, String)>, text: &str, max_lines: usize) {
    const WIDTH: usize = 110;
    let mut emitted = 0usize;
    for line in text.lines() {
        let mut rest = line;
        while !rest.is_empty() {
            if emitted >= max_lines {
                rows.push(("".to_string(), "      · truncated".to_string()));
                return;
            }
            let take = rest
                .char_indices()
                .take_while(|(i, _)| *i < WIDTH)
                .last()
                .map(|(i, c)| i + c.len_utf8())
                .unwrap_or(rest.len());
            let (head, tail) = rest.split_at(take);
            rows.push((format!("      {}", head), String::new()));
            emitted += 1;
            rest = tail;
        }
        if line.is_empty() {
            rows.push(("".to_string(), "".to_string()));
        }
    }
}

// ── Health Event split pane ────────────────────────────────────────────────────

pub fn health_section_lines(
    evt: &crate::aws::services::health::HealthEvent,
    section: HealthEventDetailSection,
    details_state: Option<&crate::lazy::Lazy<crate::aws::services::health::HealthEventDetails>>,
) -> Vec<(String, String)> {
    match section {
        HealthEventDetailSection::Details => vec![
            ("Service".to_string(), evt.service.clone()),
            ("Event Type".to_string(), evt.event_type_code.clone()),
            ("Category".to_string(), evt.category.clone()),
            ("Status".to_string(), evt.status_code.clone()),
            ("Scope".to_string(), evt.scope.clone()),
            ("Region".to_string(), evt.region.clone()),
            ("Availability Zone".to_string(), evt.availability_zone.clone()),
            ("".to_string(), "".to_string()),
            ("Start Time".to_string(), evt.start_time.clone()),
            ("End Time".to_string(), evt.end_time.clone()),
            ("Last Updated".to_string(), evt.last_updated_time.clone()),
            ("".to_string(), "".to_string()),
            ("ARN".to_string(), evt.arn.clone()),
        ],
        HealthEventDetailSection::Description => match details_state {
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("".to_string(), "Loading description…".to_string())]
            }
            Some(crate::lazy::Lazy::Error(e)) => {
                error_rows(e)
            }
            Some(crate::lazy::Lazy::Loaded(d)) => {
                if d.description.is_empty() {
                    vec![("".to_string(), "No description available".to_string())]
                } else {
                    d.description
                        .lines()
                        .map(|line| (format!("  {}", line), "".to_string()))
                        .collect()
                }
            }
        },
        HealthEventDetailSection::AffectedEntities => match details_state {
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("".to_string(), "Loading affected entities…".to_string())]
            }
            Some(crate::lazy::Lazy::Error(e)) => {
                error_rows(e)
            }
            Some(crate::lazy::Lazy::Loaded(d)) => {
                if d.affected_entities.is_empty() {
                    return vec![("".to_string(), "No affected entities".to_string())];
                }
                let mut rows = Vec::new();
                for (i, entity) in d.affected_entities.iter().enumerate() {
                    if i > 0 {
                        rows.push(("".to_string(), "".to_string()));
                    }
                    rows.push(("Entity".to_string(), entity.entity_value.clone()));
                    if !entity.status_code.is_empty() {
                        rows.push(("  Status".to_string(), entity.status_code.clone()));
                    }
                    if !entity.last_updated_time.is_empty() {
                        rows.push(("  Last Updated".to_string(), entity.last_updated_time.clone()));
                    }
                }
                rows
            }
        },
    }
}

fn render_health_split(
    app: &App,
    evt: &crate::aws::services::health::HealthEvent,
    area: ratatui::layout::Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 3, "");
    let mut block = theme::pane_block("Health Event", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                evt.display_name(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{} · {} · {}", evt.category, evt.status_code, evt.region),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);

    let sections = descriptor_tabs(app, &crate::aws::services::health::HEALTH_EVENT_SECTIONS);
    let mut spans: Vec<Span> = vec![Span::raw("  ")];
    for (i, (key, label, section)) in sections.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled("   │   ", Style::default().fg(theme::text_dim())));
        }
        let active = *section;
        if active {
            spans.push(Span::styled(
                key.to_string(),
                Style::default()
                    .fg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default()
                    .fg(Color::Black)
                    .bg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
        } else {
            spans.push(Span::styled(
                key.to_string(),
                Style::default().fg(theme::text_dim()),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default().fg(crate::ui::theme::text_muted()),
            ));
        }
    }
    frame.render_widget(Paragraph::new(Line::from(spans)), chunks[2]);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

// ── FSx File System split pane ─────────────────────────────────────────────────

pub fn fsx_section_lines(
    fs: &crate::aws::services::fsx::FsxFileSystem,
    section: FsxDetailSection,
    volumes: Option<&crate::lazy::Lazy<Vec<crate::aws::services::fsx::FsxVolume>>>,
    backups: Option<&crate::lazy::Lazy<Vec<crate::aws::services::fsx::FsxBackup>>>,
) -> Vec<(String, String)> {
    use crate::aws::services::fsx::FsxConfig;
    match section {
        FsxDetailSection::Volumes => fsx_volumes_lines(volumes),
        FsxDetailSection::Backups => fsx_backups_lines(backups),
        FsxDetailSection::Details => {
            let mut rows = vec![
                ("File System ID".to_string(), fs.file_system_id.clone()),
                ("ARN".to_string(), fs.arn.clone()),
                ("Type".to_string(), fs.file_system_type.clone()),
                ("Lifecycle".to_string(), fs.lifecycle.clone()),
            ];
            if !fs.failure_details.is_empty() {
                rows.push(("Failure Reason".to_string(), fs.failure_details.clone()));
            }
            rows.push(("Storage Capacity".to_string(), format!("{} GiB", fs.storage_capacity_gib)));
            rows.push(("Storage Type".to_string(), fs.storage_type.clone()));
            let tp = fs.throughput_mbps();
            if tp > 0 {
                rows.push(("Throughput".to_string(), format!("{} MB/s", tp)));
            }
            if !fs.dns_name.is_empty() {
                rows.push(("DNS Name".to_string(), fs.dns_name.clone()));
            }
            if !fs.kms_key_id.is_empty() {
                rows.push(("KMS Key".to_string(), fs.kms_key_id.clone()));
            }
            rows.push(("Created".to_string(), fs.creation_time.clone()));
            rows
        }
        FsxDetailSection::Network => {
            let mut rows = vec![];
            if !fs.vpc_id.is_empty() {
                rows.push(("VPC".to_string(), fs.vpc_id.clone()));
            }
            if !fs.subnet_ids.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Subnets".to_string(), "".to_string()));
                for s in &fs.subnet_ids {
                    rows.push(("  ".to_string(), s.clone()));
                }
            }
            if !fs.network_interface_ids.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Network Interfaces".to_string(), "".to_string()));
                for eni in &fs.network_interface_ids {
                    rows.push(("  ".to_string(), eni.clone()));
                }
            }
            // Type-specific network info
            match &fs.config {
                FsxConfig::Windows(w) => {
                    if !w.preferred_file_server_ip.is_empty() {
                        rows.push(("".to_string(), "".to_string()));
                        rows.push(("Preferred File Server IP".to_string(), w.preferred_file_server_ip.clone()));
                    }
                }
                FsxConfig::Ontap(o) => {
                    if !o.endpoint_ip_address_range.is_empty() {
                        rows.push(("".to_string(), "".to_string()));
                        rows.push(("Endpoint IP Range".to_string(), o.endpoint_ip_address_range.clone()));
                    }
                }
                _ => {}
            }
            rows
        }
        FsxDetailSection::Configuration => {
            match &fs.config {
                FsxConfig::Windows(w) => vec![
                    ("Windows Configuration".to_string(), "".to_string()),
                    ("".to_string(), "".to_string()),
                    ("Deployment Type".to_string(), w.deployment_type.clone()),
                    ("Throughput".to_string(), format!("{} MB/s", w.throughput_capacity_mbps)),
                    ("Active Directory".to_string(), w.active_directory_id.clone()),
                    ("Preferred Server IP".to_string(), w.preferred_file_server_ip.clone()),
                    ("Backup Retention".to_string(), format!("{} days", w.automatic_backup_retention_days)),
                ],
                FsxConfig::Lustre(l) => {
                    let mut rows = vec![
                        ("Lustre Configuration".to_string(), "".to_string()),
                        ("".to_string(), "".to_string()),
                        ("Deployment Type".to_string(), l.deployment_type.clone()),
                    ];
                    if l.per_unit_storage_throughput > 0 {
                        rows.push(("Per-Unit Throughput".to_string(), format!("{} MB/s/TiB", l.per_unit_storage_throughput)));
                    }
                    if !l.mount_name.is_empty() {
                        rows.push(("Mount Name".to_string(), l.mount_name.clone()));
                    }
                    if l.data_repo_count > 0 {
                        rows.push(("Data Repo Associations".to_string(), l.data_repo_count.to_string()));
                    }
                    rows
                }
                FsxConfig::Ontap(o) => vec![
                    ("ONTAP Configuration".to_string(), "".to_string()),
                    ("".to_string(), "".to_string()),
                    ("Deployment Type".to_string(), o.deployment_type.clone()),
                    ("Throughput".to_string(), format!("{} MB/s", o.throughput_capacity_mbps)),
                    ("Endpoint IP Range".to_string(), o.endpoint_ip_address_range.clone()),
                    ("".to_string(), "".to_string()),
                    ("  See the Volumes section (2) for this file system's volumes".to_string(), "".to_string()),
                ],
                FsxConfig::OpenZfs(z) => vec![
                    ("OpenZFS Configuration".to_string(), "".to_string()),
                    ("".to_string(), "".to_string()),
                    ("Deployment Type".to_string(), z.deployment_type.clone()),
                    ("Throughput".to_string(), format!("{} MB/s", z.throughput_capacity_mbps)),
                    ("Root Volume ID".to_string(), z.root_volume_id.clone()),
                    ("Copy Tags to Backups".to_string(), if z.copy_tags_to_backups { "Yes" } else { "No" }.to_string()),
                ],
                FsxConfig::Unknown => vec![
                    ("".to_string(), "Unknown file system type".to_string()),
                ],
            }
        }
        FsxDetailSection::Tags => tag_rows(&fs.tags),
    }
}

/// Detail body for a selected FSx **volume** resource (Volumes sub-tab):
/// describe info + a live snapshot (used/utilization/latency) fetched lazily.
pub fn fsx_volume_section_lines(
    vol: &crate::aws::services::fsx::FsxVolume,
    section: FsxVolumeDetailSection,
    detail: Option<&crate::lazy::Lazy<crate::aws::services::fsx::FsxVolumeSnapshot>>,
) -> Vec<(String, String)> {
    use crate::aws::services::efs::fmt_bytes;

    match section {
        FsxVolumeDetailSection::Overview => {
            let mut rows = vec![
                (String::new(), String::new()),
                ("Volume ID".to_string(), vol.volume_id.clone()),
                ("Name".to_string(), vol.name.clone()),
                ("File System".to_string(), vol.file_system_id.clone()),
                ("Type".to_string(), vol.volume_type.clone()),
                ("Lifecycle".to_string(), vol.lifecycle.clone()),
            ];
            if vol.size_bytes > 0 {
                rows.push(("Size".to_string(), fmt_bytes(vol.size_bytes)));
            }
            if !vol.path.is_empty() {
                rows.push(("Path".to_string(), vol.path.clone()));
            }
            if !vol.svm_id.is_empty() {
                rows.push(("SVM".to_string(), vol.svm_id.clone()));
            }
            for note in &vol.notes {
                rows.push(("  ".to_string(), note.clone()));
            }
            rows
        }
        FsxVolumeDetailSection::Live => {
            let mut rows = vec![(String::new(), String::new())];
            match detail {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(crate::lazy::Lazy::Loaded(s)) => {
                    match s.used_bytes {
                        Some(u) => {
                            let of = if vol.size_bytes > 0 {
                                format!(" / {}", fmt_bytes(vol.size_bytes))
                            } else {
                                String::new()
                            };
                            rows.push(("Used".to_string(), format!("{}{}", fmt_bytes(u), of)));
                        }
                        None => rows.push(("Used".to_string(), "—".to_string())),
                    }
                    if let Some(pct) = s.utilization_pct {
                        let marker = if pct >= 90.0 {
                            "✗ "
                        } else if pct >= 75.0 {
                            "⚠ "
                        } else {
                            ""
                        };
                        rows.push((
                            "Utilization".to_string(),
                            format!("{}{:.1}%", marker, pct),
                        ));
                    }
                    let lat =
                        |label: &str, v: Option<f64>, rows: &mut Vec<(String, String)>| {
                            if let Some(ms) = v {
                                rows.push((label.to_string(), format!("{:.2} ms", ms)));
                            }
                        };
                    lat("Read Latency", s.read_latency_ms, &mut rows);
                    lat("Write Latency", s.write_latency_ms, &mut rows);
                    lat("Metadata Latency", s.metadata_latency_ms, &mut rows);
                }
                Some(crate::lazy::Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push((
                "  press m for usage / latency / tier graphs".to_string(),
                String::new(),
            ));
            rows
        }
        FsxVolumeDetailSection::Tags => tag_rows(&vol.tags),
    }
}

fn fsx_volumes_lines(
    state: Option<&crate::lazy::Lazy<Vec<crate::aws::services::fsx::FsxVolume>>>,
) -> Vec<(String, String)> {
    use crate::aws::services::efs::fmt_bytes;
    let mut rows = vec![("".to_string(), "".to_string())];
    match state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("  Loading volumes…".to_string(), "".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(crate::lazy::Lazy::Loaded(vols)) if vols.is_empty() => {
            rows.push((
                "  No volumes (Windows/Lustre file systems have none)".to_string(),
                "".to_string(),
            ));
        }
        Some(crate::lazy::Lazy::Loaded(vols)) => {
            for (i, v) in vols.iter().enumerate() {
                if i > 0 {
                    rows.push(("".to_string(), "".to_string()));
                }
                // Group header: name + type.
                let title = if v.name.is_empty() { v.volume_id.clone() } else { v.name.clone() };
                rows.push((format!("{}  ({})", title, v.volume_type), String::new()));
                rows.push(("Volume ID".to_string(), v.volume_id.clone()));
                rows.push(("Lifecycle".to_string(), v.lifecycle.clone()));
                if v.size_bytes > 0 {
                    rows.push(("Size".to_string(), fmt_bytes(v.size_bytes)));
                }
                // Live usage (CloudWatch). Utilization gets a ⚠/✗ prefix so the
                // row colours (yellow ≥75%, red ≥90%) — spot the full volume fast.
                if let Some(used) = v.used_bytes {
                    let of = if v.size_bytes > 0 {
                        format!(" / {}", fmt_bytes(v.size_bytes))
                    } else {
                        String::new()
                    };
                    rows.push(("Used".to_string(), format!("{}{}", fmt_bytes(used), of)));
                }
                if let Some(pct) = v.utilization_pct {
                    let marker = if pct >= 90.0 {
                        "✗ "
                    } else if pct >= 75.0 {
                        "⚠ "
                    } else {
                        ""
                    };
                    rows.push(("Utilization".to_string(), format!("{}{:.1}%", marker, pct)));
                }
                if !v.path.is_empty() {
                    rows.push(("Path".to_string(), v.path.clone()));
                }
                if !v.svm_id.is_empty() {
                    rows.push(("SVM".to_string(), v.svm_id.clone()));
                }
                for note in &v.notes {
                    rows.push(("  ".to_string(), note.clone()));
                }
            }
        }
    }
    rows.push(("".to_string(), "".to_string()));
    rows
}

fn fsx_backups_lines(
    state: Option<&crate::lazy::Lazy<Vec<crate::aws::services::fsx::FsxBackup>>>,
) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    match state {
        None | Some(crate::lazy::Lazy::Loading) => {
            rows.push(("  Loading backups…".to_string(), "".to_string()));
        }
        Some(crate::lazy::Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(crate::lazy::Lazy::Loaded(bks)) if bks.is_empty() => {
            rows.push(("  No backups".to_string(), "".to_string()));
        }
        Some(crate::lazy::Lazy::Loaded(bks)) => {
            rows.push(("Backups".to_string(), format!("{} total", bks.len())));
            rows.push(("".to_string(), "".to_string()));
            for (i, b) in bks.iter().enumerate() {
                if i > 0 {
                    rows.push(("".to_string(), "".to_string()));
                }
                rows.push((format!("{}  ({})", b.backup_id, b.backup_type), String::new()));
                rows.push(("Lifecycle".to_string(), b.lifecycle.clone()));
                if b.lifecycle == "CREATING" || b.lifecycle == "PENDING" {
                    rows.push(("Progress".to_string(), format!("{}%", b.progress_percent)));
                }
                if !b.volume_id.is_empty() {
                    rows.push(("Volume".to_string(), b.volume_id.clone()));
                }
                rows.push(("Created".to_string(), b.creation_time.clone()));
            }
        }
    }
    rows.push(("".to_string(), "".to_string()));
    rows
}

fn render_fsx_split(
    app: &App,
    fs: &crate::aws::services::fsx::FsxFileSystem,
    area: ratatui::layout::Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 6, "");
    let mut block = theme::pane_block("FSx File System", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                fs.fs_name.clone(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{} · {} · {} GiB {}", fs.file_system_id, fs.file_system_type, fs.storage_capacity_gib, fs.storage_type),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);

    let sections = [
        ('1', "Details", FsxDetailSection::Details),
        ('2', "Volumes", FsxDetailSection::Volumes),
        ('3', "Backups", FsxDetailSection::Backups),
        ('4', "Network", FsxDetailSection::Network),
        ('5', "Configuration", FsxDetailSection::Configuration),
        ('6', "Tags", FsxDetailSection::Tags),
    ];
    let mut spans: Vec<Span> = vec![Span::raw("  ")];
    for (i, (key, label, section)) in sections.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled("   │   ", Style::default().fg(theme::text_dim())));
        }
        let active = FsxDetailSection::from_index(app.detail_section_index()) == *section;
        if active {
            spans.push(Span::styled(
                key.to_string(),
                Style::default()
                    .fg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default()
                    .fg(Color::Black)
                    .bg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
        } else {
            spans.push(Span::styled(
                key.to_string(),
                Style::default().fg(theme::text_dim()),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default().fg(crate::ui::theme::text_muted()),
            ));
        }
    }
    frame.render_widget(Paragraph::new(Line::from(spans)), chunks[2]);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

// ── CodeCommit Repository split pane ───────────────────────────────────────────

/// Short (8-char) commit id, the git convention.
fn cc_short_id(id: &str) -> String {
    id.chars().take(8).collect()
}

/// The repo pane's lazy states + sibling rows, bundled so the renderer
/// signature stays sane as sections grow.
pub struct CcRepoPaneState<'a> {
    pub extras: Option<&'a Lazy<crate::aws::services::code::CcRepoExtras>>,
    pub branches: Option<&'a Lazy<crate::aws::services::code::CcBranches>>,
    pub commits: Option<&'a Lazy<crate::aws::services::code::CcCommitWalk>>,
    pub commits_branch: &'a str,
    pub readme: Option<&'a Lazy<Option<String>>>,
    /// Open PRs — sibling rows already in the list (zero fetch).
    pub prs: Vec<&'a crate::aws::services::code::CodeCommitPullRequest>,
    /// Recently-closed PRs — lazy per-repo fetch on section enter.
    pub closed_prs: Option<&'a Lazy<Vec<crate::aws::services::code::CodeCommitPullRequest>>>,
}

pub fn code_commit_repo_section_lines(
    repo: &crate::aws::services::code::CodeCommitRepo,
    section: CodeCommitRepoDetailSection,
    st: &CcRepoPaneState<'_>,
) -> Vec<(String, String)> {
    let extras_state = st.extras;
    let branches_state = st.branches;
    let commits_state = st.commits;
    let commits_branch = st.commits_branch;
    let readme_state = st.readme;
    let prs = &st.prs;
    match section {
        CodeCommitRepoDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), repo.name.clone()),
                ("ARN".to_string(), repo.arn.clone()),
                ("Description".to_string(), repo.description.clone()),
                ("Default Branch".to_string(), repo.default_branch.clone()),
                ("".to_string(), "".to_string()),
                ("Clone URLs".to_string(), "".to_string()),
                ("  HTTPS".to_string(), repo.clone_url_http.clone()),
                ("  GRC".to_string(), repo.clone_url_grc.clone()),
                ("  SSH".to_string(), repo.clone_url_ssh.clone()),
                ("".to_string(), "".to_string()),
                ("Last Modified".to_string(), repo.last_modified.clone()),
                ("Account ID".to_string(), repo.account_id.clone()),
                ("".to_string(), "".to_string()),
                ("Tags".to_string(), "".to_string()),
            ];
            match extras_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(x)) => {
                    if let Some(e) = &x.tags_error {
                        rows.extend(error_rows(e));
                    } else if x.tags.is_empty() {
                        rows.push(("  · none".to_string(), "".to_string()));
                    } else {
                        for (k, v) in &x.tags {
                            rows.push((format!("  {}", k), v.clone()));
                        }
                    }
                }
            }
            rows
        }
        CodeCommitRepoDetailSection::Branches => {
            let mut rows = Vec::new();
            match branches_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(b)) => {
                    rows.push((
                        format!("Branches ({})", b.branches.len() + b.unresolved),
                        "".to_string(),
                    ));
                    if b.branches.is_empty() {
                        rows.push(("".to_string(), "No branches (empty repository)".to_string()));
                    }
                    for br in &b.branches {
                        let mut tip = String::new();
                        if br.is_default {
                            tip.push_str("default · ");
                        }
                        tip.push_str(&cc_short_id(&br.tip_commit_id));
                        if !br.subject.is_empty() {
                            tip.push_str(&format!(" {}", clip_inline(&br.subject, 48)));
                        }
                        if !br.date.is_empty() {
                            tip.push_str(&format!(" · {}", br.date));
                        }
                        rows.push((format!("  {}", br.name), tip));
                    }
                    if b.unresolved > 0 {
                        rows.push((
                            format!(
                                "  · {} more branches not shown (tip lookups capped at {})",
                                b.unresolved,
                                crate::aws::services::code::MAX_CC_BRANCHES
                            ),
                            "".to_string(),
                        ));
                    }
                    if !b.branches.is_empty() {
                        rows.push(("".to_string(), "".to_string()));
                        rows.push((
                            "  · ⏎ on a branch opens its commits".to_string(),
                            "".to_string(),
                        ));
                    }
                }
            }
            rows
        }
        CodeCommitRepoDetailSection::Commits => {
            let mut rows = vec![
                ("Branch".to_string(), commits_branch.to_string()),
                ("".to_string(), "".to_string()),
            ];
            match commits_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(walk)) => {
                    rows.push((
                        format!(
                            "Commits ({}{})",
                            walk.commits.len(),
                            if walk.truncated { "+" } else { "" }
                        ),
                        "".to_string(),
                    ));
                    for c in &walk.commits {
                        let mut v = clip_inline(&c.subject, 56);
                        if !c.author.is_empty() {
                            v.push_str(&format!(" · {}", c.author));
                        }
                        if !c.date.is_empty() {
                            v.push_str(&format!(" · {}", c.date));
                        }
                        rows.push((format!("  {}", cc_short_id(&c.id)), v));
                    }
                    rows.push(("".to_string(), "".to_string()));
                    if walk.truncated {
                        rows.push((
                            format!(
                                "  · older history not walked (capped at {})",
                                crate::aws::services::code::MAX_CC_COMMITS
                            ),
                            "".to_string(),
                        ));
                    }
                    rows.push((
                        "  · e opens the full log with commit bodies".to_string(),
                        "".to_string(),
                    ));
                }
            }
            rows
        }
        CodeCommitRepoDetailSection::PullRequests => {
            let mut rows = vec![(format!("Open ({})", prs.len()), "".to_string())];
            if prs.is_empty() {
                rows.push(("".to_string(), "No open pull requests".to_string()));
            }
            for p in prs {
                // Digits-only `#<id>` key — the shape `cc_repo_pr_row_jump_target`
                // keys on (only these rows exist on the Pull Requests sub-tab).
                rows.push((
                    format!("  #{}", p.pr_id),
                    format!(
                        "{} · {} · {}",
                        clip_inline(&p.title, 48),
                        p.author,
                        p.created
                    ),
                ));
            }
            if !prs.is_empty() {
                rows.push((
                    "  · ⏎ on a row opens the pull request".to_string(),
                    "".to_string(),
                ));
            }
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Recently Closed".to_string(), "".to_string()));
            match st.closed_prs {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(closed)) => {
                    if closed.is_empty() {
                        rows.push(("  · none".to_string(), "".to_string()));
                    }
                    for p in closed {
                        // The `(MERGED)` suffix keeps the digits-only jump
                        // classifier from firing — closed PRs have no row on
                        // the sub-tab to jump to.
                        rows.push((
                            format!("  #{} ({})", p.pr_id, p.status_label()),
                            format!(
                                "{} · {} · {}",
                                clip_inline(&p.title, 44),
                                if p.merged_by.is_empty() {
                                    p.author.clone()
                                } else {
                                    format!("merged by {}", p.merged_by)
                                },
                                p.last_activity
                            ),
                        ));
                    }
                }
            }
            rows
        }
        CodeCommitRepoDetailSection::Triggers => {
            let mut rows = Vec::new();
            match extras_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(x)) => {
                    if let Some(e) = &x.triggers_error {
                        rows.extend(error_rows(e));
                    } else if x.triggers.is_empty() {
                        rows.push(("".to_string(), "No triggers configured".to_string()));
                    } else {
                        for t in &x.triggers {
                            rows.push((t.name.clone(), "".to_string()));
                            rows.push(("  Destination".to_string(), t.destination_arn.clone()));
                            rows.push((
                                "  Events".to_string(),
                                if t.events.is_empty() {
                                    "-".to_string()
                                } else {
                                    t.events.join(", ")
                                },
                            ));
                            rows.push((
                                "  Branches".to_string(),
                                if t.branches.is_empty() {
                                    "all branches".to_string()
                                } else {
                                    t.branches.join(", ")
                                },
                            ));
                            if !t.custom_data.is_empty() {
                                rows.push(("  Custom Data".to_string(), t.custom_data.clone()));
                            }
                            rows.push(("".to_string(), "".to_string()));
                        }
                    }
                }
            }
            rows
        }
        CodeCommitRepoDetailSection::Readme => match readme_state {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading README…".to_string())]
            }
            Some(Lazy::Loaded(None)) => {
                vec![("".to_string(), "No README found".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(Some(content))) => {
                content
                    .lines()
                    .map(|line| (format!("  {}", line), "".to_string()))
                    .collect()
            }
        },
    }
}

fn render_code_commit_repo_split(
    app: &App,
    repo: &crate::aws::services::code::CodeCommitRepo,
    area: ratatui::layout::Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(
        app,
        focused,
        crate::aws::services::code::CODE_COMMIT_SECTIONS.len(),
        "",
    );
    let mut block = theme::pane_block("Repository", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                repo.name.clone(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                if repo.description.is_empty() {
                    repo.default_branch.clone()
                } else {
                    repo.description.clone()
                },
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);

    // Section tabs
    let sections = descriptor_tabs(app, &crate::aws::services::code::CODE_COMMIT_SECTIONS);
    let mut spans: Vec<Span> = vec![Span::raw("  ")];
    for (i, (key, label, section)) in sections.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled("   │   ", Style::default().fg(theme::text_dim())));
        }
        let active = *section;
        if active {
            spans.push(Span::styled(
                key.to_string(),
                Style::default()
                    .fg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default()
                    .fg(Color::Black)
                    .bg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
        } else {
            spans.push(Span::styled(
                key.to_string(),
                Style::default().fg(theme::text_dim()),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default().fg(crate::ui::theme::text_muted()),
            ));
        }
    }
    frame.render_widget(Paragraph::new(Line::from(spans)), chunks[2]);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

// ── CodeCommit Pull Request split pane ─────────────────────────────────────────

pub fn cc_pr_section_lines(
    pr: &crate::aws::services::code::CodeCommitPullRequest,
    section: crate::aws::services::code::CcPrDetailSection,
    approvals_state: Option<&Lazy<crate::aws::services::code::CcPrApprovals>>,
    events_state: Option<&Lazy<Vec<crate::aws::services::code::CcPrEvent>>>,
    comments_state: Option<&Lazy<crate::aws::services::code::CcPrComments>>,
    diff_state: Option<&Lazy<crate::aws::services::code::CcPrDiff>>,
) -> Vec<(String, String)> {
    use crate::aws::services::code::CcPrDetailSection as S;
    match section {
        S::Overview => {
            let mut rows = vec![
                ("Repository".to_string(), pr.repo.clone()),
                ("Pull Request".to_string(), format!("#{}", pr.pr_id)),
                ("Title".to_string(), pr.title.clone()),
                ("Status".to_string(), pr.status_label().to_string()),
                ("Author".to_string(), pr.author.clone()),
                ("Created".to_string(), pr.created.clone()),
                ("Last Activity".to_string(), pr.last_activity.clone()),
                ("".to_string(), "".to_string()),
                ("Branches".to_string(), "".to_string()),
                (
                    "  Source → Destination".to_string(),
                    format!("{} → {}", pr.source_ref, pr.dest_ref),
                ),
                (
                    "  Source Tip".to_string(),
                    pr.source_commit.chars().take(8).collect(),
                ),
                (
                    "  Merge Base".to_string(),
                    pr.merge_base.chars().take(8).collect(),
                ),
            ];
            if pr.is_merged || !pr.merged_by.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Merge".to_string(), "".to_string()));
                rows.push(("  Merged".to_string(), if pr.is_merged { "✓ yes" } else { "no" }.to_string()));
                if !pr.merged_by.is_empty() {
                    rows.push(("  Merged By".to_string(), pr.merged_by.clone()));
                }
                if !pr.merge_option.is_empty() {
                    rows.push(("  Strategy".to_string(), pr.merge_option.clone()));
                }
                if !pr.merge_commit_id.is_empty() {
                    rows.push((
                        "  Merge Commit".to_string(),
                        pr.merge_commit_id.chars().take(8).collect(),
                    ));
                }
            }
            if !pr.description.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Description".to_string(), "".to_string()));
                for line in pr.description.lines().take(20) {
                    rows.push((format!("  {}", line), "".to_string()));
                }
            }
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Approvals".to_string(), "".to_string()));
            match approvals_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(a)) => {
                    if let Some(e) = &a.eval_error {
                        rows.extend(error_rows(e));
                    } else if pr.approval_rule_names.is_empty() {
                        rows.push(("  · no approval rules".to_string(), "".to_string()));
                    } else {
                        rows.push((
                            "  Approved".to_string(),
                            if a.approved {
                                "✓ yes".to_string()
                            } else if a.overridden {
                                "⚠ overridden".to_string()
                            } else {
                                "✗ not yet".to_string()
                            },
                        ));
                        for r in &a.satisfied {
                            rows.push((format!("  {}", r), "✓ satisfied".to_string()));
                        }
                        for r in &a.not_satisfied {
                            rows.push((format!("  {}", r), "✗ not satisfied".to_string()));
                        }
                    }
                    if let Some(e) = &a.states_error {
                        rows.extend(error_rows(e));
                    } else {
                        for (user, state) in &a.approvals {
                            rows.push((format!("  {}", user), state.clone()));
                        }
                    }
                }
            }
            rows
        }
        S::Activity => {
            let mut rows = Vec::new();
            match events_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(events)) => {
                    rows.push((format!("Activity ({})", events.len()), "".to_string()));
                    if events.is_empty() {
                        rows.push(("".to_string(), "No events".to_string()));
                    }
                    for e in events {
                        let mut v = e.kind.clone();
                        if !e.detail.is_empty() {
                            v.push_str(&format!(" · {}", e.detail));
                        }
                        if !e.actor.is_empty() {
                            v.push_str(&format!(" · {}", e.actor));
                        }
                        rows.push((format!("  {}", e.date), v));
                    }
                }
            }
            rows
        }
        S::Comments => {
            let mut rows = Vec::new();
            match comments_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(c)) => {
                    rows.push((
                        format!(
                            "Comments ({} in {} thread(s))",
                            c.total_comments,
                            c.threads.len()
                        ),
                        "".to_string(),
                    ));
                    if c.threads.is_empty() {
                        rows.push(("".to_string(), "No comments".to_string()));
                    }
                    for t in &c.threads {
                        rows.push(("".to_string(), "".to_string()));
                        if t.path.is_empty() {
                            rows.push(("General".to_string(), "".to_string()));
                        } else if t.line.is_empty() {
                            rows.push((t.path.clone(), "".to_string()));
                        } else {
                            rows.push((format!("{}:{}", t.path, t.line), "".to_string()));
                        }
                        for cm in &t.comments {
                            if cm.deleted {
                                rows.push(("  · (comment deleted)".to_string(), "".to_string()));
                                continue;
                            }
                            rows.push((
                                format!("  {} · {}", cm.author, cm.date),
                                "".to_string(),
                            ));
                            for line in cm.content.lines() {
                                rows.push((format!("    {}", line), "".to_string()));
                            }
                        }
                    }
                    if c.truncated {
                        rows.push(("".to_string(), "".to_string()));
                        rows.push((
                            format!(
                                "  · thread list truncated at {}",
                                crate::aws::services::code::MAX_PR_COMMENT_THREADS
                            ),
                            "".to_string(),
                        ));
                    }
                }
            }
            rows
        }
        S::Changes => {
            let mut rows = Vec::new();
            match diff_state {
                None | Some(Lazy::Loading) => {
                    rows.push(("".to_string(), "Loading…".to_string()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded(d)) => {
                    rows.push((
                        format!(
                            "Changed Files ({}{})",
                            d.entries.len(),
                            if d.truncated { "+" } else { "" }
                        ),
                        format!(
                            "{} → {}",
                            d.before.chars().take(8).collect::<String>(),
                            d.after.chars().take(8).collect::<String>()
                        ),
                    ));
                    if d.entries.is_empty() {
                        rows.push(("".to_string(), "No differences".to_string()));
                    }
                    for e in &d.entries {
                        let mark = match e.change.as_str() {
                            "A" => "+",
                            "D" => "−",
                            _ => "~",
                        };
                        let label = if !e.old_path.is_empty() && e.old_path != e.path {
                            format!("{} → {}", e.old_path, e.path)
                        } else {
                            e.path.clone()
                        };
                        rows.push((format!("  {} {}", mark, label), "".to_string()));
                    }
                    rows.push(("".to_string(), "".to_string()));
                    if d.truncated {
                        rows.push((
                            format!(
                                "  · file list truncated at {}",
                                crate::aws::services::code::MAX_PR_DIFF_FILES
                            ),
                            "".to_string(),
                        ));
                    }
                    rows.push((
                        "  · e builds the unified patch and opens it in $EDITOR".to_string(),
                        "".to_string(),
                    ));
                }
            }
            rows
        }
    }
}

fn render_cc_pr_split(
    app: &App,
    pr: &crate::aws::services::code::CodeCommitPullRequest,
    area: ratatui::layout::Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(
        app,
        focused,
        crate::aws::services::code::CC_PR_SECTIONS.len(),
        "",
    );
    let mut block = theme::pane_block("Pull Request", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let status_color = match pr.status_label() {
        "OPEN" => theme::warning(),
        "MERGED" => theme::success(),
        _ => theme::text_dim(),
    };
    let header_lines = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{} #{}", pr.repo, pr.pr_id),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
            Span::raw("  "),
            Span::styled(
                pr.status_label().to_string(),
                Style::default().fg(status_color).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(pr.title.clone(), Style::default().fg(theme::text_dim())),
        ]),
        Line::raw(""),
    ];
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::code::CC_PR_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

// ── CodeBuild Project split pane ───────────────────────────────────────────────

pub fn code_build_section_lines(
    proj: &crate::aws::services::code::CodeBuildProject,
    section: CodeBuildDetailSection,
    builds_state: Option<&Lazy<Vec<crate::aws::services::code::CodeBuildBuild>>>,
    buildspec_state: Option<&Lazy<crate::aws::services::code::BuildspecResult>>,
) -> Vec<(String, String)> {
    match section {
        CodeBuildDetailSection::Details => code_build_details_lines(proj),
        CodeBuildDetailSection::Buildspec => code_build_buildspec_lines(proj, buildspec_state),
        CodeBuildDetailSection::Builds => code_build_builds_lines(builds_state),
        CodeBuildDetailSection::Environment => code_build_env_lines(proj),
        CodeBuildDetailSection::Tags => tag_rows(&proj.tags),
    }
}

fn code_build_details_lines(
    proj: &crate::aws::services::code::CodeBuildProject,
) -> Vec<(String, String)> {
    let yesno = |b: bool| if b { "Yes" } else { "No" }.to_string();
    let mut rows: Vec<(String, String)> = vec![
        ("Name".to_string(), proj.name.clone()),
        ("ARN".to_string(), proj.arn.clone()),
    ];
    if !proj.description.is_empty() {
        rows.push(("Description".to_string(), proj.description.clone()));
    }

    // Source
    rows.push(("".to_string(), "".to_string()));
    rows.push(("Source".to_string(), "".to_string()));
    rows.push(("  Type".to_string(), proj.source_type.clone()));
    if !proj.source_location.is_empty() {
        rows.push(("  Location".to_string(), proj.source_location.clone()));
    }
    if !proj.source_version.is_empty() {
        rows.push(("  Version".to_string(), proj.source_version.clone()));
    }
    let bs = if proj.buildspec.trim().is_empty() {
        "buildspec.yml (source root)".to_string()
    } else if proj.buildspec_is_inline() {
        "inline → press 2".to_string()
    } else {
        proj.buildspec.clone()
    };
    rows.push(("  Buildspec".to_string(), bs));

    // Environment
    rows.push(("".to_string(), "".to_string()));
    rows.push(("Environment".to_string(), "".to_string()));
    rows.push(("  Type".to_string(), proj.environment_type.clone()));
    rows.push(("  Compute".to_string(), proj.compute_type.clone()));
    rows.push(("  Image".to_string(), proj.image.clone()));
    rows.push(("  Privileged".to_string(), yesno(proj.privileged_mode)));
    rows.push(("  Env Vars".to_string(), proj.env_vars.len().to_string()));

    // Artifacts
    if !proj.artifacts_type.is_empty() {
        rows.push(("".to_string(), "".to_string()));
        rows.push(("Artifacts".to_string(), "".to_string()));
        rows.push(("  Type".to_string(), proj.artifacts_type.clone()));
        if !proj.artifacts_location.is_empty() {
            rows.push(("  Location".to_string(), proj.artifacts_location.clone()));
        }
        if !proj.artifacts_name.is_empty() {
            rows.push(("  Name".to_string(), proj.artifacts_name.clone()));
        }
    }

    // Cache
    if !proj.cache_type.is_empty() && proj.cache_type != "NO_CACHE" {
        rows.push(("".to_string(), "".to_string()));
        rows.push(("Cache".to_string(), "".to_string()));
        rows.push(("  Type".to_string(), proj.cache_type.clone()));
        if !proj.cache_location.is_empty() {
            rows.push(("  Location".to_string(), proj.cache_location.clone()));
        }
    }

    // VPC
    if !proj.vpc_id.is_empty() {
        rows.push(("".to_string(), "".to_string()));
        rows.push(("VPC".to_string(), "".to_string()));
        rows.push(("  VPC".to_string(), proj.vpc_id.clone()));
        if !proj.vpc_subnets.is_empty() {
            rows.push(("  Subnets".to_string(), proj.vpc_subnets.join(", ")));
        }
        if !proj.vpc_security_groups.is_empty() {
            rows.push((
                "  Security Groups".to_string(),
                proj.vpc_security_groups.join(", "),
            ));
        }
    }

    // Logs
    rows.push(("".to_string(), "".to_string()));
    rows.push(("Logs".to_string(), "".to_string()));
    if !proj.log_cw_status.is_empty() {
        rows.push(("  CloudWatch".to_string(), proj.log_cw_status.clone()));
        if !proj.log_cw_group.is_empty() {
            rows.push(("  Group".to_string(), proj.log_cw_group.clone()));
        }
        if !proj.log_cw_stream.is_empty() {
            rows.push(("  Stream Prefix".to_string(), proj.log_cw_stream.clone()));
        }
    }
    if !proj.log_s3_status.is_empty() && proj.log_s3_status != "DISABLED" {
        rows.push(("  S3".to_string(), proj.log_s3_status.clone()));
        if !proj.log_s3_location.is_empty() {
            rows.push(("  S3 Location".to_string(), proj.log_s3_location.clone()));
        }
    }
    rows.push(("  Tail latest".to_string(), "press t".to_string()));

    // Configuration
    rows.push(("".to_string(), "".to_string()));
    rows.push(("Configuration".to_string(), "".to_string()));
    rows.push(("  Service Role".to_string(), proj.service_role.clone()));
    rows.push(("  Timeout (min)".to_string(), proj.timeout_minutes.to_string()));
    if proj.queued_timeout_minutes > 0 {
        rows.push((
            "  Queued Timeout".to_string(),
            format!("{} min", proj.queued_timeout_minutes),
        ));
    }
    if let Some(limit) = proj.concurrent_build_limit {
        rows.push(("  Concurrent Limit".to_string(), limit.to_string()));
    }
    rows.push(("  Badge".to_string(), yesno(proj.badge_enabled)));
    if !proj.created.is_empty() {
        rows.push(("  Created".to_string(), proj.created.clone()));
    }
    rows.push(("  Last Modified".to_string(), proj.last_modified.clone()));

    rows
}

fn code_build_buildspec_lines(
    proj: &crate::aws::services::code::CodeBuildProject,
    buildspec_state: Option<&Lazy<crate::aws::services::code::BuildspecResult>>,
) -> Vec<(String, String)> {
    // Inline buildspec — render it directly.
    if proj.buildspec_is_inline() {
        return buildspec_body_lines("", &proj.buildspec);
    }

    // File-path (or default) buildspec — pulled from the source repo lazily.
    let path = if proj.buildspec.trim().is_empty() {
        "buildspec.yml".to_string()
    } else {
        proj.buildspec.clone()
    };
    use crate::aws::services::code::BuildspecResult;
    match buildspec_state {
        None | Some(Lazy::Loading) => vec![
            ("Buildspec file".to_string(), path),
            ("".to_string(), "".to_string()),
            ("".to_string(), "Fetching from source repo…".to_string()),
        ],
        Some(Lazy::Loaded(BuildspecResult::Content(text))) => {
            let mut rows = vec![("Buildspec file".to_string(), path), ("".to_string(), "".to_string())];
            rows.extend(buildspec_body_lines(
                "from repo",
                text,
            ));
            rows
        }
        Some(Lazy::Loaded(BuildspecResult::NotFound)) => vec![
            ("Buildspec file".to_string(), path),
            ("".to_string(), "".to_string()),
            ("⚠".to_string(), "Not found in the source repo".to_string()),
        ],
        Some(Lazy::Loaded(BuildspecResult::Unsupported(note))) => vec![
            ("Buildspec file".to_string(), path),
            ("".to_string(), "".to_string()),
            ("".to_string(), note.clone()),
        ],
        Some(Lazy::Error(e)) => {
            let mut rows = vec![("Buildspec file".to_string(), path)];
            rows.extend(error_rows(e));
            rows
        }
    }
}

fn buildspec_body_lines(hint: &str, content: &str) -> Vec<(String, String)> {
    let mut rows: Vec<(String, String)> = vec![
        ("".to_string(), hint.to_string()),
        ("".to_string(), "".to_string()),
    ];
    // Plain content rows (leading-space key) preserve the YAML's own indentation.
    for line in content.lines() {
        rows.push((format!(" {}", line), "".to_string()));
    }
    rows
}

fn code_build_builds_lines(builds_state: Option<&Lazy<Vec<crate::aws::services::code::CodeBuildBuild>>>) -> Vec<(String, String)> {
    code_build_builds_lines_indexed(builds_state).0
}

/// Build the Builds-section rows and, alongside, the body-line index at which
/// each build's block starts — so `t` can map the detail cursor to a build.
pub fn code_build_builds_lines_indexed(
    builds_state: Option<&Lazy<Vec<crate::aws::services::code::CodeBuildBuild>>>,
) -> (Vec<(String, String)>, Vec<usize>) {
    match builds_state {
        None | Some(Lazy::Loading) => {
            (vec![("".to_string(), "Loading builds…".to_string())], vec![])
        }
        Some(Lazy::Error(e)) => (
            error_rows(e),
            vec![],
        ),
        Some(Lazy::Loaded(builds)) => {
            if builds.is_empty() {
                return (vec![("".to_string(), "No builds found".to_string())], vec![]);
            }
            let mut rows: Vec<(String, String)> = vec![
                (
                    "".to_string(),
                    "j/k to a build · t tails its CloudWatch logs".to_string(),
                ),
                ("".to_string(), "".to_string()),
            ];
            let mut starts: Vec<usize> = Vec::with_capacity(builds.len());
            for (i, b) in builds.iter().enumerate() {
                if i > 0 {
                    rows.push(("".to_string(), "".to_string()));
                }
                starts.push(rows.len());
                let duration = if b.duration_secs > 0 {
                    format!("{}m {}s", b.duration_secs / 60, b.duration_secs % 60)
                } else {
                    "—".to_string()
                };
                // Group header (empty value, no leading space) so `[[`/`]]`
                // anchor on it and jump build-to-build; status rides in the
                // header label so pass/fail shows at a glance while jumping.
                rows.push((
                    format!("Build #{} — {}", b.build_number, b.status),
                    "".to_string(),
                ));
                rows.push(("  Started".to_string(), b.start_time.clone()));
                if !b.end_time.is_empty() {
                    rows.push(("  Ended".to_string(), b.end_time.clone()));
                }
                rows.push(("  Duration".to_string(), duration));
                if !b.initiator.is_empty() {
                    rows.push(("  Initiator".to_string(), b.initiator.clone()));
                }
                if !b.source_version.is_empty() {
                    rows.push(("  Source Version".to_string(), b.source_version.clone()));
                }
                if !b.resolved_source_version.is_empty()
                    && b.resolved_source_version != b.source_version
                {
                    rows.push(("  Resolved".to_string(), b.resolved_source_version.clone()));
                }
                if !b.log_group.is_empty() {
                    rows.push(("  Log Group".to_string(), b.log_group.clone()));
                    rows.push(("  Log Stream".to_string(), b.log_stream.clone()));
                }
                // Phases
                if !b.phases.is_empty() {
                    rows.push(("  Phases".to_string(), "".to_string()));
                    for p in &b.phases {
                        if p.phase_type.is_empty() {
                            continue;
                        }
                        let dur = if p.duration_secs > 0 {
                            format!("{}s", p.duration_secs)
                        } else {
                            "—".to_string()
                        };
                        rows.push((
                            format!("    {}", p.phase_type),
                            format!("{} ({})", p.status, dur),
                        ));
                    }
                }
            }
            (rows, starts)
        }
    }
}

fn code_build_env_lines(proj: &crate::aws::services::code::CodeBuildProject) -> Vec<(String, String)> {
    if proj.env_vars.is_empty() {
        return vec![("".to_string(), "No environment variables".to_string())];
    }
    // PARAMETER_STORE / SECRETS_MANAGER values are references (param name /
    // secret id), not the secret itself — safe to display, tagged by source.
    proj.env_vars
        .iter()
        .map(|v| {
            let label = match v.var_type.as_str() {
                "PARAMETER_STORE" => format!("{} (SSM)", v.name),
                "SECRETS_MANAGER" => format!("{} (Secret)", v.name),
                _ => v.name.clone(),
            };
            (label, v.value.clone())
        })
        .collect()
}

fn render_code_build_split(
    app: &App,
    proj: &crate::aws::services::code::CodeBuildProject,
    area: ratatui::layout::Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 5, "");
    let mut block = theme::pane_block("Build Project", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                proj.name.clone(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{} · {}", proj.source_type, proj.compute_type),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);

    let sections = descriptor_tabs(app, &crate::aws::services::code::CODE_BUILD_SECTIONS);
    let mut spans: Vec<Span> = vec![Span::raw("  ")];
    for (i, (key, label, section)) in sections.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled("   │   ", Style::default().fg(theme::text_dim())));
        }
        let active = *section;
        if active {
            spans.push(Span::styled(
                key.to_string(),
                Style::default()
                    .fg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default()
                    .fg(Color::Black)
                    .bg(theme::aws_orange())
                    .add_modifier(Modifier::BOLD),
            ));
        } else {
            spans.push(Span::styled(
                key.to_string(),
                Style::default().fg(theme::text_dim()),
            ));
            spans.push(Span::styled(
                format!(" {} ", label),
                Style::default().fg(crate::ui::theme::text_muted()),
            ));
        }
    }
    frame.render_widget(Paragraph::new(Line::from(spans)), chunks[2]);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

// ── CodePipeline split pane ────────────────────────────────────────────────────

pub fn code_pipeline_section_lines(
    p: &crate::aws::services::code::CodePipeline,
    section: CodePipelineDetailSection,
    details_state: Option<&Lazy<crate::aws::services::code::CodePipelineDetails>>,
    executions: &[&crate::aws::services::code::CodePipelineExecution],
) -> Vec<(String, String)> {
    match section {
        CodePipelineDetailSection::Stages => code_pipeline_stages_lines(p, details_state),
        CodePipelineDetailSection::Executions => code_pipeline_executions_lines(executions),
        // `ListPipelines` returns no tags — they ride the details fetch.
        CodePipelineDetailSection::Tags => match details_state {
            None | Some(Lazy::Loading) => vec![("".to_string(), "Loading…".to_string())],
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(d)) => tag_rows(&d.tags),
        },
    }
}

fn code_pipeline_stages_lines(
    p: &crate::aws::services::code::CodePipeline,
    details_state: Option<&Lazy<crate::aws::services::code::CodePipelineDetails>>,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Name".to_string(), p.name.clone()),
        ("Type".to_string(), p.pipeline_type.clone()),
        ("Version".to_string(), p.version.to_string()),
        ("Created".to_string(), p.created.clone()),
        ("Updated".to_string(), p.updated.clone()),
    ];

    match details_state {
        None | Some(Lazy::Loading) => {
            rows.push(("".to_string(), "".to_string()));
            rows.push(("".to_string(), "Loading pipeline…".to_string()));
        }
        Some(Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(Lazy::Loaded(details)) => {
            if !details.execution_mode.is_empty() {
                rows.push(("Execution Mode".to_string(), details.execution_mode.clone()));
            }
            if !details.role_arn.is_empty() {
                rows.push(("Role ARN".to_string(), details.role_arn.clone()));
            }
            // Artifact store
            if !details.artifact_store_location.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Artifact Store".to_string(), "".to_string()));
                rows.push(("  Type".to_string(), details.artifact_store_type.clone()));
                rows.push(("  Location".to_string(), details.artifact_store_location.clone()));
                if !details.artifact_store_kms.is_empty() {
                    rows.push(("  KMS Key".to_string(), details.artifact_store_kms.clone()));
                }
            }
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Stages".to_string(), "".to_string()));
            for stage in &details.stages {
                let status_str = if stage.status.is_empty() {
                    String::new()
                } else {
                    format!(" [{}]", stage.status)
                };
                rows.push(("".to_string(), "".to_string()));
                rows.push((format!("  ▸ {}{}", stage.name, status_str), "".to_string()));
                for action in &stage.actions {
                    let order = action
                        .run_order
                        .map(|o| format!("  ·  run order {}", o))
                        .unwrap_or_default();
                    rows.push((
                        format!("    {}", action.name),
                        format!("{} / {}{}", action.category, action.provider, order),
                    ));
                    // Jumpable target row (the key is read by code_row_jump_target).
                    if let Some((label, value)) = &action.target {
                        rows.push((format!("      {}", label), value.clone()));
                    }
                    if !action.region.is_empty() {
                        rows.push(("      Region".to_string(), action.region.clone()));
                    }
                    if !action.namespace.is_empty() {
                        rows.push(("      Namespace".to_string(), action.namespace.clone()));
                    }
                    if !action.role_arn.is_empty() {
                        rows.push(("      Role".to_string(), action.role_arn.clone()));
                    }
                    if !action.input_artifacts.is_empty() {
                        rows.push((
                            "      Input".to_string(),
                            action.input_artifacts.join(", "),
                        ));
                    }
                    if !action.output_artifacts.is_empty() {
                        rows.push((
                            "      Output".to_string(),
                            action.output_artifacts.join(", "),
                        ));
                    }
                    // The rest of the action configuration verbatim — this is
                    // where a CFN template path or an ECS file name lives.
                    for (k, v) in &action.configuration {
                        rows.push((format!("      {}", k), v.clone()));
                    }
                }
            }
        }
    }
    rows
}

/// The pipeline's runs, filtered from sibling rows already in `resources` (the
/// Executions sub-tab loaded them) — no fetch, and every `Execution` row jumps
/// into that run's own pane.
fn code_pipeline_executions_lines(
    executions: &[&crate::aws::services::code::CodePipelineExecution],
) -> Vec<(String, String)> {
    if executions.is_empty() {
        return vec![
            ("".to_string(), "No recent executions".to_string()),
            (
                "".to_string(),
                "  · runs are listed on the Executions sub-tab (6)".to_string(),
            ),
        ];
    }

    let running = executions.iter().filter(|e| e.is_running()).count();
    let failed = executions.iter().filter(|e| e.failed()).count();
    let mut rows = vec![(
        format!(
            "Recent Executions ({}{}{})",
            executions.len(),
            if running > 0 {
                format!(", {} running", running)
            } else {
                String::new()
            },
            if failed > 0 {
                format!(", {} failed", failed)
            } else {
                String::new()
            }
        ),
        String::new(),
    )];

    for ex in executions {
        rows.push(("".to_string(), "".to_string()));
        // Group header (empty value) so `[[`/`]]` jump execution-to-execution.
        rows.push((format!("{} — {}", ex.execution_id, ex.status), String::new()));
        rows.push(("  Execution".to_string(), ex.execution_id.clone()));
        rows.push(("  Started".to_string(), ex.start_time.clone()));
        if ex.duration_secs > 0 {
            rows.push(("  Duration".to_string(), ex.duration_label()));
        }
        if !ex.trigger.is_empty() {
            let t = if ex.trigger_detail.is_empty() {
                ex.trigger.clone()
            } else {
                format!("{} · {}", ex.trigger, ex.trigger_detail)
            };
            rows.push(("  Trigger".to_string(), t));
        }
        for rev in &ex.source_revisions {
            rows.push(("  Revision".to_string(), rev.clone()));
        }
    }
    rows
}

