fn render_resource_group_split(app: &App, rg: &RgGroup, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");

    let mut block = theme::pane_block("Resource Group", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = build_resource_group_header_lines(rg);
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);
    render_resource_group_section_tabs(app, chunks[2], frame);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn build_resource_group_header_lines(rg: &RgGroup) -> Vec<Line<'static>> {
    let mut lines = vec![Line::raw("")];
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            rg.name.clone(),
            Style::default()
                .fg(crate::ui::theme::text_primary())
                .add_modifier(Modifier::BOLD),
        ),
    ]));
    if !rg.description.is_empty() {
        lines.push(Line::from(vec![
            Span::raw("  "),
            Span::styled(rg.description.clone(), Style::default().fg(theme::text_dim())),
        ]));
    }
    lines.push(Line::raw(""));
    lines
}

fn render_resource_group_section_tabs(app: &App, area: Rect, frame: &mut Frame) {
    render_section_tab_bar(
        app,
        area,
        frame,
        &descriptor_tabs(app, &crate::aws::services::resource_groups::RESOURCE_GROUP_SECTIONS),
    );
}

pub fn resource_group_section_lines(
    rg: &RgGroup,
    section: ResourceGroupDetailSection,
    query_state: Option<&Lazy<crate::aws::services::resource_groups::ResourceGroupQuery>>,
    resources_state: Option<&Lazy<Vec<crate::aws::services::resource_groups::ResourceGroupMember>>>,
    tags_state: Option<&Lazy<std::collections::HashMap<String, String>>>,
) -> Vec<(String, String)> {
    match section {
        ResourceGroupDetailSection::Details => rg_details_lines(rg, query_state),
        ResourceGroupDetailSection::Query => rg_query_lines(query_state),
        ResourceGroupDetailSection::Resources => rg_resources_lines(resources_state),
        ResourceGroupDetailSection::Tags => rg_tags_lines(tags_state),
    }
}

fn rg_details_lines(
    rg: &RgGroup,
    query_state: Option<&Lazy<crate::aws::services::resource_groups::ResourceGroupQuery>>,
) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Name".to_string(), rg.name.clone()),
        ("ARN".to_string(), rg.arn.clone()),
    ];
    if !rg.description.is_empty() {
        rows.push(("Description".to_string(), rg.description.clone()));
    }
    rows.push(("".to_string(), "".to_string()));
    let qt = match query_state {
        Some(Lazy::Loaded(q)) => q.query_type.clone(),
        Some(Lazy::Loading) => "Loading…".to_string(),
        Some(Lazy::Error(e)) => format!("⚠ {}", e),
        None => "…".to_string(),
    };
    rows.push(("Query Type".to_string(), qt));
    rows
}

fn rg_query_lines(query_state: Option<&Lazy<crate::aws::services::resource_groups::ResourceGroupQuery>>) -> Vec<(String, String)> {
    match query_state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading query…".to_string())]
        }
        Some(Lazy::Error(e)) => {
            error_rows(e)
        }
        Some(Lazy::Loaded(q)) => {
            let mut rows = vec![("Type".to_string(), q.query_type.clone())];
            rows.push(("".to_string(), "".to_string()));
            // Pretty-print the query JSON if possible
            if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(&q.query) {
                if let Ok(pretty) = serde_json::to_string_pretty(&parsed) {
                    for line in pretty.lines() {
                        rows.push(("".to_string(), line.to_string()));
                    }
                } else {
                    rows.push(("Query".to_string(), q.query.clone()));
                }
            } else {
                // Not JSON (e.g. CFN stack ARN) — show as-is
                rows.push(("Query".to_string(), q.query.clone()));
            }
            rows
        }
    }
}

fn rg_resources_lines(
    state: Option<&Lazy<Vec<crate::aws::services::resource_groups::ResourceGroupMember>>>,
) -> Vec<(String, String)> {
    match state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading resources…".to_string())]
        }
        Some(Lazy::Error(e)) => {
            error_rows(e)
        }
        Some(Lazy::Loaded(members)) => {
            if members.is_empty() {
                return vec![("".to_string(), "No resources".to_string())];
            }
            let mut rows: Vec<(String, String)> = Vec::with_capacity(members.len() + 1);
            rows.push(("Count".to_string(), members.len().to_string()));
            rows.push(("".to_string(), "".to_string()));
            for m in members.iter().take(200) {
                let label = if m.resource_type.is_empty() {
                    "→".to_string()
                } else {
                    format!("→ {}", m.resource_type)
                };
                rows.push((label, m.arn.clone()));
            }
            if members.len() > 200 {
                rows.push((
                    "".to_string(),
                    format!("… and {} more", members.len() - 200),
                ));
            }
            rows
        }
    }
}

fn rg_tags_lines(state: Option<&Lazy<std::collections::HashMap<String, String>>>) -> Vec<(String, String)> {
    match state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading tags…".to_string())]
        }
        Some(Lazy::Error(e)) => {
            error_rows(e)
        }
        Some(Lazy::Loaded(tags)) => {
            if tags.is_empty() {
                return vec![("".to_string(), "No tags".to_string())];
            }
            let mut sorted: Vec<(&String, &String)> = tags.iter().collect();
            sorted.sort_by_key(|(k, _)| k.as_str());
            sorted
                .into_iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect()
        }
    }
}

// ── Trusted Advisor check split pane ───────────────────────────────────────────

fn render_ta_check_split(app: &App, check: &TaCheck, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 2, "");

    let mut block = theme::pane_block("Trusted Advisor Check", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = build_ta_check_header_lines(check);
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);
    // Org-aggregated rows carry the reduced Summary/Accounts descriptor —
    // same per-instance switch as TaCheck::detail_sections().
    let descriptor: &'static crate::sections::SectionDescriptor = if check.org_scope {
        &crate::aws::services::trusted_advisor::TA_ORG_CHECK_SECTIONS
    } else {
        &crate::aws::services::trusted_advisor::TA_CHECK_SECTIONS
    };
    render_section_tab_bar(app, chunks[2], frame, &descriptor_tabs(app, descriptor));
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn build_ta_check_header_lines(check: &TaCheck) -> Vec<Line<'static>> {
    let mut lines = vec![Line::raw("")];
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            check.name.clone(),
            Style::default()
                .fg(crate::ui::theme::text_primary())
                .add_modifier(Modifier::BOLD),
        ),
    ]));

    let (status_label, status_color) = ta_status_display(&check.status);
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(check.category_label(), Style::default().fg(theme::text_dim())),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(
            status_label,
            Style::default()
                .fg(status_color)
                .add_modifier(Modifier::BOLD),
        ),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(
            format!("{} flagged", check.resources_flagged),
            Style::default().fg(if check.resources_flagged > 0 {
                theme::warning()
            } else {
                theme::text_dim()
            }),
        ),
    ]));
    if check.org_scope {
        let affected = check
            .org_accounts
            .iter()
            .filter(|a| a.status == "error" || a.status == "warning")
            .count();
        lines.push(Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!(
                    "Organization · {} account(s) · {} affected",
                    check.org_accounts.len(),
                    affected
                ),
                Style::default().fg(if affected > 0 {
                    theme::warning()
                } else {
                    theme::text_dim()
                }),
            ),
        ]));
    }
    lines.push(Line::raw(""));
    lines
}

/// (label, colour) for a Trusted Advisor status string.
fn ta_status_display(status: &str) -> (String, Color) {
    match status {
        "ok" => ("OK".to_string(), theme::success()),
        "warning" => ("Warning".to_string(), theme::warning()),
        "error" => ("Action recommended".to_string(), theme::error()),
        "" => ("—".to_string(), theme::text_dim()),
        other => (other.to_string(), theme::text_dim()),
    }
}

pub fn ta_check_section_lines(
    check: &TaCheck,
    section: TaCheckDetailSection,
    result: Option<&Lazy<Vec<crate::aws::services::trusted_advisor::TaFlaggedResource>>>,
) -> Vec<(String, String)> {
    match section {
        TaCheckDetailSection::Summary => ta_summary_lines(check),
        TaCheckDetailSection::Resources => ta_resources_lines(check, result),
    }
}

fn ta_summary_lines(check: &TaCheck) -> Vec<(String, String)> {
    let (status_label, _) = ta_status_display(&check.status);
    let mut rows = vec![
        ("Check".to_string(), check.name.clone()),
        ("Category".to_string(), check.category_label()),
        ("Status".to_string(), status_label),
        ("".to_string(), "".to_string()),
        (
            "Resources Flagged".to_string(),
            check.resources_flagged.to_string(),
        ),
        (
            "Resources Processed".to_string(),
            check.resources_processed.to_string(),
        ),
        (
            "Resources Suppressed".to_string(),
            check.resources_suppressed.to_string(),
        ),
        ("".to_string(), "".to_string()),
        ("Check ID".to_string(), check.id.clone()),
        ("".to_string(), "".to_string()),
    ];

    // Org scope: the counts above are sums across the organization.
    if check.org_scope {
        let affected = check
            .org_accounts
            .iter()
            .filter(|a| a.status == "error" || a.status == "warning")
            .count();
        rows.insert(3, ("Scope".to_string(), "Organization".to_string()));
        rows.insert(4, ("Accounts".to_string(), check.org_accounts.len().to_string()));
        rows.insert(5, ("Accounts Affected".to_string(), affected.to_string()));
    }

    if !check.description.is_empty() {
        rows.push(("Description".to_string(), "".to_string())); // group header
        // The description is already plain text with paragraph/list newlines
        // (html_to_text); wrap each segment but keep its blank-line breaks.
        for segment in check.description.split('\n') {
            if segment.trim().is_empty() {
                rows.push(("".to_string(), "".to_string())); // blank spacer
            } else {
                for line in wrap_plain(segment, 72) {
                    rows.push((format!(" {}", line), "".to_string()));
                }
            }
        }
    }
    rows
}

fn ta_resources_lines(check: &TaCheck, state: Option<&Lazy<Vec<crate::aws::services::trusted_advisor::TaFlaggedResource>>>) -> Vec<(String, String)> {
    match state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading flagged resources…".to_string())]
        }
        Some(Lazy::Error(e)) => error_rows(e),
        Some(Lazy::Loaded(resources)) => {
            if resources.is_empty() {
                return vec![("".to_string(), "No flagged resources".to_string())];
            }
            let cols = &check.metadata_cols;
            let mut rows: Vec<(String, String)> =
                vec![(format!("{} flagged resource(s)", resources.len()), String::new())];
            rows.push(("".to_string(), "".to_string()));

            for r in resources {
                // Per-resource subsection header: region + suppressed badge.
                let mut head = if r.region.is_empty() {
                    "resource".to_string()
                } else {
                    r.region.clone()
                };
                if r.is_suppressed {
                    head.push_str("  [suppressed]");
                }
                rows.push((head, "".to_string())); // group header (magenta)

                if !r.status.is_empty() {
                    rows.push(("Status".to_string(), r.status.clone()));
                }

                // Each metadata value labelled by its column header (positional).
                for (i, val) in r.metadata.iter().enumerate() {
                    if val.is_empty() {
                        continue;
                    }
                    let key = cols
                        .get(i)
                        .filter(|c| !c.is_empty())
                        .cloned()
                        .unwrap_or_else(|| format!("col {}", i + 1));
                    rows.push((key, val.clone()));
                }
                rows.push(("".to_string(), "".to_string()));
            }
            rows
        }
    }
}

pub fn ta_org_check_section_lines(
    check: &TaCheck,
    section: TaOrgCheckDetailSection,
) -> Vec<(String, String)> {
    match section {
        TaOrgCheckDetailSection::Summary => ta_summary_lines(check),
        TaOrgCheckDetailSection::Accounts => ta_accounts_lines(check),
    }
}

/// Per-account breakdown of an org-aggregated check. Affected accounts get a
/// full block; clean / not-evaluated accounts collapse to one count line each
/// so a 50-account org stays scannable.
fn ta_accounts_lines(check: &TaCheck) -> Vec<(String, String)> {
    if check.org_accounts.is_empty() {
        return vec![(
            "".to_string(),
            "No account returned data for this check".to_string(),
        )];
    }
    let affected: Vec<_> = check
        .org_accounts
        .iter()
        .filter(|a| a.status == "error" || a.status == "warning")
        .collect();
    let ok = check.org_accounts.iter().filter(|a| a.status == "ok").count();
    let na = check.org_accounts.len() - affected.len() - ok;

    let mut rows = vec![
        ("Accounts".to_string(), check.org_accounts.len().to_string()),
        ("Affected".to_string(), affected.len().to_string()),
        ("".to_string(), "".to_string()),
    ];

    for a in &affected {
        rows.push((format!("{} ({})", a.account_name, a.account_id), "".to_string()));
        let (status_label, _) = ta_status_display(&a.status);
        rows.push(("Status".to_string(), status_label));
        rows.push(("Flagged".to_string(), a.flagged.to_string()));
        if a.suppressed > 0 {
            rows.push(("Suppressed".to_string(), a.suppressed.to_string()));
        }
        rows.push(("".to_string(), "".to_string()));
    }

    if affected.is_empty() {
        rows.push(("  · no account is flagged on this check".to_string(), "".to_string()));
    }
    if ok > 0 {
        rows.push((format!("  · {} account(s) OK", ok), "".to_string()));
    }
    if na > 0 {
        rows.push((format!("  · {} account(s) not evaluated", na), "".to_string()));
    }
    rows.push(("".to_string(), "".to_string()));
    rows.push((
        "  · flagged-resource detail is per account — assume into it (@orgs) and open this check"
            .to_string(),
        "".to_string(),
    ));
    rows
}

