fn build_ta_rec_header_lines(
    rec: &crate::aws::services::trusted_advisor::TaRecommendation,
) -> Vec<Line<'static>> {
    let mut lines = vec![Line::raw("")];
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            rec.name.clone(),
            Style::default()
                .fg(crate::ui::theme::text_primary())
                .add_modifier(Modifier::BOLD),
        ),
    ]));

    let (status_label, status_color) = ta_status_display(&rec.status);
    let lifecycle_color = if rec.active() {
        theme::warning()
    } else {
        theme::text_dim()
    };
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(rec.lifecycle_label(), Style::default().fg(lifecycle_color)),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(
            status_label,
            Style::default().fg(status_color).add_modifier(Modifier::BOLD),
        ),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(
            format!("{} error / {} warning", rec.error_count, rec.warning_count),
            Style::default().fg(if rec.error_count + rec.warning_count > 0 {
                theme::warning()
            } else {
                theme::text_dim()
            }),
        ),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(
            format!("{} account(s)", rec.affected_accounts.len()),
            Style::default().fg(theme::text_dim()),
        ),
    ]));
    lines.push(Line::raw(""));
    lines
}

pub fn ta_rec_section_lines(
    rec: &crate::aws::services::trusted_advisor::TaRecommendation,
    section: crate::aws::services::trusted_advisor::TaRecDetailSection,
    detail: Option<&Lazy<crate::aws::services::trusted_advisor::TaRecDetail>>,
    accounts: Option<&Lazy<Vec<crate::aws::services::trusted_advisor::TaRecAccount>>>,
    resources: Option<&Lazy<(Vec<crate::aws::services::trusted_advisor::TaRecResource>, bool)>>,
) -> Vec<(String, String)> {
    use crate::aws::services::trusted_advisor::TaRecDetailSection as S;
    match section {
        S::Overview => ta_rec_overview_lines(rec, detail),
        S::Accounts => ta_rec_accounts_lines(accounts),
        S::Resources => ta_rec_resources_lines(resources),
    }
}

fn ta_rec_overview_lines(
    rec: &crate::aws::services::trusted_advisor::TaRecommendation,
    detail: Option<&Lazy<crate::aws::services::trusted_advisor::TaRecDetail>>,
) -> Vec<(String, String)> {
    let (status_label, _) = ta_status_display(&rec.status);
    let mut rows = vec![
        ("Recommendation".to_string(), rec.name.clone()),
        ("Status".to_string(), status_label),
        ("Lifecycle".to_string(), rec.lifecycle_label()),
        ("Type".to_string(), rec.rec_type.clone()),
        ("Source".to_string(), rec.source.replace('_', " ")),
        (
            "Pillars".to_string(),
            rec.pillars
                .iter()
                .map(|p| crate::aws::services::trusted_advisor::category_label(p))
                .collect::<Vec<_>>()
                .join(", "),
        ),
        ("Services".to_string(), rec.aws_services.join(", ")),
        (
            "Accounts Affected".to_string(),
            if rec.affected_accounts.is_empty() {
                "—".to_string()
            } else {
                rec.affected_accounts.join(", ")
            },
        ),
        ("".to_string(), "".to_string()),
        ("Resources".to_string(), "".to_string()), // group header
        ("Error".to_string(), rec.error_count.to_string()),
        ("Warning".to_string(), rec.warning_count.to_string()),
        ("OK".to_string(), rec.ok_count.to_string()),
        ("".to_string(), "".to_string()),
        ("Created".to_string(), rec.created_at.clone()),
        ("Last Updated".to_string(), rec.last_updated.clone()),
    ];

    match detail {
        None | Some(Lazy::Loading) => {
            rows.push(("".to_string(), "".to_string()));
            rows.push(("".to_string(), "Loading…".to_string()));
        }
        Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
        Some(Lazy::Loaded(d)) => {
            if !d.resolved_at.is_empty() {
                rows.push(("Resolved".to_string(), d.resolved_at.clone()));
            }
            if !d.created_by.is_empty() {
                rows.push(("Created By".to_string(), d.created_by.clone()));
            }
            if !d.updated_on_behalf_of.is_empty() {
                rows.push((
                    "Updated On Behalf Of".to_string(),
                    d.updated_on_behalf_of.clone(),
                ));
            }
            if !d.update_reason_code.is_empty() {
                rows.push(("Update Reason".to_string(), d.update_reason_code.replace('_', " ")));
            }
            if !d.update_reason.is_empty() {
                for line in wrap_plain(&d.update_reason, 72) {
                    rows.push((format!(" {}", line), "".to_string()));
                }
            }
            if !d.description.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Description".to_string(), "".to_string())); // group header
                for segment in d.description.split('\n') {
                    if segment.trim().is_empty() {
                        rows.push(("".to_string(), "".to_string()));
                    } else {
                        for line in wrap_plain(segment, 72) {
                            rows.push((format!(" {}", line), "".to_string()));
                        }
                    }
                }
            }
        }
    }
    rows
}

fn ta_rec_accounts_lines(
    state: Option<&Lazy<Vec<crate::aws::services::trusted_advisor::TaRecAccount>>>,
) -> Vec<(String, String)> {
    match state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading affected accounts…".to_string())]
        }
        Some(Lazy::Error(e)) => error_rows(e),
        Some(Lazy::Loaded(accounts)) => {
            if accounts.is_empty() {
                return vec![("".to_string(), "No affected accounts".to_string())];
            }
            let mut rows: Vec<(String, String)> = vec![
                ("Affected Accounts".to_string(), accounts.len().to_string()),
                ("".to_string(), "".to_string()),
            ];
            for a in accounts {
                rows.push((a.account_id.clone(), "".to_string())); // group header
                let lifecycle = match a.lifecycle.as_str() {
                    "" => "—".to_string(),
                    other => other.replace('_', " "),
                };
                rows.push(("Lifecycle".to_string(), lifecycle));
                if !a.updated_on_behalf_of.is_empty() {
                    rows.push(("Updated On Behalf Of".to_string(), a.updated_on_behalf_of.clone()));
                }
                if !a.update_reason.is_empty() {
                    for line in wrap_plain(&a.update_reason, 68) {
                        rows.push((format!(" {}", line), "".to_string()));
                    }
                }
                if !a.last_updated.is_empty() {
                    rows.push(("Last Updated".to_string(), a.last_updated.clone()));
                }
                rows.push(("".to_string(), "".to_string()));
            }
            rows.push((
                "  · assume into an account (@orgs) for its own Trusted Advisor view".to_string(),
                "".to_string(),
            ));
            rows
        }
    }
}

fn ta_rec_resources_lines(
    state: Option<
        &Lazy<(Vec<crate::aws::services::trusted_advisor::TaRecResource>, bool)>,
    >,
) -> Vec<(String, String)> {
    match state {
        None | Some(Lazy::Loading) => {
            vec![("".to_string(), "Loading affected resources…".to_string())]
        }
        Some(Lazy::Error(e)) => error_rows(e),
        Some(Lazy::Loaded((resources, truncated))) => {
            if resources.is_empty() {
                return vec![("".to_string(), "No affected resources".to_string())];
            }
            let mut rows: Vec<(String, String)> = vec![
                ("Affected Resources".to_string(), resources.len().to_string()),
                ("".to_string(), "".to_string()),
            ];
            for r in resources {
                // Group header: account · region — the "which account is this
                // in" dimension the console's account selector serves.
                let mut head = if r.account_id.is_empty() {
                    r.region.clone()
                } else {
                    format!("{}  ·  {}", r.account_id, r.region)
                };
                if r.excluded {
                    head.push_str("  [excluded]");
                }
                rows.push((head, "".to_string())); // group header
                rows.push(("Resource".to_string(), r.aws_resource_id.clone()));
                if !r.status.is_empty() {
                    rows.push(("Status".to_string(), r.status.clone()));
                }
                for (k, v) in &r.metadata {
                    rows.push((k.clone(), v.clone()));
                }
                rows.push(("".to_string(), "".to_string()));
            }
            if *truncated {
                rows.push((
                    format!(
                        "  · showing the first {} resources (list truncated)",
                        crate::aws::services::trusted_advisor::TA_REC_RESOURCES_CAP
                    ),
                    "".to_string(),
                ));
            }
            rows
        }
    }
}

/// Word-wrap plain text to `width` columns (best-effort, splits on whitespace).
fn wrap_plain(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        if line.is_empty() {
            line = word.to_string();
        } else if line.len() + 1 + word.len() <= width {
            line.push(' ');
            line.push_str(word);
        } else {
            out.push(std::mem::take(&mut line));
            line = word.to_string();
        }
    }
    if !line.is_empty() {
        out.push(line);
    }
    out
}

// ── DynamoDB table split pane ──────────────────────────────────────────────────

fn render_ddb_table_split(app: &App, table: &DdbTable, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "i items");
    let mut block = theme::pane_block("DynamoDB Table", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let state_color = match table.status.as_str() {
        "ACTIVE" => theme::success(),
        "CREATING" | "UPDATING" => theme::warning(),
        "DELETING" => theme::error(),
        _ => theme::text_dim(),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                table.name.clone(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(table.status.clone(), Style::default().fg(state_color)),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(table.billing_mode.clone(), Style::default().fg(theme::text_dim())),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::dynamodb::DDB_TABLE_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn fmt_bytes(b: i64) -> String {
    let b = b as f64;
    if b >= 1_073_741_824.0 {
        format!("{:.2} GB", b / 1_073_741_824.0)
    } else if b >= 1_048_576.0 {
        format!("{:.2} MB", b / 1_048_576.0)
    } else if b >= 1024.0 {
        format!("{:.1} KB", b / 1024.0)
    } else {
        format!("{} B", b as i64)
    }
}

pub fn ddb_table_section_lines(
    table: &DdbTable,
    section: DdbTableDetailSection,
    ttl: Option<&crate::lazy::Lazy<(bool, Option<String>)>>,
    tags: Option<&crate::lazy::Lazy<std::collections::HashMap<String, String>>>,
) -> Vec<(String, String)> {
    match section {
        DdbTableDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), table.name.clone()),
                ("Status".to_string(), table.status.clone()),
                ("Billing Mode".to_string(), table.billing_mode.clone()),
                (
                    "Items (approx)".to_string(),
                    format!("{}  (≈, ~6h stale)", table.item_count),
                ),
                ("Size".to_string(), fmt_bytes(table.size_bytes)),
                (String::new(), String::new()),
                ("Partition Key".to_string(), format!("{} ({})", table.partition_key, table.partition_key_type)),
            ];
            if let (Some(sk), Some(skt)) = (&table.sort_key, &table.sort_key_type) {
                rows.push(("Sort Key".to_string(), format!("{} ({})", sk, skt)));
            }
            rows.push((String::new(), String::new()));
            rows.push((
                "Stream".to_string(),
                if table.stream_enabled {
                    table
                        .stream_view_type
                        .clone()
                        .unwrap_or_else(|| "enabled".to_string())
                } else {
                    "disabled".to_string()
                },
            ));
            let ttl_text = match ttl {
                None | Some(crate::lazy::Lazy::Loading) => "…".to_string(),
                Some(crate::lazy::Lazy::Error(e)) => format!("⚠ {}", e),
                Some(crate::lazy::Lazy::Loaded((enabled, attribute))) => {
                    if *enabled {
                        format!("enabled ({})", attribute.clone().unwrap_or_default())
                    } else {
                        "disabled".to_string()
                    }
                }
            };
            rows.push(("TTL".to_string(), ttl_text));
            if let Some(c) = &table.created {
                rows.push(("Created".to_string(), c.clone()));
            }
            rows.push(("ARN".to_string(), table.arn.clone()));
            rows
        }
        DdbTableDetailSection::Indexes => {
            let mut rows = Vec::new();
            rows.push((format!("Global Secondary Indexes ({})", table.gsis.len()), String::new()));
            rows.push((String::new(), String::new()));
            if table.gsis.is_empty() {
                rows.push(("  none".to_string(), String::new()));
            } else {
                for g in &table.gsis {
                    rows.push((g.name.clone(), String::new())); // group header
                    rows.push(("Keys".to_string(), g.keys.clone()));
                    rows.push(("Projection".to_string(), g.projection.clone()));
                    if !g.status.is_empty() {
                        rows.push(("Status".to_string(), g.status.clone()));
                    }
                    if let (Some(r), Some(w)) = (g.read_capacity, g.write_capacity) {
                        rows.push(("Capacity".to_string(), format!("{} RCU / {} WCU", r, w)));
                    }
                    rows.push((String::new(), String::new()));
                }
            }
            rows.push((format!("Local Secondary Indexes ({})", table.lsis.len()), String::new()));
            rows.push((String::new(), String::new()));
            if table.lsis.is_empty() {
                rows.push(("  none".to_string(), String::new()));
            } else {
                for l in &table.lsis {
                    rows.push((l.name.clone(), String::new()));
                    rows.push(("Keys".to_string(), l.keys.clone()));
                    rows.push(("Projection".to_string(), l.projection.clone()));
                    rows.push((String::new(), String::new()));
                }
            }
            rows
        }
        DdbTableDetailSection::Capacity => {
            let mut rows = vec![("Billing Mode".to_string(), table.billing_mode.clone())];
            if table.billing_mode == "PAY_PER_REQUEST" {
                rows.push((
                    "Mode".to_string(),
                    "On-demand — capacity scales automatically".to_string(),
                ));
            } else {
                rows.push((
                    "Table RCU".to_string(),
                    table.read_capacity.map(|v| v.to_string()).unwrap_or_else(|| "—".to_string()),
                ));
                rows.push((
                    "Table WCU".to_string(),
                    table.write_capacity.map(|v| v.to_string()).unwrap_or_else(|| "—".to_string()),
                ));
                let provisioned_gsis: Vec<&crate::aws::services::dynamodb::DdbIndex> = table
                    .gsis
                    .iter()
                    .filter(|g| g.read_capacity.is_some())
                    .collect();
                if !provisioned_gsis.is_empty() {
                    rows.push((String::new(), String::new()));
                    rows.push(("Per-GSI capacity".to_string(), String::new())); // group header
                    for g in provisioned_gsis {
                        rows.push((
                            format!("  {}", g.name),
                            format!(
                                "{} RCU / {} WCU",
                                g.read_capacity.unwrap_or(0),
                                g.write_capacity.unwrap_or(0)
                            ),
                        ));
                    }
                }
            }
            rows
        }
        DdbTableDetailSection::Tags => match tags {
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("".to_string(), "Loading tags…".to_string())]
            }
            Some(crate::lazy::Lazy::Error(e)) => error_rows(e),
            Some(crate::lazy::Lazy::Loaded(t)) => tag_rows(t),
        },
    }
}

// ── Direct Connect split panes ─────────────────────────────────────────────────

fn render_dx_connection_split(app: &App, conn: &DxConnection, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 3, "");
    let mut block = theme::pane_block("DX Connection", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header = dx_header_lines(&conn.name, &conn.id, &conn.state, dx_state_color(&conn.state));
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::direct_connect::DX_CONNECTION_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn render_dx_vif_split(app: &App, vif: &DxVirtualInterface, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 3, "");
    let mut block = theme::pane_block("DX Virtual Interface", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    // Header carries the BGP state too — it's the operational signal.
    let name = vif.name.clone();
    let bgp = if vif.bgp_status.is_empty() {
        "no peers".to_string()
    } else {
        format!("BGP {}", vif.bgp_status)
    };
    let bgp_color = match vif.bgp_status.as_str() {
        "up" => theme::success(),
        "down" => theme::error(),
        _ => theme::text_dim(),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                name,
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(vif.id.clone(), Style::default().fg(theme::text_dim())),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(vif.state.clone(), Style::default().fg(dx_state_color(&vif.state))),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(bgp, Style::default().fg(bgp_color).add_modifier(Modifier::BOLD)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::direct_connect::DX_VIF_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn dx_state_color(state: &str) -> Color {
    match state {
        "available" => theme::success(),
        "down" | "rejected" => theme::error(),
        "pending" | "requested" | "ordering" | "confirming" | "verifying" => theme::warning(),
        _ => theme::text_dim(),
    }
}

fn dx_header_lines(name: &str, id: &str, state: &str, state_color: Color) -> Vec<Line<'static>> {
    vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                name.to_string(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(id.to_string(), Style::default().fg(theme::text_dim())),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(state.to_string(), Style::default().fg(state_color)),
        ]),
        Line::raw(""),
    ]
}

/// Body lines for a DX connection. Virtual Interfaces are filtered from the
/// already-loaded list (passed in by `get_detail_lines`), so no extra fetch.
pub fn dx_connection_section_lines(
    conn: &DxConnection,
    section: DxConnectionDetailSection,
    vifs: &[(String, String, String, String)], // id, type, state, bgp
) -> Vec<(String, String)> {
    match section {
        DxConnectionDetailSection::Details => {
            let mut rows = vec![
                ("ID".to_string(), conn.id.clone()),
                ("Name".to_string(), conn.name.clone()),
                ("State".to_string(), conn.state.clone()),
                ("Bandwidth".to_string(), conn.bandwidth.clone()),
                ("Location".to_string(), conn.location.clone()),
                ("Region".to_string(), conn.region.clone()),
            ];
            if let Some(v) = conn.vlan {
                rows.push(("VLAN".to_string(), v.to_string()));
            }
            if !conn.partner.is_empty() {
                rows.push(("Partner".to_string(), conn.partner.clone()));
            }
            if let Some(lag) = &conn.lag_id {
                rows.push(("LAG".to_string(), lag.clone()));
            }
            if !conn.aws_device.is_empty() {
                rows.push(("AWS Device".to_string(), conn.aws_device.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push((
                "Jumbo Frames".to_string(),
                if conn.jumbo_capable { "✓ capable" } else { "no" }.to_string(),
            ));
            rows.push((
                "MACsec".to_string(),
                if conn.mac_sec_capable { "✓ capable" } else { "no" }.to_string(),
            ));
            if !conn.encryption_mode.is_empty() {
                rows.push(("Encryption Mode".to_string(), conn.encryption_mode.clone()));
            }
            rows
        }
        DxConnectionDetailSection::VirtualInterfaces => {
            let mut rows = vec![(format!("Virtual Interfaces ({})", vifs.len()), String::new())];
            rows.push((String::new(), String::new()));
            if vifs.is_empty() {
                rows.push(("  No virtual interfaces".to_string(), String::new()));
            } else {
                rows.push((
                    format!("  {:<22}  {:<9}  {:<12}  {}", "ID", "Type", "State", "BGP"),
                    String::new(),
                ));
                for (id, kind, state, bgp) in vifs {
                    let bgp_label = if bgp.is_empty() { "—" } else { bgp.as_str() };
                    rows.push((
                        format!("  {:<22}  {:<9}  {:<12}  {}", id, kind, state, bgp_label),
                        String::new(),
                    ));
                }
            }
            rows
        }
        DxConnectionDetailSection::Tags => tag_rows(&conn.tags),
    }
}

/// Body lines for a DX virtual interface. BGP peers come from the VIF itself.
pub fn dx_vif_section_lines(
    vif: &DxVirtualInterface,
    section: DxVifDetailSection,
) -> Vec<(String, String)> {
    match section {
        DxVifDetailSection::Details => {
            let mut rows = vec![
                ("ID".to_string(), vif.id.clone()),
                ("Name".to_string(), vif.name.clone()),
                ("Type".to_string(), vif.kind.clone()),
                ("State".to_string(), vif.state.clone()),
                ("Connection".to_string(), vif.connection_id.clone()),
            ];
            if !vif.gateway_id.is_empty() {
                rows.push(("Gateway".to_string(), vif.gateway_id.clone()));
            }
            if let Some(v) = vif.vlan {
                rows.push(("VLAN".to_string(), v.to_string()));
            }
            if let Some(mtu) = vif.mtu {
                rows.push(("MTU".to_string(), mtu.to_string()));
            }
            if !vif.address_family.is_empty() {
                rows.push(("Address Family".to_string(), vif.address_family.clone()));
            }
            if !vif.amazon_address.is_empty() {
                rows.push(("Amazon Address".to_string(), vif.amazon_address.clone()));
            }
            if !vif.customer_address.is_empty() {
                rows.push(("Customer Address".to_string(), vif.customer_address.clone()));
            }
            rows
        }
        DxVifDetailSection::Bgp => {
            let status_label = if vif.bgp_status.is_empty() {
                "no peers".to_string()
            } else {
                vif.bgp_status.clone()
            };
            let mut rows = vec![
                ("BGP Status".to_string(), status_label),
                (
                    "BGP ASN".to_string(),
                    vif.bgp_asn.map(|a| a.to_string()).unwrap_or_default(),
                ),
                (String::new(), String::new()),
                (format!("Peers ({})", vif.peers.len()), String::new()),
                (String::new(), String::new()),
            ];
            if vif.peers.is_empty() {
                rows.push(("  No BGP peers".to_string(), String::new()));
            } else {
                for p in &vif.peers {
                    let title = format!("ASN {}  ·  {}", p.asn, p.address_family);
                    rows.push((title, String::new())); // group header
                    rows.push((
                        "Status".to_string(),
                        if p.status.is_empty() {
                            p.peer_state.clone()
                        } else {
                            format!("{} ({})", p.status, p.peer_state)
                        },
                    ));
                    if !p.amazon_address.is_empty() {
                        rows.push(("Amazon Address".to_string(), p.amazon_address.clone()));
                    }
                    if !p.customer_address.is_empty() {
                        rows.push(("Customer Address".to_string(), p.customer_address.clone()));
                    }
                    rows.push((
                        "Auth Key".to_string(),
                        if p.has_auth_key { "✓ set" } else { "none" }.to_string(),
                    ));
                    rows.push((String::new(), String::new()));
                }
            }
            rows
        }
        DxVifDetailSection::Tags => tag_rows(&vif.tags),
    }
}

