pub fn eks_cluster_section_lines(
    cluster: &EksCluster,
    section: EksClusterDetailSection,
    nodegroups: Option<&Lazy<Vec<crate::aws::services::eks::EksNodeGroup>>>,
    fargate: Option<&Lazy<Vec<crate::aws::services::eks::EksFargateProfile>>>,
    addons: Option<&Lazy<Vec<crate::aws::services::eks::EksAddon>>>,
    access: Option<&Lazy<crate::aws::services::eks::EksAccessData>>,
    insights: Option<&Lazy<Vec<crate::aws::services::eks::EksInsight>>>,
) -> Vec<(String, String)> {
    match section {
        EksClusterDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), cluster.name.clone()),
                ("Status".to_string(), cluster.status.clone()),
                ("K8s Version".to_string(), cluster.version.clone()),
                ("Platform".to_string(), cluster.platform_version.clone()),
                ("Auth Mode".to_string(), cluster.auth_mode.clone()),
            ];
            if !cluster.upgrade_policy.is_empty() {
                rows.push(("Support".to_string(), cluster.upgrade_policy.clone()));
            }
            // Health issues — force red via the ✗ marker.
            if !cluster.health_issues.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Health".to_string(), String::new())); // group header
                for issue in &cluster.health_issues {
                    rows.push(("  ✗ Issue".to_string(), issue.clone()));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push(("Endpoint".to_string(), String::new())); // group header
            rows.push(("  Access".to_string(), cluster.endpoint_access()));
            rows.push(("  URL".to_string(), cluster.endpoint.clone()));
            rows.push((String::new(), String::new()));
            rows.push(("Identity & Encryption".to_string(), String::new())); // group header
            if !cluster.role_arn.is_empty() {
                rows.push(("  Cluster Role".to_string(), cluster.role_arn.clone()));
            }
            if !cluster.oidc_issuer.is_empty() {
                rows.push(("  OIDC Issuer".to_string(), cluster.oidc_issuer.clone()));
            }
            rows.push((
                "  Secrets KMS Key".to_string(),
                if cluster.secrets_kms_key.is_empty() {
                    "(none)".to_string()
                } else {
                    cluster.secrets_kms_key.clone()
                },
            ));
            rows.push((String::new(), String::new()));
            let logging = if cluster.logging_enabled.is_empty() {
                "(none enabled)".to_string()
            } else {
                cluster.logging_enabled.join(", ")
            };
            rows.push(("Control Plane Logs".to_string(), logging));
            if cluster.logging_enabled.is_empty() {
                rows.push((
                    "  enable control-plane logging to use t (tail)".to_string(),
                    String::new(),
                ));
            } else {
                rows.push(("  press t to tail · m for metrics".to_string(), String::new()));
            }
            if let Some(c) = &cluster.created {
                rows.push((String::new(), String::new()));
                rows.push(("Created".to_string(), c.clone()));
            }
            rows.push(("ARN".to_string(), cluster.arn.clone()));
            rows
        }
        EksClusterDetailSection::Networking => {
            let mut rows = vec![("VPC".to_string(), String::new())]; // group header
            rows.push(("  VPC".to_string(), cluster.vpc_id.clone()));
            if cluster.subnet_ids.is_empty() {
                rows.push(("  Subnets".to_string(), "(none)".to_string()));
            } else {
                rows.push(("  Subnets".to_string(), String::new()));
                for s in &cluster.subnet_ids {
                    rows.push(("  Subnet".to_string(), s.clone()));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push(("Security Groups".to_string(), String::new())); // group header
            if !cluster.cluster_security_group_id.is_empty() {
                rows.push((
                    "  Cluster SG".to_string(),
                    cluster.cluster_security_group_id.clone(),
                ));
            }
            for sg in &cluster.security_group_ids {
                rows.push(("  Control Plane SG".to_string(), sg.clone()));
            }
            if cluster.cluster_security_group_id.is_empty()
                && cluster.security_group_ids.is_empty()
            {
                rows.push(("  (none)".to_string(), String::new()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Service Networking".to_string(), String::new())); // group header
            if !cluster.ip_family.is_empty() {
                rows.push(("  IP Family".to_string(), cluster.ip_family.clone()));
            }
            if !cluster.service_ipv4_cidr.is_empty() {
                rows.push(("  Service IPv4 CIDR".to_string(), cluster.service_ipv4_cidr.clone()));
            }
            if !cluster.service_ipv6_cidr.is_empty() {
                rows.push(("  Service IPv6 CIDR".to_string(), cluster.service_ipv6_cidr.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Public Access CIDRs".to_string(), String::new())); // group header
            if cluster.public_access_cidrs.is_empty() {
                rows.push(("  (none / disabled)".to_string(), String::new()));
            } else {
                for c in &cluster.public_access_cidrs {
                    rows.push((format!("  {}", c), String::new()));
                }
            }
            rows
        }
        EksClusterDetailSection::Compute => match nodegroups {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading node groups…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(ngs)) => {
                if ngs.is_empty() {
                    return vec![("".to_string(), "No managed node groups".to_string())];
                }
                let mut rows = Vec::new();
                for ng in ngs {
                    rows.push((ng.name.clone(), String::new())); // group header
                    rows.push(("  Status".to_string(), ng.status.clone()));
                    for issue in &ng.health_issues {
                        rows.push(("  ✗ Health".to_string(), issue.clone()));
                    }
                    rows.push((
                        "  Version".to_string(),
                        version_drift(&ng.version, &cluster.version),
                    ));
                    if !ng.release_version.is_empty() {
                        rows.push(("  Release".to_string(), ng.release_version.clone()));
                    }
                    rows.push(("  Capacity".to_string(), ng.capacity_type.clone()));
                    rows.push(("  AMI Type".to_string(), ng.ami_type.clone()));
                    if !ng.instance_types.is_empty() {
                        rows.push(("  Instance Types".to_string(), ng.instance_types.join(", ")));
                    }
                    rows.push((
                        "  Scaling".to_string(),
                        format!("desired {} (min {} / max {})", ng.desired, ng.min, ng.max),
                    ));
                    if let Some(d) = ng.disk_size {
                        rows.push(("  Disk Size".to_string(), format!("{} GiB", d)));
                    }
                    if !ng.max_unavailable.is_empty() {
                        rows.push(("  Max Unavailable".to_string(), ng.max_unavailable.clone()));
                    }
                    if !ng.launch_template.is_empty() {
                        rows.push(("  Launch Template".to_string(), ng.launch_template.clone()));
                    }
                    if !ng.node_role.is_empty() {
                        rows.push(("  Node Role".to_string(), ng.node_role.clone()));
                    }
                    if !ng.labels.is_empty() {
                        rows.push(("  Labels".to_string(), String::new()));
                        for (k, v) in &ng.labels {
                            rows.push((format!("    {}={}", k, v), String::new()));
                        }
                    }
                    if !ng.taints.is_empty() {
                        rows.push(("  Taints".to_string(), String::new()));
                        for t in &ng.taints {
                            rows.push((format!("    {}", t), String::new()));
                        }
                    }
                    if !ng.subnets.is_empty() {
                        rows.push(("  Subnets".to_string(), String::new()));
                        for s in &ng.subnets {
                            rows.push(("    Subnet".to_string(), s.clone()));
                        }
                    }
                    if let Some(c) = &ng.created {
                        rows.push(("  Created".to_string(), c.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EksClusterDetailSection::Fargate => match fargate {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading Fargate profiles…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(fps)) => {
                if fps.is_empty() {
                    return vec![("".to_string(), "No Fargate profiles".to_string())];
                }
                let mut rows = Vec::new();
                for fp in fps {
                    rows.push((fp.name.clone(), String::new())); // group header
                    rows.push(("  Status".to_string(), fp.status.clone()));
                    if !fp.pod_execution_role.is_empty() {
                        rows.push((
                            "  Pod Exec Role".to_string(),
                            fp.pod_execution_role.clone(),
                        ));
                    }
                    rows.push(("  Selectors".to_string(), String::new()));
                    for sel in &fp.selectors {
                        rows.push((format!("    {}", sel), String::new()));
                    }
                    if !fp.subnets.is_empty() {
                        rows.push(("  Subnets".to_string(), String::new()));
                        for s in &fp.subnets {
                            rows.push(("    Subnet".to_string(), s.clone()));
                        }
                    }
                    if let Some(c) = &fp.created {
                        rows.push(("  Created".to_string(), c.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EksClusterDetailSection::Addons => match addons {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading add-ons…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(addons)) => {
                if addons.is_empty() {
                    return vec![("".to_string(), "No add-ons".to_string())];
                }
                let mut rows = Vec::new();
                for a in addons {
                    let status = if a.status == "DEGRADED" {
                        format!("✗ {}", a.status)
                    } else {
                        a.status.clone()
                    };
                    rows.push((a.name.clone(), String::new())); // group header
                    rows.push(("  Status".to_string(), status));
                    let version = if a.update_available && !a.latest_version.is_empty() {
                        format!("⚠ {}  (latest {})", a.version, a.latest_version)
                    } else {
                        a.version.clone()
                    };
                    rows.push(("  Version".to_string(), version));
                    for issue in &a.health_issues {
                        rows.push(("  ✗ Health".to_string(), issue.clone()));
                    }
                    if a.configured {
                        rows.push(("  Configured".to_string(), "yes".to_string()));
                    }
                    if !a.service_account_role.is_empty() {
                        rows.push(("  SA Role".to_string(), a.service_account_role.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EksClusterDetailSection::Access => match access {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading access entries…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(data)) => {
                let mut rows = vec![("Auth Mode".to_string(), cluster.auth_mode.clone())];
                if cluster.auth_mode == "CONFIG_MAP" {
                    rows.push((
                        "  CONFIG_MAP clusters keep mappings in the in-cluster aws-auth ConfigMap"
                            .to_string(),
                        String::new(),
                    ));
                }
                rows.push((String::new(), String::new()));
                rows.push(("Access Entries".to_string(), String::new())); // group header
                if data.entries.is_empty() {
                    rows.push(("  (none)".to_string(), String::new()));
                } else {
                    for e in &data.entries {
                        rows.push(("  Principal".to_string(), e.principal_arn.clone()));
                        if !e.entry_type.is_empty() {
                            rows.push(("    Type".to_string(), e.entry_type.clone()));
                        }
                        if !e.username.is_empty() {
                            rows.push(("    Username".to_string(), e.username.clone()));
                        }
                        if !e.kubernetes_groups.is_empty() {
                            rows.push((
                                "    K8s Groups".to_string(),
                                e.kubernetes_groups.join(", "),
                            ));
                        }
                        for p in &e.access_policies {
                            rows.push((format!("    {}", p), String::new()));
                        }
                        rows.push((String::new(), String::new()));
                    }
                }
                rows.push(("Pod Identity".to_string(), String::new())); // group header
                if data.pod_identities.is_empty() {
                    rows.push(("  (none)".to_string(), String::new()));
                } else {
                    for pi in &data.pod_identities {
                        rows.push((
                            "  Service Account".to_string(),
                            format!("{}/{}", pi.namespace, pi.service_account),
                        ));
                        rows.push(("    Role".to_string(), pi.role_arn.clone()));
                        rows.push((String::new(), String::new()));
                    }
                }
                rows
            }
        },
        EksClusterDetailSection::Insights => match insights {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading upgrade insights…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                if list.is_empty() {
                    return vec![(
                        "".to_string(),
                        "No upgrade-readiness insights".to_string(),
                    )];
                }
                let mut rows = Vec::new();
                for ins in list {
                    rows.push((ins.name.clone(), String::new())); // group header
                    let status = match ins.status.as_str() {
                        "PASSING" => format!("✓ {}", ins.status),
                        "WARNING" => format!("⚠ {}", ins.status),
                        "ERROR" => format!("✗ {}", ins.status),
                        _ => ins.status.clone(),
                    };
                    rows.push(("  Status".to_string(), status));
                    if !ins.category.is_empty() {
                        rows.push(("  Category".to_string(), ins.category.clone()));
                    }
                    if !ins.kubernetes_version.is_empty() {
                        rows.push(("  Target Version".to_string(), ins.kubernetes_version.clone()));
                    }
                    if !ins.description.is_empty() {
                        rows.push(("  Description".to_string(), ins.description.clone()));
                    }
                    if !ins.recommendation.is_empty() {
                        rows.push(("  Recommendation".to_string(), ins.recommendation.clone()));
                    }
                    if !ins.deprecation_details.is_empty() {
                        rows.push(("  Deprecated APIs".to_string(), String::new()));
                        for d in &ins.deprecation_details {
                            rows.push((format!("    {}", d), String::new()));
                        }
                    }
                    if let Some(r) = &ins.last_refresh {
                        rows.push(("  Last Refresh".to_string(), r.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EksClusterDetailSection::Tags => tag_rows(&cluster.tags),
    }
}

/// The uniform in-section note for a failed lazy fetch (a missing permission,
/// a partial emulator, or an unreachable endpoint) — keeps the error local to
/// the section instead of a scary global "sdk error". `style_detail_row`
/// renders the `⚠`-prefixed content line in the warning color. Used by every
/// lazy-section `*crate::lazy::Lazy::Error` render site.
fn error_rows(err: &str) -> Vec<(String, String)> {
    vec![
        (String::new(), String::new()),
        (format!("  ⚠ {}", err), String::new()),
    ]
}

/// Shared body for the lazy **Optimizer** section (the Compute Optimizer
/// right-sizing lens) on the EC2 instance / EBS volume / Lambda / ASG /
/// ECS-service panes. Pure row-builder: all flattening happens in
/// `aws::services::computeoptimizer`.
pub fn optimizer_lines(
    state: Option<&Lazy<Option<crate::aws::services::computeoptimizer::OptimizerRec>>>,
    enrollment: Option<&crate::aws::services::computeoptimizer::CoEnrollment>,
) -> Vec<(String, String)> {
    use crate::aws::services::computeoptimizer::{display_finding, CoEnrollment};
    // An unenrolled account can never return recommendations — the hint
    // outranks whatever the (doomed) per-resource call reported.
    if let Some(CoEnrollment::Inactive(status)) = enrollment {
        return vec![
            (String::new(), String::new()),
            (
                format!("  ⚠ Compute Optimizer is not enrolled ({})", status),
                String::new(),
            ),
            (
                "  Enroll in the AWS console (free) — recommendations appear ~30h later."
                    .to_string(),
                String::new(),
            ),
        ];
    }
    // Enrollment-check failure (endpoint / permissions): the per-resource
    // call almost certainly failed the same way — show the root cause unless
    // we somehow got data anyway.
    if let Some(CoEnrollment::Error(e)) = enrollment {
        if !matches!(state, Some(Lazy::Loaded(_))) {
            return error_rows(e);
        }
    }
    match state {
        None | Some(Lazy::Loading) => {
            vec![("  Loading recommendation…".to_string(), String::new())]
        }
        Some(Lazy::Error(e)) => error_rows(e),
        Some(Lazy::Loaded(None)) => vec![
            (
                "  No Compute Optimizer recommendation for this resource."
                    .to_string(),
                String::new(),
            ),
            (String::new(), String::new()),
            (
                "  New resources need ~30h and a 14-day metrics window; ECS needs Fargate."
                    .to_string(),
                String::new(),
            ),
        ],
        Some(Lazy::Loaded(Some(rec))) => {
            let mut rows = vec![("Finding".to_string(), display_finding(&rec.finding))];
            if !rec.finding_reasons.is_empty() {
                rows.push(("Reasons".to_string(), rec.finding_reasons.join(", ")));
            }
            if let Some(risk) = &rec.performance_risk {
                rows.push(("Current perf risk".to_string(), risk.clone()));
            }
            rows.push((
                "Look-back".to_string(),
                format!("{:.0} days", rec.lookback_days),
            ));
            if !rec.current.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Current".to_string(), String::new()));
                rows.extend(rec.current.iter().cloned());
            }
            if !rec.utilization.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Observed utilization".to_string(), String::new()));
                rows.extend(rec.utilization.iter().cloned());
            }
            if !rec.options.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Recommended options".to_string(), String::new()));
                for o in &rec.options {
                    let mut extras: Vec<String> = Vec::new();
                    if let Some(r) = o.performance_risk {
                        extras.push(format!("risk {:.1}", r));
                    }
                    if let Some(m) = &o.migration_effort {
                        extras.push(format!("effort {}", m));
                    }
                    let value = match (&o.savings, extras.is_empty()) {
                        (Some(s), true) => s.clone(),
                        (Some(s), false) => format!("{} · {}", s, extras.join(" · ")),
                        (None, false) => extras.join(" · "),
                        (None, true) => "—".to_string(),
                    };
                    rows.push((format!("#{}  {}", o.rank, o.label), value));
                    for p in &o.projected {
                        rows.push((format!("      {}", p), String::new()));
                    }
                }
            }
            rows
        }
    }
}

/// Annotate a child's k8s version with a drift marker when it trails the
/// cluster's control-plane version (the EKS upgrade signal).
fn version_drift(child: &str, cluster: &str) -> String {
    if !child.is_empty() && !cluster.is_empty() && child != cluster {
        format!("{}  ⚠ behind cluster ({})", child, cluster)
    } else {
        child.to_string()
    }
}

// ── EFS file system split pane ─────────────────────────────────────────────────

fn render_efs_fs_split(app: &App, fs: &EfsFileSystem, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");
    let mut block = theme::pane_block("EFS File System", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let state_color = match fs.lifecycle_state.as_str() {
        "available" => theme::success(),
        "creating" | "updating" => theme::warning(),
        "error" => theme::error(),
        _ => theme::text_dim(),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                fs.fs_name.clone(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(fs.file_system_id.clone(), Style::default().fg(theme::text_dim())),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(fs.lifecycle_state.clone(), Style::default().fg(state_color)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::efs::EFS_FS_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn efs_fs_section_lines(
    fs: &EfsFileSystem,
    section: EfsFileSystemDetailSection,
    mount_targets: Option<&Lazy<Vec<crate::aws::services::efs::EfsMountTarget>>>,
    access_points: Option<&Lazy<Vec<crate::aws::services::efs::EfsAccessPoint>>>,
) -> Vec<(String, String)> {
    use crate::aws::services::efs::fmt_bytes;
    match section {
        EfsFileSystemDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), fs.fs_name.clone()),
                ("File System ID".to_string(), fs.file_system_id.clone()),
                ("State".to_string(), fs.lifecycle_state.clone()),
                ("Storage Class".to_string(), fs.storage_class().to_string()),
            ];
            if let Some(az) = &fs.availability_zone_name {
                rows.push(("  Availability Zone".to_string(), az.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Performance".to_string(), String::new())); // group header
            rows.push(("  Performance Mode".to_string(), fs.performance_mode.clone()));
            rows.push(("  Throughput Mode".to_string(), fs.throughput_summary()));
            rows.push((String::new(), String::new()));
            rows.push(("Storage".to_string(), String::new())); // group header
            rows.push(("  Total Size".to_string(), fmt_bytes(fs.size_total)));
            rows.push(("  Standard".to_string(), fmt_bytes(fs.size_standard)));
            rows.push(("  Infrequent Access".to_string(), fmt_bytes(fs.size_ia)));
            if fs.size_archive > 0 {
                rows.push(("  Archive".to_string(), fmt_bytes(fs.size_archive)));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Lifecycle".to_string(), String::new())); // group header
            if fs.lifecycle.is_empty() {
                rows.push(("  Policy".to_string(), "None".to_string()));
            } else {
                if let Some(v) = &fs.lifecycle.to_ia {
                    rows.push(("  → IA".to_string(), v.clone()));
                }
                if let Some(v) = &fs.lifecycle.to_archive {
                    rows.push(("  → Archive".to_string(), v.clone()));
                }
                if let Some(v) = &fs.lifecycle.to_primary {
                    rows.push(("  → Primary".to_string(), v.clone()));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push(("Other".to_string(), String::new())); // group header
            rows.push((
                "  Encryption".to_string(),
                if fs.encrypted {
                    "✓ Encrypted".to_string()
                } else {
                    "✗ Not encrypted".to_string()
                },
            ));
            if let Some(kms) = &fs.kms_key_id {
                rows.push(("  KMS Key".to_string(), kms.clone()));
            }
            rows.push((
                "  Mount Targets".to_string(),
                fs.number_of_mount_targets.to_string(),
            ));
            if let Some(c) = &fs.created {
                rows.push(("  Created".to_string(), c.clone()));
            }
            rows.push(("  ARN".to_string(), fs.arn.clone()));
            rows
        }
        EfsFileSystemDetailSection::MountTargets => match mount_targets {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading mount targets…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(mts)) => {
                if mts.is_empty() {
                    return vec![(
                        "".to_string(),
                        "No mount targets — the file system is unreachable until one exists"
                            .to_string(),
                    )];
                }
                let mut rows = Vec::new();
                for mt in mts {
                    rows.push((mt.availability_zone.clone(), String::new())); // group header
                    rows.push(("  Mount Target".to_string(), mt.mount_target_id.clone()));
                    rows.push(("  State".to_string(), mt.lifecycle_state.clone()));
                    rows.push(("  IP Address".to_string(), mt.ip_address.clone()));
                    rows.push(("  Subnet".to_string(), mt.subnet_id.clone()));
                    if !mt.network_interface_id.is_empty() {
                        rows.push(("  ENI".to_string(), mt.network_interface_id.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EfsFileSystemDetailSection::AccessPoints => match access_points {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading access points…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(aps)) => {
                if aps.is_empty() {
                    return vec![("".to_string(), "No access points".to_string())];
                }
                let mut rows = Vec::new();
                for ap in aps {
                    let label = if ap.name.is_empty() {
                        ap.access_point_id.clone()
                    } else {
                        ap.name.clone()
                    };
                    rows.push((label, String::new())); // group header
                    rows.push(("  Access Point".to_string(), ap.access_point_id.clone()));
                    rows.push(("  State".to_string(), ap.lifecycle_state.clone()));
                    rows.push(("  Root Directory".to_string(), ap.root_directory.clone()));
                    if let Some(u) = &ap.posix_user {
                        rows.push(("  POSIX User (uid:gid)".to_string(), u.clone()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        EfsFileSystemDetailSection::Tags => tag_rows(&fs.tags),
    }
}

// ── ElastiCache cluster split pane ─────────────────────────────────────────────

fn render_elasticache_split(
    app: &App,
    c: &ElastiCacheCluster,
    area: Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");
    let mut block = theme::pane_block("ElastiCache", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let state_color = match c.status.as_str() {
        "available" => theme::success(),
        "creating" | "modifying" | "snapshotting" => theme::warning(),
        "create-failed" | "incompatible-network" | "restore-failed" => theme::error(),
        _ => theme::text_dim(),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                c.name.clone(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(c.engine_summary(), Style::default().fg(theme::text_dim())),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(c.status.clone(), Style::default().fg(state_color)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::elasticache::ELASTICACHE_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn elasticache_section_lines(
    c: &ElastiCacheCluster,
    section: ElastiCacheDetailSection,
    tags: Option<&Lazy<Vec<(String, String)>>>,
) -> Vec<(String, String)> {
    match section {
        ElastiCacheDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), c.name.clone()),
                ("Cache ID".to_string(), c.id.clone()),
                (
                    "Type".to_string(),
                    match c.kind {
                        CacheKind::ReplicationGroup => "Replication Group".to_string(),
                        CacheKind::CacheCluster => "Cache Cluster".to_string(),
                    },
                ),
                ("Engine".to_string(), c.engine_summary()),
                ("Status".to_string(), c.status.clone()),
                ("Node Type".to_string(), c.node_type.clone()),
                ("Nodes".to_string(), c.num_nodes.to_string()),
            ];
            if let Some(d) = &c.description {
                rows.push(("Description".to_string(), d.clone()));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Endpoints".to_string(), String::new())); // group header
            rows.push((
                "  Primary".to_string(),
                c.endpoint.clone().unwrap_or_else(|| "—".to_string()),
            ));
            if let Some(r) = &c.reader_endpoint {
                rows.push(("  Reader".to_string(), r.clone()));
            }

            if c.kind == CacheKind::ReplicationGroup {
                rows.push((String::new(), String::new()));
                rows.push(("Availability".to_string(), String::new())); // group header
                rows.push((
                    "  Cluster Mode".to_string(),
                    if c.cluster_mode_enabled {
                        "enabled".to_string()
                    } else {
                        "disabled".to_string()
                    },
                ));
                if let Some(m) = &c.multi_az {
                    rows.push(("  Multi-AZ".to_string(), m.clone()));
                }
                if let Some(f) = &c.automatic_failover {
                    rows.push(("  Automatic Failover".to_string(), f.clone()));
                }
            }

            rows.push((String::new(), String::new()));
            rows.push(("Security".to_string(), String::new())); // group header
            rows.push((
                "  Encryption at Rest".to_string(),
                if c.at_rest_encryption {
                    "✓ Enabled".to_string()
                } else {
                    "✗ Disabled".to_string()
                },
            ));
            rows.push((
                "  Encryption in Transit".to_string(),
                if c.transit_encryption {
                    "✓ Enabled".to_string()
                } else {
                    "✗ Disabled".to_string()
                },
            ));
            rows.push((
                "  Auth Token (AUTH)".to_string(),
                if c.auth_token_enabled {
                    "✓ Enabled".to_string()
                } else {
                    "✗ Disabled".to_string()
                },
            ));

            rows.push((String::new(), String::new()));
            rows.push(("Maintenance".to_string(), String::new())); // group header
            rows.push((
                "  Snapshot Retention".to_string(),
                match c.snapshot_retention {
                    Some(0) | None => "disabled".to_string(),
                    Some(d) => format!("{} day(s)", d),
                },
            ));
            if let Some(w) = &c.maintenance_window {
                rows.push(("  Window".to_string(), w.clone()));
            }
            if let Some(created) = &c.created {
                rows.push(("  Created".to_string(), created.clone()));
            }
            if !c.arn.is_empty() {
                rows.push(("  ARN".to_string(), c.arn.clone()));
            }
            rows
        }
        ElastiCacheDetailSection::Nodes => {
            if c.nodes.is_empty() {
                return vec![("".to_string(), "No node detail available".to_string())];
            }
            let mut rows = Vec::new();
            for n in &c.nodes {
                let label = match &n.role {
                    Some(role) if !role.is_empty() => format!("{} ({})", n.cache_cluster_id, role),
                    _ => n.cache_cluster_id.clone(),
                };
                rows.push((label, String::new())); // group header
                if !n.node_id.is_empty() {
                    rows.push(("  Node ID".to_string(), n.node_id.clone()));
                }
                if !n.status.is_empty() {
                    rows.push(("  Status".to_string(), n.status.clone()));
                }
                if let Some(az) = &n.az {
                    rows.push(("  Availability Zone".to_string(), az.clone()));
                }
                if let Some(ep) = &n.endpoint {
                    rows.push(("  Endpoint".to_string(), ep.clone()));
                }
                rows.push((String::new(), String::new()));
            }
            rows
        }
        ElastiCacheDetailSection::Network => {
            let mut rows = Vec::new();
            rows.push((
                "Subnet Group".to_string(),
                c.subnet_group.clone().unwrap_or_else(|| "—".to_string()),
            ));
            rows.push((
                "Parameter Group".to_string(),
                c.parameter_group.clone().unwrap_or_else(|| "—".to_string()),
            ));
            if let Some(kms) = &c.kms_key_id {
                rows.push(("KMS Key".to_string(), kms.clone())); // arn → jumpable
            }
            rows.push((String::new(), String::new()));
            rows.push(("Security Groups".to_string(), String::new())); // group header
            if c.security_group_ids.is_empty() {
                rows.push(("  ".to_string(), "None".to_string()));
            } else {
                for sg in &c.security_group_ids {
                    rows.push(("  Security Group".to_string(), sg.clone())); // sg- → jumpable
                }
            }
            rows
        }
        ElastiCacheDetailSection::Tags => match tags {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading tags…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                if list.is_empty() {
                    return vec![("".to_string(), "No tags".to_string())];
                }
                list.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
            }
        },
    }
}

// ── Kinesis stream split pane ──────────────────────────────────────────────────

fn render_kinesis_split(app: &App, st: &KinesisStream, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 3, "");
    let mut block = theme::pane_block("Kinesis Stream", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let state_color = match st.status.as_str() {
        "ACTIVE" => theme::success(),
        "CREATING" | "UPDATING" => theme::warning(),
        "DELETING" => theme::text_dim(),
        _ => theme::text_dim(),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                st.name.clone(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{} · {} shard(s)", st.mode, st.open_shard_count),
                Style::default().fg(theme::text_dim()),
            ),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(st.status.clone(), Style::default().fg(state_color)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::kinesis::KINESIS_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn kinesis_section_lines(
    st: &KinesisStream,
    section: KinesisDetailSection,
    consumers: Option<&Lazy<Vec<crate::aws::services::kinesis::KinesisConsumer>>>,
    tags: Option<&Lazy<Vec<(String, String)>>>,
) -> Vec<(String, String)> {
    match section {
        KinesisDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), st.name.clone()),
                ("Status".to_string(), st.status.clone()),
                ("Capacity Mode".to_string(), st.mode.clone()),
                ("Open Shards".to_string(), st.open_shard_count.to_string()),
                ("Retention".to_string(), st.retention_label()),
            ];
            if let Some(n) = st.consumer_count {
                rows.push(("Fan-Out Consumers".to_string(), n.to_string()));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Encryption".to_string(), String::new())); // group header
            rows.push((
                "  At Rest".to_string(),
                if st.is_encrypted() {
                    "✓ KMS".to_string()
                } else {
                    "✗ None".to_string()
                },
            ));
            if let Some(kms) = &st.kms_key_id {
                rows.push(("  KMS Key".to_string(), kms.clone())); // jumpable
            }

            if !st.enhanced_metrics.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Enhanced (Shard-Level) Metrics".to_string(), String::new())); // group header
                for m in &st.enhanced_metrics {
                    rows.push(("  ".to_string(), m.clone()));
                }
            }

            rows.push((String::new(), String::new()));
            rows.push(("Other".to_string(), String::new())); // group header
            if let Some(c) = &st.created {
                rows.push(("  Created".to_string(), c.clone()));
            }
            if !st.arn.is_empty() {
                rows.push(("  ARN".to_string(), st.arn.clone()));
            }
            rows
        }
        KinesisDetailSection::Consumers => match consumers {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading consumers…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                if list.is_empty() {
                    return vec![(
                        "".to_string(),
                        "No enhanced fan-out consumers registered".to_string(),
                    )];
                }
                let mut rows = Vec::new();
                for c in list {
                    rows.push((c.name.clone(), String::new())); // group header
                    rows.push(("  Status".to_string(), c.status.clone()));
                    if let Some(created) = &c.created {
                        rows.push(("  Created".to_string(), created.clone()));
                    }
                    rows.push(("  ARN".to_string(), c.arn.clone()));
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        KinesisDetailSection::Tags => match tags {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading tags…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                if list.is_empty() {
                    return vec![("".to_string(), "No tags".to_string())];
                }
                list.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
            }
        },
    }
}

