fn render_ct_account_split(app: &App, a: &CtAccount, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 3, "");
    let mut block = theme::pane_block("Account", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    // The subtitle is the account's verdict at a glance: where it sits, then
    // whichever of enrolment / violations / drift is actually wrong.
    let (verdict, color) = if a.status.as_deref() == Some("SUSPENDED") {
        ("suspended".to_string(), theme::text_dim())
    } else if a.noncompliant > 0 {
        (
            format!("{} non-compliant", a.noncompliant),
            theme::error(),
        )
    } else if !a.enrolled {
        ("not enrolled".to_string(), theme::warning())
    } else if a.controls_drifted > 0 {
        (format!("{} drifted", a.controls_drifted), theme::warning())
    } else {
        ("compliant".to_string(), theme::success())
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                a.account_name.clone(),
                Style::default().fg(theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                format!("  {}", a.account_id),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                a.ou_path.clone().unwrap_or_else(|| "OU unknown".to_string()),
                Style::default().fg(theme::text_dim()),
            ),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(verdict, Style::default().fg(color)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::controltower::CT_ACCOUNT_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn ct_account_section_lines(
    a: &CtAccount,
    section: CtAccountDetailSection,
    controls: &[&crate::aws::services::controltower::EnabledControl],
    compliance: &[&CtCompliance],
) -> Vec<(String, String)> {
    match section {
        CtAccountDetailSection::Overview => {
            let mut rows = vec![
                ("Account".to_string(), a.account_id.clone()),
                ("Name".to_string(), a.account_name.clone()),
            ];
            if let Some(e) = &a.email {
                rows.push(("Email".to_string(), e.clone()));
            }
            if let Some(s) = &a.status {
                let val = match s.as_str() {
                    "ACTIVE" => format!("✓ {}", s),
                    _ => format!("⚠ {}", s),
                };
                rows.push(("Status".to_string(), val));
            }
            if let Some(m) = &a.joined_method {
                rows.push(("Joined".to_string(), match &a.joined_at {
                    Some(t) => format!("{} ({})", t, m),
                    None => m.clone(),
                }));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Organization".to_string(), String::new())); // group header
            rows.push((
                "  OU".to_string(),
                a.ou_path.clone().unwrap_or_else(|| "unknown".to_string()),
            ));
            // Key-value form so the ou- id classifies as an Enter-jump into
            // Organizations (the "organizations" arm in arn_jump_target).
            if let Some(id) = &a.ou_id {
                rows.push(("  OU ID".to_string(), id.clone()));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Governance".to_string(), String::new())); // group header
            rows.push((
                "  Enrolled".to_string(),
                if a.enrolled {
                    "✓ baseline enabled".to_string()
                } else {
                    "✗ no baseline on this account".to_string()
                },
            ));
            if let Some(s) = &a.baseline_status {
                rows.push(("  Baseline".to_string(), state_mark(s)));
            }
            if let Some(d) = &a.baseline_drift {
                rows.push(("  Baseline Drift".to_string(), drift_mark(d)));
            }
            rows.push(("  Controls".to_string(), a.controls_applied.to_string()));
            if a.controls_drifted > 0 {
                rows.push((
                    "  Controls Drifted".to_string(),
                    format!("⚠ {}", a.controls_drifted),
                ));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Compliance".to_string(), String::new())); // group header
            if a.compliant + a.noncompliant == 0 {
                // Distinguishes "clean" from "the Compliance tab has no data
                // here" — which is the common case outside the audit account.
                rows.push((
                    "  · no aggregated compliance data for this account".to_string(),
                    String::new(),
                ));
            } else {
                rows.push((
                    "  Non-Compliant".to_string(),
                    if a.noncompliant > 0 {
                        format!("✗ {}", a.noncompliant)
                    } else {
                        "0".to_string()
                    },
                ));
                rows.push(("  Compliant".to_string(), a.compliant.to_string()));
            }
            rows
        }
        CtAccountDetailSection::Controls => {
            if controls.is_empty() {
                return vec![(
                    "".to_string(),
                    "No controls enabled on this account or its OU".to_string(),
                )];
            }
            let mut rows = Vec::new();
            for (i, c) in controls.iter().enumerate() {
                if i > 0 {
                    rows.push((String::new(), String::new()));
                }
                rows.push((c.control_name.clone(), String::new())); // group header
                if let Some(s) = &c.severity {
                    rows.push((
                        "  Severity".to_string(),
                        match s.as_str() {
                            "CRITICAL" | "HIGH" => format!("⚠ {}", s),
                            _ => s.clone(),
                        },
                    ));
                }
                if let Some(s) = &c.status {
                    rows.push(("  Status".to_string(), state_mark(s)));
                }
                if let Some(d) = &c.drift_status {
                    rows.push(("  Drift".to_string(), drift_mark(d)));
                }
                // Enabled on the OU vs on the account itself — the difference
                // between org policy and a one-off.
                if let Some(t) = &c.target_name {
                    rows.push(("  Target".to_string(), t.clone()));
                }
            }
            rows
        }
        CtAccountDetailSection::Compliance => {
            if compliance.is_empty() {
                return vec![(
                    "".to_string(),
                    "No aggregated compliance data for this account".to_string(),
                )];
            }
            // Violations first — the reason anyone opens this section.
            let mut sorted: Vec<&&CtCompliance> = compliance.iter().collect();
            sorted.sort_by_key(|c| c.compliance.as_deref() != Some("NON_COMPLIANT"));
            let mut rows = Vec::new();
            for (i, c) in sorted.iter().enumerate() {
                if i > 0 {
                    rows.push((String::new(), String::new()));
                }
                rows.push((
                    c.control_name.clone().unwrap_or_else(|| c.control_label.clone()),
                    String::new(),
                )); // group header
                if let Some(comp) = &c.compliance {
                    rows.push((
                        "  Compliance".to_string(),
                        match comp.as_str() {
                            "NON_COMPLIANT" => format!("✗ {}", comp),
                            "COMPLIANT" => format!("✓ {}", comp),
                            _ => comp.clone(),
                        },
                    ));
                }
                if let Some((count, capped)) = c.noncompliant_count {
                    rows.push((
                        "  Resources".to_string(),
                        if capped {
                            format!("{}+ (count capped)", count)
                        } else {
                            count.to_string()
                        },
                    ));
                }
                rows.push(("  Source".to_string(), c.source.to_string()));
                rows.push(("  Region".to_string(), c.region.clone()));
            }
            rows
        }
    }
}

/// Drift status → row text. Only `DRIFTED` is a problem; `IN_SYNC` is a clean
/// ✓, and `NOT_CHECKING` / `UNKNOWN` render as a dim annotation (the `· `
/// convention) rather than a ✓ that overstates what was actually verified.
fn drift_mark(drift: &str) -> String {
    match drift {
        crate::aws::services::controltower::DRIFTED => format!("✗ {}", drift),
        "IN_SYNC" => format!("✓ {}", drift),
        _ => format!("· {}", drift),
    }
}

/// Control Tower status strings (`SUCCEEDED` / `FAILED` / `UNDER_CHANGE`).
fn state_mark(status: &str) -> String {
    match status {
        "SUCCEEDED" => format!("✓ {}", status),
        s if s.contains("FAILED") => format!("✗ {}", status),
        _ => format!("⚠ {}", status),
    }
}

fn render_ct_compliance_split(app: &App, c: &CtCompliance, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 2, "");
    let mut block = theme::pane_block("Compliance", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let (label, color) = match c.compliance.as_deref() {
        Some("NON_COMPLIANT") => ("NON_COMPLIANT".to_string(), theme::error()),
        Some("COMPLIANT") => ("COMPLIANT".to_string(), theme::success()),
        Some(other) => (other.to_string(), theme::text_dim()),
        None => ("unknown".to_string(), theme::text_dim()),
    };
    let account = c
        .account_name
        .clone()
        .unwrap_or_else(|| c.account_id.clone());
    // Second line carries the raw guardrail slug only when the catalog
    // resolved a friendlier title for the first — never the slug twice.
    let mut subtitle = vec![
        Span::raw("  "),
        Span::styled(
            format!("{} · {}", account, c.region),
            Style::default().fg(theme::text_dim()),
        ),
        Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
        Span::styled(label, Style::default().fg(color)),
    ];
    if let Some(sev) = &c.severity {
        subtitle.push(Span::styled("  ·  ", Style::default().fg(theme::text_dim())));
        subtitle.push(Span::styled(
            sev.clone(),
            Style::default().fg(severity_color(sev)),
        ));
    }
    subtitle.push(Span::styled(
        format!("  ·  {}", c.source),
        Style::default().fg(theme::text_dim()),
    ));
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                c.control_name.clone().unwrap_or_else(|| c.control_label.clone()),
                Style::default().fg(theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                match &c.control_name {
                    Some(_) => format!("  {}", c.control_label),
                    None => String::new(),
                },
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::from(subtitle),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::controltower::CT_COMPLIANCE_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn ct_compliance_section_lines(
    c: &CtCompliance,
    section: CtComplianceDetailSection,
    resources: Option<&Lazy<Vec<CtComplianceResource>>>,
) -> Vec<(String, String)> {
    match section {
        CtComplianceDetailSection::Overview => {
            let mut rows = vec![("Control".to_string(), c.control_label.clone())];
            if let Some(n) = &c.control_name {
                rows.push(("Name".to_string(), n.clone()));
            }
            if let Some(s) = &c.severity {
                let val = match s.as_str() {
                    "CRITICAL" | "HIGH" => format!("⚠ {}", s),
                    _ => s.clone(),
                };
                rows.push(("Severity".to_string(), val));
            }
            // Which system deployed the rule — where you'd go to change it.
            rows.push(("Source".to_string(), c.source.to_string()));
            rows.push(("Config Rule".to_string(), c.rule_name.clone()));
            if let Some(d) = &c.control_description {
                rows.push((String::new(), String::new()));
                rows.push(("Description".to_string(), String::new())); // group header
                for line in crate::aws::services::controltower::wrap_words(d, 90) {
                    rows.push((format!(" {}", line), String::new()));
                }
            }
            rows.extend([
                (String::new(), String::new()),
                ("Account".to_string(), c.account_id.clone()),
            ]);
            if let Some(n) = &c.account_name {
                rows.push(("Account Name".to_string(), n.clone()));
            }
            rows.push(("Region".to_string(), c.region.clone()));
            rows.push((String::new(), String::new()));
            if let Some(comp) = &c.compliance {
                let val = match comp.as_str() {
                    "NON_COMPLIANT" => format!("✗ {}", comp),
                    "COMPLIANT" => format!("✓ {}", comp),
                    _ => comp.clone(),
                };
                rows.push(("Compliance".to_string(), val));
            }
            if let Some((count, capped)) = c.noncompliant_count {
                let val = if capped {
                    format!("{}+ (count capped)", count)
                } else {
                    count.to_string()
                };
                rows.push(("Non-Compliant Resources".to_string(), val));
            }
            rows.push(("Aggregator".to_string(), c.aggregator.clone()));
            // Where the aggregator was read from, when that isn't the account
            // being browsed — otherwise this row's provenance is invisible.
            if let Some(src) = &c.source_account {
                rows.push(("Aggregator Account".to_string(), src.clone()));
            }
            rows
        }
        CtComplianceDetailSection::Resources => match resources {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading resources…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) if list.is_empty() => {
                vec![("".to_string(), "No non-compliant resources".to_string())]
            }
            Some(Lazy::Loaded(list)) => {
                let mut rows = Vec::new();
                for (i, r) in list.iter().enumerate() {
                    if i > 0 {
                        rows.push((String::new(), String::new()));
                    }
                    rows.push((r.resource_type.clone(), String::new())); // group header
                    // Key-value form so id prefixes (i-, vol-, sg-, …)
                    // classify as Enter-jumpable where the type is browsable.
                    rows.push(("  Resource".to_string(), r.resource_id.clone()));
                    if let Some(a) = &r.annotation {
                        rows.push(("  Annotation".to_string(), a.clone()));
                    }
                    if let Some(t) = &r.recorded {
                        rows.push(("  Recorded".to_string(), t.clone()));
                    }
                }
                rows
            }
        },
    }
}

/// Shared status/drift → (label, color) for the Control Tower pane headers.
fn tower_status_label(
    status: &Option<String>,
    drift: &Option<String>,
) -> (String, ratatui::style::Color) {
    match (status.as_deref(), drift.as_deref()) {
        (_, Some("DRIFTED")) => ("DRIFTED".to_string(), theme::error()),
        (Some("FAILED"), _) => ("FAILED".to_string(), theme::error()),
        (Some("UNDER_CHANGE"), _) => ("UNDER_CHANGE".to_string(), theme::warning()),
        (Some(s), _) => (s.to_string(), theme::success()),
        (None, _) => ("unknown".to_string(), theme::text_dim()),
    }
}

/// Shared Tags-section rows for the three Control Tower panes (one lazy map).
fn tower_tag_rows(tags: Option<&Lazy<Vec<(String, String)>>>) -> Vec<(String, String)> {
    match tags {
        None | Some(Lazy::Loading) => vec![("".to_string(), "Loading tags…".to_string())],
        Some(Lazy::Error(e)) => error_rows(e),
        Some(Lazy::Loaded(list)) if list.is_empty() => {
            vec![("".to_string(), "No tags".to_string())]
        }
        Some(Lazy::Loaded(list)) => list.iter().map(|(k, v)| (k.clone(), v.clone())).collect(),
    }
}

fn render_opensearch_split(app: &App, d: &OpenSearchDomain, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 5, "");
    let mut block = theme::pane_block("OpenSearch Domain", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let status = d.status_label();
    let state_color = match status.as_str() {
        "Active" => theme::success(),
        "Isolated" => theme::error(),
        "Creating" | "Deleting" => theme::text_dim(),
        _ => theme::warning(), // Modifying / Upgrading / Updating / Processing
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                d.domain_name.clone(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(d.engine_version.clone(), Style::default().fg(theme::text_dim())),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled(status, Style::default().fg(state_color)),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(
        app,
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::opensearch::OPENSEARCH_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn opensearch_section_lines(
    d: &OpenSearchDomain,
    section: OpenSearchDetailSection,
    tags: Option<&Lazy<Vec<(String, String)>>>,
) -> Vec<(String, String)> {
    let yn = |b: bool| {
        if b {
            "✓ Enabled".to_string()
        } else {
            "✗ Disabled".to_string()
        }
    };
    match section {
        OpenSearchDetailSection::Details => {
            let mut rows = vec![
                ("Name".to_string(), d.domain_name.clone()),
                ("Domain ID".to_string(), d.domain_id.clone()),
                ("Engine".to_string(), d.engine_version.clone()),
                ("Status".to_string(), d.status_label()),
            ];
            if let Some(ep) = &d.endpoint {
                rows.push(("Endpoint".to_string(), ep.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Operations".to_string(), String::new())); // group header
            if let Some(at) = &d.auto_tune {
                rows.push(("  Auto-Tune".to_string(), at.clone()));
            }
            if let Some(h) = d.snapshot_hour {
                rows.push(("  Auto-Snapshot Hour".to_string(), format!("{:02}:00 UTC", h)));
            }
            rows.push((
                "  Change In Progress".to_string(),
                if d.processing { "yes".to_string() } else { "no".to_string() },
            ));
            if !d.arn.is_empty() {
                rows.push(("  ARN".to_string(), d.arn.clone()));
            }
            rows
        }
        OpenSearchDetailSection::Cluster => {
            let mut rows = vec![
                ("Data Nodes".to_string(), String::new()), // group header
                ("  Instance Type".to_string(), d.instance_type.clone()),
                ("  Instance Count".to_string(), d.instance_count.to_string()),
            ];
            rows.push((
                "  Zone Awareness".to_string(),
                if d.zone_awareness_enabled {
                    match d.availability_zone_count {
                        Some(n) => format!("enabled ({} AZ)", n),
                        None => "enabled".to_string(),
                    }
                } else {
                    "disabled".to_string()
                },
            ));
            if d.multi_az_standby {
                rows.push(("  Multi-AZ w/ Standby".to_string(), "✓ Enabled".to_string()));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Dedicated Master".to_string(), String::new())); // group header
            if d.dedicated_master_enabled {
                if let Some(t) = &d.dedicated_master_type {
                    rows.push(("  Type".to_string(), t.clone()));
                }
                if let Some(c) = d.dedicated_master_count {
                    rows.push(("  Count".to_string(), c.to_string()));
                }
            } else {
                rows.push(("  Enabled".to_string(), "✗ Disabled".to_string()));
            }

            if d.warm_enabled || d.cold_storage_enabled {
                rows.push((String::new(), String::new()));
                rows.push(("Tiered Storage".to_string(), String::new())); // group header
                if d.warm_enabled {
                    let wt = d.warm_type.clone().unwrap_or_default();
                    let wc = d.warm_count.map(|c| c.to_string()).unwrap_or_default();
                    rows.push(("  UltraWarm".to_string(), format!("{} × {}", wc, wt)));
                }
                if d.cold_storage_enabled {
                    rows.push(("  Cold Storage".to_string(), "✓ Enabled".to_string()));
                }
            }

            rows.push((String::new(), String::new()));
            rows.push(("Storage (EBS)".to_string(), String::new())); // group header
            if d.ebs_enabled {
                if let Some(t) = &d.volume_type {
                    rows.push(("  Volume Type".to_string(), t.clone()));
                }
                if let Some(s) = d.volume_size {
                    rows.push(("  Volume Size".to_string(), format!("{} GiB", s)));
                }
                if let Some(i) = d.volume_iops {
                    rows.push(("  IOPS".to_string(), i.to_string()));
                }
                if let Some(t) = d.volume_throughput {
                    rows.push(("  Throughput".to_string(), format!("{} MiB/s", t)));
                }
            } else {
                rows.push(("  EBS".to_string(), "instance storage".to_string()));
            }
            rows
        }
        OpenSearchDetailSection::Network => {
            let mut rows = Vec::new();
            if let Some(ep) = &d.endpoint {
                rows.push(("Endpoint".to_string(), ep.clone()));
            }
            for ve in &d.vpc_endpoints {
                rows.push(("VPC Endpoint".to_string(), ve.clone()));
            }
            if let Some(ce) = &d.custom_endpoint {
                rows.push(("Custom Endpoint".to_string(), ce.clone()));
            }
            if let Some(e) = d.enforce_https {
                rows.push(("Enforce HTTPS".to_string(), yn(e)));
            }
            if let Some(t) = &d.tls_policy {
                rows.push(("TLS Policy".to_string(), t.clone()));
            }

            if d.vpc_id.is_some() || !d.subnet_ids.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("VPC".to_string(), String::new())); // group header
                if let Some(v) = &d.vpc_id {
                    rows.push(("  VPC".to_string(), v.clone())); // vpc- jumpable
                }
                for sn in &d.subnet_ids {
                    rows.push(("  Subnet".to_string(), sn.clone())); // subnet- jumpable
                }
                for sg in &d.security_group_ids {
                    rows.push(("  Security Group".to_string(), sg.clone())); // sg- jumpable
                }
                for az in &d.availability_zones {
                    rows.push(("  Availability Zone".to_string(), az.clone()));
                }
            } else {
                rows.push((String::new(), String::new()));
                rows.push(("Access".to_string(), "Public endpoint".to_string()));
            }
            rows
        }
        OpenSearchDetailSection::Security => {
            let mut rows = vec![
                ("Encryption".to_string(), String::new()), // group header
                ("  At Rest".to_string(), yn(d.encryption_at_rest)),
            ];
            if let Some(kms) = &d.kms_key_id {
                rows.push(("  KMS Key".to_string(), kms.clone())); // arn jumpable
            }
            rows.push(("  Node-to-Node".to_string(), yn(d.node_to_node_encryption)));

            rows.push((String::new(), String::new()));
            rows.push(("Access Control".to_string(), String::new())); // group header
            rows.push(("  Fine-Grained Access".to_string(), yn(d.fine_grained_access)));
            if d.fine_grained_access {
                rows.push((
                    "  Internal User DB".to_string(),
                    yn(d.internal_user_db),
                ));
            }
            rows.push(("  Cognito Auth".to_string(), yn(d.cognito_enabled)));
            if let Some(up) = &d.cognito_user_pool_id {
                rows.push(("  Cognito User Pool".to_string(), up.clone()));
            }

            rows.push((String::new(), String::new()));
            rows.push(("Resource Policy".to_string(), String::new())); // group header
            if d.access_policies.is_some() {
                rows.push((
                    "  Access Policy".to_string(),
                    "set — press v to view".to_string(),
                ));
            } else {
                rows.push(("  Access Policy".to_string(), "none".to_string()));
            }
            rows
        }
        OpenSearchDetailSection::Tags => match tags {
            None | Some(Lazy::Loading) => {
                vec![("".to_string(), "Loading tags…".to_string())]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                if list.is_empty() {
                    return vec![("".to_string(), "No tags".to_string())];
                }
                list.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
            }
        },
    }
}

