/// Provisioning rows shared by IC users and groups: external IDs reveal SCIM
/// provisioning from an external IdP — the closest public-API signal for the
/// configured identity source.
fn ic_provisioning_rows(
    rows: &mut Vec<(String, String)>,
    external_ids: &[(String, String)],
    created_at: Option<&str>,
    created_by: Option<&str>,
    updated_at: Option<&str>,
    updated_by: Option<&str>,
) {
    rows.push((String::new(), String::new()));
    rows.push(("Provisioning".to_string(), String::new()));
    if external_ids.is_empty() {
        rows.push((
            "Source".to_string(),
            "Identity Center directory (no external IDs)".to_string(),
        ));
    } else {
        rows.push(("Source".to_string(), "External IdP (SCIM)".to_string()));
        for (issuer, id) in external_ids {
            rows.push((format!("  {}", issuer), id.clone()));
        }
    }
    if created_at.is_some() || updated_at.is_some() {
        rows.push((String::new(), String::new()));
        if let Some(c) = created_at {
            rows.push(("Created".to_string(), c.to_string()));
        }
        if let Some(c) = created_by {
            rows.push(("Created By".to_string(), c.to_string()));
        }
        if let Some(u) = updated_at {
            rows.push(("Updated".to_string(), u.to_string()));
        }
        if let Some(u) = updated_by {
            rows.push(("Updated By".to_string(), u.to_string()));
        }
    }
}

/// Shared Access section body for IC users and groups: every (account,
/// permission set) the principal can reach — direct assignments first, then
/// per contributing group. Permission-set rows carry the PS ARN so `Enter`
/// jumps to the permission set; Account rows jump to Organizations.
fn ic_access_lines(
    state: Option<&Lazy<Vec<crate::aws::services::identity_center::IcAccessEntry>>>,
    account_names: &std::collections::HashMap<String, String>,
    is_group: bool,
) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    match state {
        None | Some(Lazy::Loading) => {
            rows.push(("  Loading…".to_string(), "".to_string()));
        }
        Some(Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(Lazy::Loaded(list)) if list.is_empty() => {
            rows.push((
                "  No account access assigned.".to_string(),
                "".to_string(),
            ));
        }
        Some(Lazy::Loaded(list)) => {
            let mut current_via: Option<&Option<String>> = None;
            let mut current_account = String::new();
            for e in list {
                if current_via != Some(&e.via_group) {
                    if current_via.is_some() {
                        rows.push((String::new(), String::new()));
                    }
                    let count = list.iter().filter(|x| x.via_group == e.via_group).count();
                    let header = match &e.via_group {
                        None if is_group => format!("Assignments ({})", count),
                        None => format!("Direct assignments ({})", count),
                        Some(g) => format!("Via group {} ({})", g, count),
                    };
                    rows.push((header, String::new()));
                    current_via = Some(&e.via_group);
                    current_account.clear();
                }
                if e.account_id != current_account {
                    rows.push((
                        "Account".to_string(),
                        ic_account_label(&e.account_id, account_names),
                    ));
                    current_account = e.account_id.clone();
                }
                // Value is the PS ARN → Enter jumps to the permission set.
                rows.push((format!("  {}", e.ps_name), e.ps_arn.clone()));
            }
        }
    }
    rows
}

pub fn ic_group_section_lines(
    g: &crate::aws::services::identity_center::IcGroup,
    section: IcGroupDetailSection,
    members: Option<&Lazy<Vec<crate::aws::services::identity_center::IcMember>>>,
    access: Option<&Lazy<Vec<crate::aws::services::identity_center::IcAccessEntry>>>,
    account_names: &std::collections::HashMap<String, String>,
) -> Vec<(String, String)> {
    match section {
        IcGroupDetailSection::Details => {
            let mut rows = vec![("Display Name".to_string(), g.display_name.clone())];
            if !g.description.is_empty() {
                rows.push(("Description".to_string(), g.description.clone()));
            }
            rows.push(("Group ID".to_string(), g.group_id.clone()));
            ic_provisioning_rows(
                &mut rows,
                &g.external_ids,
                g.created_at.as_deref(),
                g.created_by.as_deref(),
                g.updated_at.as_deref(),
                g.updated_by.as_deref(),
            );
            rows
        }
        IcGroupDetailSection::Members => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match members {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push(("  (no members)".to_string(), "".to_string()));
                }
                Some(Lazy::Loaded(list)) => {
                    rows.push((format!("Members ({})", list.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for m in list {
                        rows.push((format!("  {}", m.name), m.user_id.clone()));
                    }
                }
            }
            rows
        }
        IcGroupDetailSection::Access => ic_access_lines(access, account_names, true),
    }
}

pub fn ic_user_section_lines(
    u: &crate::aws::services::identity_center::IcUser,
    section: IcUserDetailSection,
    groups: Option<&Lazy<Vec<crate::aws::services::identity_center::IcGroupRef>>>,
    access: Option<&Lazy<Vec<crate::aws::services::identity_center::IcAccessEntry>>>,
    account_names: &std::collections::HashMap<String, String>,
) -> Vec<(String, String)> {
    match section {
        IcUserDetailSection::Details => {
            let mut rows = vec![("Username".to_string(), u.username.clone())];
            if !u.display_name.is_empty() {
                rows.push(("Display Name".to_string(), u.display_name.clone()));
            }
            if let Some(email) = &u.email {
                rows.push(("Email".to_string(), email.clone()));
            }
            if let Some(status) = &u.status {
                let v = if status == "DISABLED" {
                    "✗ DISABLED".to_string()
                } else {
                    status.clone()
                };
                rows.push(("Status".to_string(), v));
            }
            match (&u.given_name, &u.family_name) {
                (Some(g), Some(f)) => rows.push(("Name".to_string(), format!("{} {}", g, f))),
                (Some(g), None) => rows.push(("Name".to_string(), g.clone())),
                (None, Some(f)) => rows.push(("Name".to_string(), f.clone())),
                (None, None) => {}
            }
            if let Some(title) = &u.title {
                rows.push(("Title".to_string(), title.clone()));
            }
            if let Some(t) = &u.user_type {
                rows.push(("User Type".to_string(), t.clone()));
            }
            rows.push(("User ID".to_string(), u.user_id.clone()));
            ic_provisioning_rows(
                &mut rows,
                &u.external_ids,
                u.created_at.as_deref(),
                u.created_by.as_deref(),
                u.updated_at.as_deref(),
                u.updated_by.as_deref(),
            );
            rows
        }
        IcUserDetailSection::Groups => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match groups {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push(("  (no group memberships)".to_string(), "".to_string()));
                }
                Some(Lazy::Loaded(list)) => {
                    rows.push((format!("Groups ({})", list.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for grp in list {
                        rows.push((format!("  {}", grp.name), grp.group_id.clone()));
                    }
                }
            }
            rows
        }
        IcUserDetailSection::Access => ic_access_lines(access, account_names, false),
    }
}

pub fn ic_instance_section_lines(
    inst: &crate::aws::services::identity_center::IcInstance,
    section: IcInstanceDetailSection,
    abac: Option<&Lazy<Option<crate::aws::services::identity_center::IcAbac>>>,
    tti: Option<&Lazy<Vec<crate::aws::services::identity_center::IcTti>>>,
    counts: (usize, usize, usize, usize),
) -> Vec<(String, String)> {
    match section {
        IcInstanceDetailSection::Overview => {
            let mut rows = Vec::new();
            if !inst.name.is_empty() {
                rows.push(("Name".to_string(), inst.name.clone()));
            }
            rows.push(("Status".to_string(), inst.status.clone()));
            if let Some(r) = &inst.status_reason {
                rows.push(("Status Reason".to_string(), r.clone()));
            }
            rows.push(("Instance ARN".to_string(), inst.instance_arn.clone()));
            rows.push((
                "Identity Store ID".to_string(),
                inst.identity_store_id.clone(),
            ));
            if !inst.owner_account_id.is_empty() {
                rows.push(("Owner Account".to_string(), inst.owner_account_id.clone()));
            }
            if let Some(c) = &inst.created_date {
                rows.push(("Created".to_string(), c.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Encryption".to_string(), String::new()));
            match &inst.encryption_key_type {
                Some(t) => {
                    rows.push(("Key Type".to_string(), t.clone()));
                    if let Some(arn) = &inst.encryption_kms_key_arn {
                        // KMS key ARN → jumpable.
                        rows.push(("KMS Key".to_string(), arn.clone()));
                    }
                    if let Some(s) = &inst.encryption_status {
                        rows.push(("Encryption Status".to_string(), s.clone()));
                    }
                    if let Some(r) = &inst.encryption_status_reason {
                        rows.push(("Reason".to_string(), r.clone()));
                    }
                }
                None => rows.push((
                    "Key Type".to_string(),
                    "AWS owned key (default)".to_string(),
                )),
            }
            rows.push((String::new(), String::new()));
            rows.push((
                "  MFA policy, session duration, and the identity source have no public read API — view them in the console."
                    .to_string(),
                String::new(),
            ));
            rows
        }
        IcInstanceDetailSection::Abac => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match abac {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(Lazy::Loaded(None)) => {
                    rows.push((
                        "  Attribute-based access control is not configured.".to_string(),
                        "".to_string(),
                    ));
                    rows.push((String::new(), String::new()));
                    rows.push((
                        "  ABAC maps identity-source attributes onto sessions so permission-set policies can filter on ${aws:PrincipalTag/...}."
                            .to_string(),
                        String::new(),
                    ));
                }
                Some(Lazy::Loaded(Some(a))) => {
                    rows.push(("Status".to_string(), a.status.clone()));
                    if let Some(r) = &a.status_reason {
                        rows.push(("Status Reason".to_string(), r.clone()));
                    }
                    rows.push((String::new(), String::new()));
                    rows.push((
                        format!("Access Control Attributes ({})", a.attributes.len()),
                        String::new(),
                    ));
                    if a.attributes.is_empty() {
                        rows.push(("  none".to_string(), "".to_string()));
                    }
                    for (key, sources) in &a.attributes {
                        rows.push((format!("  {}", key), sources.clone()));
                    }
                }
            }
            rows
        }
        IcInstanceDetailSection::TrustedIssuers => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match tti {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push((
                        "  No trusted token issuers configured.".to_string(),
                        "".to_string(),
                    ));
                    rows.push((String::new(), String::new()));
                    rows.push((
                        "  Trusted token issuers let external IdP tokens propagate identity into AWS services (trusted identity propagation)."
                            .to_string(),
                        String::new(),
                    ));
                }
                Some(Lazy::Loaded(list)) => {
                    for (i, t) in list.iter().enumerate() {
                        if i > 0 {
                            rows.push((String::new(), String::new()));
                        }
                        rows.push((t.name.clone(), String::new()));
                        rows.push(("Type".to_string(), t.issuer_type.clone()));
                        if let Some(u) = &t.issuer_url {
                            rows.push(("Issuer URL".to_string(), u.clone()));
                        }
                        if let Some(c) = &t.claim_attribute_path {
                            rows.push(("Claim Attribute".to_string(), c.clone()));
                        }
                        if let Some(p) = &t.identity_store_attribute_path {
                            rows.push(("Store Attribute".to_string(), p.clone()));
                        }
                        if let Some(j) = &t.jwks_retrieval {
                            rows.push(("JWKS Retrieval".to_string(), j.clone()));
                        }
                        rows.push(("ARN".to_string(), t.arn.clone()));
                    }
                }
            }
            rows
        }
        IcInstanceDetailSection::Summary => {
            let (ps, users, groups, apps) = counts;
            vec![
                ("Permission Sets".to_string(), ps.to_string()),
                ("Users".to_string(), users.to_string()),
                ("Groups".to_string(), groups.to_string()),
                ("Applications".to_string(), apps.to_string()),
                (String::new(), String::new()),
                (
                    "  Counts reflect the loaded list — sub-tabs 2–5 browse each type."
                        .to_string(),
                    String::new(),
                ),
            ]
        }
    }
}

pub fn ic_application_section_lines(
    a: &crate::aws::services::identity_center::IcApplication,
    section: IcApplicationDetailSection,
    assignments: Option<&Lazy<Box<crate::aws::services::identity_center::IcAppAssignments>>>,
) -> Vec<(String, String)> {
    match section {
        IcApplicationDetailSection::Overview => {
            let mut rows = vec![
                ("Name".to_string(), a.name.clone()),
                ("Provider".to_string(), a.provider_name().to_string()),
                ("Status".to_string(), a.status.clone()),
            ];
            if !a.description.is_empty() {
                rows.push(("Description".to_string(), a.description.clone()));
            }
            if !a.application_account.is_empty() {
                rows.push(("Account".to_string(), a.application_account.clone()));
            }
            if let Some(c) = &a.created_date {
                rows.push(("Created".to_string(), c.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Portal".to_string(), String::new()));
            rows.push((
                "Visibility".to_string(),
                a.visibility.clone().unwrap_or_else(|| "—".to_string()),
            ));
            rows.push((
                "Sign-in Origin".to_string(),
                a.sign_in_origin.clone().unwrap_or_else(|| "—".to_string()),
            ));
            if let Some(u) = &a.application_url {
                rows.push(("Application URL".to_string(), u.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("ARN".to_string(), a.arn.clone()));
            rows
        }
        IcApplicationDetailSection::Assignments => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match assignments {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(Lazy::Loaded(a)) => {
                    if let Some(req) = a.assignment_required {
                        rows.push((
                            "Assignment Required".to_string(),
                            if req { "✓ yes".to_string() } else { "no".to_string() },
                        ));
                        rows.push((String::new(), String::new()));
                    }
                    if a.assignments.is_empty() {
                        let hint = if a.assignment_required == Some(false) {
                            "  No explicit assignments — all users can access (assignment not required)."
                        } else {
                            "  No principals assigned."
                        };
                        rows.push((hint.to_string(), "".to_string()));
                    } else {
                        rows.push((
                            format!("Assigned Principals ({})", a.assignments.len()),
                            String::new(),
                        ));
                        rows.push((String::new(), String::new()));
                        for p in &a.assignments {
                            rows.push((
                                format!("  {}", p.principal_type),
                                p.principal_name.clone(),
                            ));
                        }
                    }
                }
            }
            rows
        }
    }
}

// ── Security group split pane (EC2 + VPC, shared) ────────────────────────────

#[allow(clippy::too_many_arguments)]
fn render_security_group_split(
    app: &App,
    name: &str,
    group_id: &str,
    vpc_id: Option<&str>,
    description: &str,
    area: Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");
    let mut block = theme::pane_block("Security Group", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let subtitle = match vpc_id {
        Some(v) if !v.is_empty() => format!("{}  ·  {}", group_id, v),
        _ => group_id.to_string(),
    };
    let mut header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                name.to_string(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(subtitle, Style::default().fg(theme::text_dim())),
        ]),
    ];
    if !description.is_empty() {
        header.push(Line::from(vec![
            Span::raw("  "),
            Span::styled(description.to_string(), Style::default().fg(theme::text_dim())),
        ]));
    }
    header.push(Line::raw(""));
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(app, chunks[2], frame, &descriptor_tabs(app, &crate::aws::services::ec2::SECURITY_GROUP_SECTIONS));
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn security_group_section_lines(
    section: SecurityGroupDetailSection,
    inbound: &[crate::aws::services::ec2::SgRule],
    outbound: &[crate::aws::services::ec2::SgRule],
    tags: &std::collections::HashMap<String, String>,
    used_by: Option<&crate::lazy::Lazy<Vec<crate::aws::services::ec2::SgEni>>>,
) -> Vec<(String, String)> {
    use crate::aws::services::ec2::sg_rule_rows;
    match section {
        // Rule rows already carry the sg-/pl-/CIDR token, so referenced security
        // groups are Enter-jumpable via the generic resource_jump_target.
        SecurityGroupDetailSection::Inbound => sg_rule_rows("Inbound", inbound),
        SecurityGroupDetailSection::Outbound => sg_rule_rows("Outbound", outbound),
        SecurityGroupDetailSection::UsedBy => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match used_by {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(crate::lazy::Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(crate::lazy::Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push((
                        "  Not attached to any network interface.".to_string(),
                        "".to_string(),
                    ));
                }
                Some(crate::lazy::Lazy::Loaded(list)) => {
                    rows.push((format!("Network Interfaces ({})", list.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for e in list {
                        // eni id in the key → Enter jumps to the network interface.
                        let mut ctx = Vec::new();
                        if !e.attached_to.is_empty() {
                            ctx.push(e.attached_to.clone());
                        }
                        if !e.private_ip.is_empty() {
                            ctx.push(e.private_ip.clone());
                        }
                        if !e.status.is_empty() {
                            ctx.push(e.status.clone());
                        }
                        rows.push((e.eni_id.clone(), ctx.join("  ·  ")));
                        if !e.description.is_empty() {
                            rows.push((format!("  {}", e.description), "".to_string()));
                        }
                    }
                }
            }
            rows
        }
        SecurityGroupDetailSection::Tags => tag_rows(tags),
    }
}

// ── EBS volume split pane ────────────────────────────────────────────────────

fn render_ebs_volume_split(
    app: &App,
    vol: &crate::aws::services::ec2::EbsVolume,
    area: Rect,
    frame: &mut Frame,
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");
    let mut block = theme::pane_block("EBS Volume", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let (dot, dot_label) = match vol.state.as_str() {
        "in-use" => (theme::success(), "in-use"),
        "available" => (theme::warning(), "available"),
        "error" => (theme::error(), "error"),
        other => (theme::text_dim(), other),
    };
    let name = vol.name();
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                name.to_string(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled("● ", Style::default().fg(dot)),
            Span::styled(dot_label.to_string(), Style::default().fg(dot)),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!(
                    "{}  ·  {} GiB  ·  {}",
                    vol.volume_type, vol.size_gb, vol.availability_zone
                ),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(app, chunks[2], frame, &descriptor_tabs(app, &crate::aws::services::ec2::EBS_VOLUME_SECTIONS));
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn ebs_volume_section_lines(
    vol: &crate::aws::services::ec2::EbsVolume,
    section: EbsVolumeDetailSection,
    snapshots: Option<&crate::lazy::Lazy<Vec<crate::aws::services::ec2::EbsSnapshot>>>,
    optimizer: Option<&Lazy<Option<crate::aws::services::computeoptimizer::OptimizerRec>>>,
    enrollment: Option<&crate::aws::services::computeoptimizer::CoEnrollment>,
) -> Vec<(String, String)> {
    match section {
        EbsVolumeDetailSection::Details => {
            let mut rows = vec![
                ("Volume ID".to_string(), vol.volume_id.clone()),
                ("Type".to_string(), vol.volume_type.clone()),
                ("Size".to_string(), format!("{} GiB", vol.size_gb)),
                ("State".to_string(), vol.state.clone()),
                ("Availability Zone".to_string(), vol.availability_zone.clone()),
            ];
            if let Some(i) = vol.iops {
                rows.push(("IOPS".to_string(), i.to_string()));
            }
            if let Some(t) = vol.throughput {
                rows.push(("Throughput".to_string(), format!("{} MiB/s", t)));
            }
            rows.push((
                "Encrypted".to_string(),
                if vol.encrypted { "✓ yes".to_string() } else { "✗ no".to_string() },
            ));
            if let Some(k) = &vol.kms_key_id {
                rows.push(("KMS Key".to_string(), k.clone()));
            }
            if vol.multi_attach {
                rows.push(("Multi-Attach".to_string(), "enabled".to_string()));
            }
            if !vol.create_time.is_empty() {
                rows.push(("Created".to_string(), vol.create_time.clone()));
            }
            if let Some(s) = &vol.snapshot_id {
                // snap- source → jumps to the Snapshots sub-tab.
                rows.push(("Source Snapshot".to_string(), s.clone()));
            }
            rows
        }
        EbsVolumeDetailSection::Attachments => {
            if vol.attachments.is_empty() {
                return vec![("  Not attached.".to_string(), String::new())];
            }
            let mut rows = vec![(
                format!("Attachments ({})", vol.attachments.len()),
                String::new(),
            )];
            rows.push((String::new(), String::new()));
            for a in &vol.attachments {
                // instance id in value → Enter jumps to the instance.
                rows.push(("Instance".to_string(), a.instance_id.clone()));
                if !a.device.is_empty() {
                    rows.push(("  Device".to_string(), a.device.clone()));
                }
                if !a.state.is_empty() {
                    rows.push(("  State".to_string(), a.state.clone()));
                }
                rows.push((
                    "  Delete on Termination".to_string(),
                    if a.delete_on_termination { "yes".to_string() } else { "no".to_string() },
                ));
                rows.push((String::new(), String::new()));
            }
            rows
        }
        EbsVolumeDetailSection::Snapshots => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match snapshots {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(crate::lazy::Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(crate::lazy::Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push(("  No snapshots of this volume.".to_string(), "".to_string()));
                }
                Some(crate::lazy::Lazy::Loaded(list)) => {
                    rows.push((format!("Snapshots ({})", list.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for s in list {
                        let status = if s.state == "completed" {
                            s.state.clone()
                        } else {
                            format!("{} {}", s.state, s.progress)
                        };
                        rows.push((s.snapshot_id.clone(), status));
                        if !s.started.is_empty() {
                            rows.push(("  Started".to_string(), s.started.clone()));
                        }
                        if !s.description.is_empty() {
                            rows.push((format!("  {}", s.description), "".to_string()));
                        }
                        rows.push(("".to_string(), "".to_string()));
                    }
                }
            }
            rows
        }
        EbsVolumeDetailSection::Tags => tag_rows(&vol.tags),
        EbsVolumeDetailSection::Optimizer => optimizer_lines(optimizer, enrollment),
    }
}

// ── AMI split pane ──────────────────────────────────────────────────────────

fn render_ami_split(app: &App, ami: &crate::aws::services::ec2::Ami, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "");
    let mut block = theme::pane_block("AMI", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let (dot, dot_label) = match ami.state.as_str() {
        "available" => (theme::success(), "available"),
        "pending" | "transient" => (theme::warning(), ami.state.as_str()),
        "failed" | "invalid" | "error" => (theme::error(), ami.state.as_str()),
        "deregistered" => (theme::text_dim(), "deregistered"),
        other => (theme::text_dim(), other),
    };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                ami.name().to_string(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
            Span::styled("  ·  ", Style::default().fg(theme::text_dim())),
            Span::styled("● ", Style::default().fg(dot)),
            Span::styled(dot_label.to_string(), Style::default().fg(dot)),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                format!("{}  ·  {}", ami.image_id, ami.architecture),
                Style::default().fg(theme::text_dim()),
            ),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(app, chunks[2], frame, &descriptor_tabs(app, &crate::aws::services::ec2::AMI_SECTIONS));
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn ami_section_lines(
    ami: &crate::aws::services::ec2::Ami,
    section: AmiDetailSection,
    permissions: Option<&crate::lazy::Lazy<Vec<String>>>,
) -> Vec<(String, String)> {
    match section {
        AmiDetailSection::Details => {
            let mut rows = vec![
                ("Image ID".to_string(), ami.image_id.clone()),
                ("Name".to_string(), ami.name.clone()),
            ];
            if !ami.description.is_empty() {
                rows.push(("Description".to_string(), ami.description.clone()));
            }
            rows.push(("State".to_string(), ami.state.clone()));
            rows.push(("Architecture".to_string(), ami.architecture.clone()));
            rows.push(("Virtualization".to_string(), ami.virtualization_type.clone()));
            rows.push(("Root Device Type".to_string(), ami.root_device_type.clone()));
            if !ami.root_device_name.is_empty() {
                rows.push(("Root Device".to_string(), ami.root_device_name.clone()));
            }
            if !ami.hypervisor.is_empty() {
                rows.push(("Hypervisor".to_string(), ami.hypervisor.clone()));
            }
            rows.push((
                "ENA Support".to_string(),
                if ami.ena_support { "✓ yes".to_string() } else { "✗ no".to_string() },
            ));
            rows.push((
                "Platform".to_string(),
                ami.platform.clone().unwrap_or_else(|| "linux".to_string()),
            ));
            rows.push((
                "Public".to_string(),
                if ami.public { "⚠ yes".to_string() } else { "no".to_string() },
            ));
            if let Some(c) = &ami.creation_date {
                rows.push(("Created".to_string(), c.clone()));
            }
            if let Some(d) = &ami.deprecation_time {
                rows.push(("Deprecation".to_string(), d.clone()));
            }
            rows
        }
        AmiDetailSection::BlockDevices => {
            if ami.block_devices.is_empty() {
                return vec![("  No EBS block devices.".to_string(), String::new())];
            }
            let mut rows = vec![(
                format!("Block Devices ({})", ami.block_devices.len()),
                String::new(),
            )];
            rows.push((String::new(), String::new()));
            for b in &ami.block_devices {
                rows.push(("Device".to_string(), b.device_name.clone()));
                if let Some(s) = &b.snapshot_id {
                    // snap- → Enter jumps to the Snapshots sub-tab.
                    rows.push(("Snapshot".to_string(), s.clone()));
                }
                if b.size_gb > 0 {
                    rows.push(("  Size".to_string(), format!("{} GiB", b.size_gb)));
                }
                if !b.volume_type.is_empty() {
                    rows.push(("  Type".to_string(), b.volume_type.clone()));
                }
                rows.push((
                    "  Delete on Termination".to_string(),
                    if b.delete_on_termination { "yes".to_string() } else { "no".to_string() },
                ));
                rows.push((String::new(), String::new()));
            }
            rows
        }
        AmiDetailSection::Permissions => {
            let mut rows = vec![(String::new(), String::new())];
            match permissions {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), String::new()));
                }
                Some(crate::lazy::Lazy::Error(e)) => {
                    rows.extend(error_rows(e));
                }
                Some(crate::lazy::Lazy::Loaded(list)) if list.is_empty() => {
                    rows.push((
                        "  Private — not shared with any account.".to_string(),
                        String::new(),
                    ));
                }
                Some(crate::lazy::Lazy::Loaded(list)) => {
                    rows.push((format!("Shared with ({})", list.len()), String::new()));
                    rows.push((String::new(), String::new()));
                    for p in list {
                        if p == "public" {
                            rows.push(("Public".to_string(), "⚠ shared with all".to_string()));
                        } else {
                            rows.push(("Account".to_string(), p.clone()));
                        }
                    }
                }
            }
            rows
        }
        AmiDetailSection::Tags => tag_rows(&ami.tags),
    }
}

