pub fn nfw_policy_section_lines(
    policy: &NfwPolicy,
    section: NfwPolicyDetailSection,
) -> Vec<(String, String)> {
    match section {
        NfwPolicyDetailSection::Stateful => {
            let mut rows = vec![("Stateful Default Actions".to_string(), String::new())]; // header
            if policy.stateful_default_actions.is_empty() {
                rows.push((
                    "  (engine default)".to_string(),
                    String::new(),
                ));
            } else {
                for a in &policy.stateful_default_actions {
                    rows.push((format!("  {}", a), String::new()));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push((
                format!("Rule Groups ({})", policy.stateful_rule_groups.len()),
                String::new(),
            )); // header
            if policy.stateful_rule_groups.is_empty() {
                rows.push(("  (none)".to_string(), String::new()));
            } else {
                rows.push((String::new(), String::new()));
                for r in &policy.stateful_rule_groups {
                    let prio = r
                        .priority
                        .map(|p| format!("priority {}", p))
                        .unwrap_or_else(|| "strict-order".to_string());
                    rows.push((format!("{} ·", prio), String::new()));
                    // ARN is a same-service jump anchor (→ Rule Groups tab).
                    rows.push(("  ARN".to_string(), r.arn.clone()));
                }
            }
            rows
        }
        NfwPolicyDetailSection::Stateless => {
            let mut rows = vec![("Stateless Default Actions".to_string(), String::new())]; // header
            if policy.stateless_default_actions.is_empty() {
                rows.push(("  (none)".to_string(), String::new()));
            } else {
                for a in &policy.stateless_default_actions {
                    rows.push((format!("  {}", a), String::new()));
                }
            }
            if !policy.stateless_fragment_default_actions.is_empty() {
                rows.push((String::new(), String::new()));
                rows.push(("Fragment Default Actions".to_string(), String::new())); // header
                for a in &policy.stateless_fragment_default_actions {
                    rows.push((format!("  {}", a), String::new()));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push((
                format!("Rule Groups ({})", policy.stateless_rule_groups.len()),
                String::new(),
            )); // header
            if policy.stateless_rule_groups.is_empty() {
                rows.push(("  (none)".to_string(), String::new()));
            } else {
                rows.push((String::new(), String::new()));
                for r in &policy.stateless_rule_groups {
                    let prio = r
                        .priority
                        .map(|p| format!("priority {}", p))
                        .unwrap_or_else(|| "—".to_string());
                    rows.push((format!("{} ·", prio), String::new()));
                    rows.push(("  ARN".to_string(), r.arn.clone()));
                }
            }
            rows
        }
        NfwPolicyDetailSection::Tags => tag_rows(&policy.tags),
    }
}

// ── Network Firewall: rule group split pane ─────────────────────────────────────

fn render_nfw_rule_group_split(app: &App, rg: &NfwRuleGroup, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 2, "");
    let mut block = theme::pane_block("NFW Rule Group", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let kind_label = if rg.kind.is_empty() { "—".to_string() } else { rg.kind.clone() };
    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                rg.name.clone(),
                Style::default().fg(crate::ui::theme::text_primary()).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(kind_label, Style::default().fg(theme::text_dim())),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(app, 
        chunks[2],
        frame,
        &descriptor_tabs(app, &crate::aws::services::network_firewall::NFW_RULE_GROUP_SECTIONS),
    );
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

pub fn nfw_rule_group_section_lines(
    rg: &NfwRuleGroup,
    section: NfwRuleGroupDetailSection,
    rules: Option<&crate::lazy::Lazy<crate::aws::services::network_firewall::NfwRuleGroupRules>>,
) -> Vec<(String, String)> {
    match section {
        NfwRuleGroupDetailSection::Rules => match rules {
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("".to_string(), "Loading rules…".to_string())]
            }
            Some(crate::lazy::Lazy::Error(e)) => {
                let mut rows = error_rows(e);
                // Add wrapped display lines for readability.
                rows.push((String::new(), String::new()));
                for line in wrap_plain(e, 70) {
                    rows.push((format!("  {}", line), String::new()));
                }
                rows
            }
            Some(crate::lazy::Lazy::Loaded(r)) => {
                let mut rows = vec![
                    (
                        "Type".to_string(),
                        if r.kind.is_empty() { rg.kind.clone() } else { r.kind.clone() },
                    ),
                    ("Capacity".to_string(), r.capacity.to_string()),
                ];
                if !r.description.is_empty() {
                    rows.push(("Description".to_string(), r.description.clone()));
                }
                rows.push((String::new(), String::new()));

                // Suricata-style raw rules text → summary + pointer to `v`.
                if let Some(text) = &r.rules_string {
                    let n = text.lines().filter(|l| !l.trim().is_empty()).count();
                    rows.push(("Suricata Rules".to_string(), String::new())); // header
                    rows.push((
                        format!("  {} rule line(s) — e to edit", n),
                        String::new(),
                    ));
                    rows.push((String::new(), String::new()));
                    // Preview the first few lines inline.
                    for line in text.lines().take(12) {
                        rows.push((format!("  {}", line), String::new()));
                    }
                    if n > 12 {
                        rows.push(("  …".to_string(), String::new()));
                    }
                }

                // Structured stateful 5-tuple rules → table.
                if !r.stateful_rules.is_empty() {
                    rows.push((
                        format!("5-Tuple Rules ({})", r.stateful_rules.len()),
                        String::new(),
                    )); // header
                    rows.push((String::new(), String::new()));
                    rows.push((
                        format!(
                            "  {:<8} {:<6} {:<18} {:<6} {:<4} {:<18} {:<6}",
                            "ACTION", "PROTO", "SOURCE", "SPORT", "DIR", "DEST", "DPORT"
                        ),
                        String::new(),
                    ));
                    for sr in &r.stateful_rules {
                        rows.push((
                            format!(
                                "  {:<8} {:<6} {:<18} {:<6} {:<4} {:<18} {:<6}",
                                truncate_cell(&sr.action, 8),
                                truncate_cell(&sr.protocol, 6),
                                truncate_cell(&sr.source, 18),
                                truncate_cell(&sr.source_port, 6),
                                truncate_cell(&sr.direction, 4),
                                truncate_cell(&sr.destination, 18),
                                truncate_cell(&sr.destination_port, 6),
                            ),
                            String::new(),
                        ));
                        if !sr.options.is_empty() {
                            rows.push((format!("    {}", sr.options), String::new()));
                        }
                    }
                }

                // Domain allow/deny list.
                if !r.domain_targets.is_empty() {
                    rows.push((
                        format!("Domain List ({})", r.domain_targets.len()),
                        String::new(),
                    )); // header
                    if let Some(t) = &r.domain_rules_type {
                        rows.push(("  Type".to_string(), t.clone()));
                    }
                    rows.push((String::new(), String::new()));
                    for d in &r.domain_targets {
                        rows.push((format!("  {}", d), String::new()));
                    }
                }

                // Stateless rule count (full expansion is out of scope v1).
                if r.stateless_rule_count > 0 {
                    rows.push((
                        "Stateless Rules".to_string(),
                        format!("{} rule(s)", r.stateless_rule_count),
                    ));
                }

                if r.rules_string.is_none()
                    && r.stateful_rules.is_empty()
                    && r.domain_targets.is_empty()
                    && r.stateless_rule_count == 0
                {
                    rows.push((String::new(), String::new()));
                    rows.push(("  (no rules in this group)".to_string(), String::new()));
                }
                rows
            }
        },
        NfwRuleGroupDetailSection::Tags => match rules {
            Some(crate::lazy::Lazy::Loaded(r)) => tag_rows(&r.tags),
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("".to_string(), "Loading tags…".to_string())]
            }
            Some(crate::lazy::Lazy::Error(e)) => {
                // Show why the detail fetch failed, then fall back to the
                // tags already present on the list summary.
                let mut rows = error_rows(e);
                rows.push((String::new(), String::new()));
                rows.extend(tag_rows(&rg.tags));
                rows
            }
        },
    }
}

/// Shared skeleton for the U13 flat-straggler split panes: fixed header
/// (bold name + dim subtitle) | rule | section tab bar | rule | generic body.
#[allow(clippy::too_many_arguments)]
/// Tab-bar triples for a descriptor-backed pane — digit keys, labels, and
/// the active flag all derive from the section table.
fn descriptor_tabs(
    app: &App,
    desc: &'static crate::sections::SectionDescriptor,
) -> Vec<(char, &'static str, bool)> {
    let active = app.detail_section_index();
    desc.sections
        .iter()
        .enumerate()
        .map(|(i, s)| {
            (
                crate::sections::key_for(i).unwrap_or(' '),
                s.label,
                i == active,
            )
        })
        .collect()
}

fn render_simple_split(
    app: &App,
    area: Rect,
    frame: &mut Frame,
    pane_title: &str,
    name: &str,
    subtitle: &str,
    tabs: &[(char, &str, bool)],
) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, tabs.len(), "");
    let mut block = theme::pane_block(pane_title, focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header = vec![
        Line::raw(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(
                name.to_string(),
                Style::default()
                    .fg(crate::ui::theme::text_primary())
                    .add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(subtitle.to_string(), Style::default().fg(theme::text_dim())),
        ]),
        Line::raw(""),
    ];
    let header_h = header.len() as u16;
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);
    frame.render_widget(Paragraph::new(header), chunks[0]);
    render_hr(chunks[1], frame);
    render_section_tab_bar(app, chunks[2], frame, tabs);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn render_vpc_split(app: &App, vpc: &Vpc, area: Rect, frame: &mut Frame) {
    let name = vpc
        .tags
        .get("Name")
        .map(|s| s.as_str())
        .unwrap_or(&vpc.vpc_id);
    let extra = vpc.secondary_cidrs.len() + vpc.ipv6_cidrs.len();
    let subtitle = if extra > 0 {
        format!("{} +{}", vpc.cidr_block, extra)
    } else {
        vpc.cidr_block.clone()
    };
    render_simple_split(
        app,
        area,
        frame,
        "VPC",
        name,
        &subtitle,
        &descriptor_tabs(app, &crate::aws::services::vpc::VPC_SECTIONS),
    );
}

#[allow(clippy::too_many_arguments)]
pub fn vpc_section_lines(
    vpc: &Vpc,
    section: VpcDetailSection,
    subnets: &[&Subnet],
    igws: &[&InternetGateway],
    nats: &[&NatGateway],
    endpoints: &[&VpcEndpoint],
    dhcp: Option<&DhcpOptionsSet>,
    flow_logs: Option<&Lazy<Vec<FlowLogInfo>>>,
    dns_attrs: Option<&Lazy<(bool, bool)>>,
) -> Vec<(String, String)> {
    match section {
        VpcDetailSection::Overview => {
            let mut rows = vec![
                (String::new(), String::new()),
                ("VPC ID".to_string(), vpc.vpc_id.clone()),
                ("State".to_string(), vpc.state.clone()),
                ("CIDR Block".to_string(), vpc.cidr_block.clone()),
            ];
            rows.extend(vpc.cidr_rows());
            rows.push((
                "Default VPC".to_string(),
                if vpc.is_default {
                    "✓ yes".to_string()
                } else {
                    "no".to_string()
                },
            ));
            if let Some(owner) = &vpc.owner_id {
                rows.push(("Owner".to_string(), owner.clone()));
            }
            if let Some(t) = &vpc.instance_tenancy {
                rows.push(("Instance Tenancy".to_string(), t.clone()));
            }
            if let Some(d) = &vpc.dhcp_options_id {
                rows.push(("DHCP Options".to_string(), d.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("DNS / DHCP".to_string(), String::new()));
            // The two attribute flags are a lazy DescribeVpcAttribute pair.
            match dns_attrs {
                None | Some(Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), String::new()));
                }
                Some(Lazy::Error(e)) => rows.extend(error_rows(e)),
                Some(Lazy::Loaded((support, hostnames))) => {
                    let on_off = |on: bool| {
                        if on {
                            "✓ enabled".to_string()
                        } else {
                            "✗ disabled".to_string()
                        }
                    };
                    rows.push(("  DNS Support".to_string(), on_off(*support)));
                    rows.push(("  DNS Hostnames".to_string(), on_off(*hostnames)));
                }
            }
            // Resolved from the sibling DHCP options set — no extra fetch.
            if let Some(d) = dhcp {
                for (k, values) in &d.configs {
                    rows.push((format!("  {}", pretty_dhcp_key(k)), values.join(", ")));
                }
            }
            rows.push((String::new(), String::new()));
            rows.push(("In this VPC".to_string(), String::new()));
            rows.push(("Subnets".to_string(), subnets.len().to_string()));
            rows.push(("Internet Gateways".to_string(), igws.len().to_string()));
            rows.push(("NAT Gateways".to_string(), nats.len().to_string()));
            rows.push(("VPC Endpoints".to_string(), endpoints.len().to_string()));
            rows
        }
        VpcDetailSection::Subnets => {
            let mut rows = vec![(String::new(), String::new())];
            if subnets.is_empty() {
                rows.push(("".to_string(), "No subnets in this VPC".to_string()));
            }
            for s in subnets {
                // IPv6-native subnets have no IPv4 CIDR — show the IPv6 one.
                let cidr = if s.cidr_block == "unknown" {
                    s.ipv6_cidr_blocks
                        .first()
                        .cloned()
                        .unwrap_or_else(|| "—".to_string())
                } else {
                    s.cidr_block.clone()
                };
                rows.push((
                    s.subnet_id.clone(),
                    format!(
                        "{} · {} · {} IPs free",
                        cidr, s.availability_zone, s.available_ip_count
                    ),
                ));
            }
            rows
        }
        VpcDetailSection::Gateways => {
            let mut rows = vec![(String::new(), String::new())];
            rows.push(("Internet Gateways".to_string(), String::new()));
            if igws.is_empty() {
                rows.push(("  none".to_string(), String::new()));
            }
            for g in igws {
                rows.push((g.igw_id.clone(), g.state.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("NAT Gateways".to_string(), String::new()));
            if nats.is_empty() {
                rows.push(("  none".to_string(), String::new()));
            }
            for n in nats {
                let ip = n
                    .public_ip
                    .as_deref()
                    .or(n.private_ip.as_deref())
                    .unwrap_or("—");
                rows.push((n.nat_gateway_id.clone(), format!("{} · {}", n.state, ip)));
            }
            rows.push((String::new(), String::new()));
            rows.push(("VPC Endpoints".to_string(), String::new()));
            if endpoints.is_empty() {
                rows.push(("  none".to_string(), String::new()));
            }
            for e in endpoints {
                rows.push((e.id.clone(), format!("{} · {}", e.kind, e.service_name)));
            }
            rows
        }
        VpcDetailSection::FlowLogs => match flow_logs {
            None | Some(Lazy::Loading) => {
                vec![
                    (String::new(), String::new()),
                    ("  Loading…".to_string(), String::new()),
                ]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(logs)) => {
                let mut rows = vec![(String::new(), String::new())];
                if logs.is_empty() {
                    rows.push((
                        "  No VPC-level flow logs — traffic is not being captured"
                            .to_string(),
                        String::new(),
                    ));
                    rows.push((
                        "  (subnet- or ENI-level flow logs aren't listed here)".to_string(),
                        String::new(),
                    ));
                    return rows;
                }
                for fl in logs {
                    rows.push((fl.id.clone(), String::new()));
                    rows.push((
                        "  Status".to_string(),
                        if fl.status == "ACTIVE" {
                            "✓ active".to_string()
                        } else {
                            fl.status.clone()
                        },
                    ));
                    rows.push(("  Traffic".to_string(), fl.traffic_type.clone()));
                    rows.push((
                        format!("  Destination ({})", fl.dest_type),
                        fl.destination.clone(),
                    ));
                    if fl.log_format_custom {
                        rows.push(("  Format".to_string(), "custom".to_string()));
                    }
                    if let Some(secs) = fl.aggregation_secs {
                        rows.push(("  Aggregation".to_string(), format!("{}s", secs)));
                    }
                    if let Some(err) = &fl.deliver_error {
                        rows.push((format!("  ⚠ delivery: {}", err), String::new()));
                    }
                    rows.push((String::new(), String::new()));
                }
                rows
            }
        },
        VpcDetailSection::Tags => tag_rows(&vpc.tags),
    }
}

fn render_dhcp_options_split(app: &App, dopt: &DhcpOptionsSet, area: Rect, frame: &mut Frame) {
    let name = dopt
        .tags
        .get("Name")
        .map(|s| s.as_str())
        .unwrap_or(&dopt.id);
    let subtitle = dopt
        .values_for("domain-name")
        .unwrap_or_else(|| "DHCP options set".to_string());
    render_simple_split(
        app,
        area,
        frame,
        "DHCP Options",
        name,
        &subtitle,
        &descriptor_tabs(app, &crate::aws::services::vpc::DHCP_OPTIONS_SECTIONS),
    );
}

pub fn dhcp_options_section_lines(
    dopt: &DhcpOptionsSet,
    section: DhcpOptionsDetailSection,
    vpcs: &[&Vpc],
) -> Vec<(String, String)> {
    match section {
        DhcpOptionsDetailSection::Overview => {
            let mut rows = vec![
                (String::new(), String::new()),
                ("ID".to_string(), dopt.id.clone()),
            ];
            if let Some(owner) = &dopt.owner_id {
                rows.push(("Owner".to_string(), owner.clone()));
            }
            rows.push((String::new(), String::new()));
            rows.push(("Configuration".to_string(), String::new()));
            if dopt.configs.is_empty() {
                rows.push(("  no options configured".to_string(), String::new()));
            }
            for (k, values) in &dopt.configs {
                rows.push((format!("  {}", pretty_dhcp_key(k)), values.join(", ")));
            }
            rows.push((String::new(), String::new()));
            rows.push(("VPCs Using".to_string(), vpcs.len().to_string()));
            rows
        }
        DhcpOptionsDetailSection::Vpcs => {
            let mut rows = vec![(String::new(), String::new())];
            if vpcs.is_empty() {
                rows.push((
                    "  No VPCs use this options set".to_string(),
                    String::new(),
                ));
            }
            for v in vpcs {
                let name = v.tags.get("Name").map(|s| s.as_str()).unwrap_or("—");
                rows.push((v.vpc_id.clone(), format!("{} · {}", name, v.cidr_block)));
            }
            rows
        }
        DhcpOptionsDetailSection::Tags => tag_rows(&dopt.tags),
    }
}

fn render_vpc_peering_split(app: &App, peer: &VpcPeering, area: Rect, frame: &mut Frame) {
    let name = peer
        .tags
        .get("Name")
        .map(|s| s.as_str())
        .unwrap_or(&peer.id);
    let subtitle = format!(
        "{} ⇄ {} · {}",
        peer.requester.vpc_id.as_deref().unwrap_or("—"),
        peer.accepter.vpc_id.as_deref().unwrap_or("—"),
        peer.status
    );
    render_simple_split(
        app,
        area,
        frame,
        "Peering Connection",
        name,
        &subtitle,
        &descriptor_tabs(app, &crate::aws::services::vpc::VPC_PEERING_SECTIONS),
    );
}

pub fn vpc_peering_section_lines(
    peer: &VpcPeering,
    section: VpcPeeringDetailSection,
) -> Vec<(String, String)> {
    match section {
        VpcPeeringDetailSection::Overview => {
            let mut rows = vec![
                (String::new(), String::new()),
                ("ID".to_string(), peer.id.clone()),
                ("Status".to_string(), peer.status.clone()),
            ];
            if let Some(m) = &peer.status_message {
                if m != &peer.status {
                    rows.push(("  ".to_string() + m, String::new()));
                }
            }
            if let Some(exp) = &peer.expiration_time {
                rows.push(("Expires".to_string(), exp.clone()));
            }
            let side_rows = |rows: &mut Vec<(String, String)>, label: &str, s: &PeeringSide| {
                rows.push((String::new(), String::new()));
                rows.push((label.to_string(), String::new()));
                rows.push((
                    "  VPC".to_string(),
                    s.vpc_id.clone().unwrap_or_else(|| "—".to_string()),
                ));
                if !s.cidrs.is_empty() {
                    rows.push(("  CIDRs".to_string(), s.cidrs.join(", ")));
                }
                if let Some(o) = &s.owner_id {
                    rows.push(("  Owner".to_string(), o.clone()));
                }
                if let Some(r) = &s.region {
                    rows.push(("  Region".to_string(), r.clone()));
                }
                if let Some(dns) = s.allow_remote_dns {
                    rows.push((
                        "  Remote DNS Resolution".to_string(),
                        if dns {
                            "✓ enabled".to_string()
                        } else {
                            "disabled".to_string()
                        },
                    ));
                }
            };
            side_rows(&mut rows, "Requester", &peer.requester);
            side_rows(&mut rows, "Accepter", &peer.accepter);
            // Cross-account / cross-region peers can't resolve locally.
            let local_owner_differs = peer.requester.owner_id.is_some()
                && peer.requester.owner_id != peer.accepter.owner_id;
            let region_differs = peer.requester.region.is_some()
                && peer.requester.region != peer.accepter.region;
            if local_owner_differs || region_differs {
                rows.push((String::new(), String::new()));
                rows.push((
                    "  VPC jumps only resolve in the browsed account/region".to_string(),
                    String::new(),
                ));
            }
            rows
        }
        VpcPeeringDetailSection::Tags => tag_rows(&peer.tags),
    }
}

fn render_prefix_list_split(app: &App, pl: &PrefixList, area: Rect, frame: &mut Frame) {
    let subtitle = format!(
        "{} · {}",
        pl.address_family.as_deref().unwrap_or("—"),
        if pl.is_aws_managed() {
            "AWS-managed"
        } else {
            "customer-managed"
        }
    );
    render_simple_split(
        app,
        area,
        frame,
        "Prefix List",
        &pl.name,
        &subtitle,
        &descriptor_tabs(app, &crate::aws::services::vpc::PREFIX_LIST_SECTIONS),
    );
}

pub fn prefix_list_section_lines(
    pl: &PrefixList,
    section: PrefixListDetailSection,
    entries: Option<&Lazy<Vec<(String, String)>>>,
) -> Vec<(String, String)> {
    match section {
        PrefixListDetailSection::Overview => {
            let mut rows = vec![
                (String::new(), String::new()),
                ("ID".to_string(), pl.id.clone()),
                ("Name".to_string(), pl.name.clone()),
                ("State".to_string(), pl.state.clone()),
            ];
            if let Some(m) = &pl.state_message {
                rows.push(("  ".to_string() + m, String::new()));
            }
            if let Some(f) = &pl.address_family {
                rows.push(("Address Family".to_string(), f.clone()));
            }
            if let Some(m) = pl.max_entries {
                rows.push(("Max Entries".to_string(), m.to_string()));
            }
            if let Some(v) = pl.version {
                rows.push(("Version".to_string(), v.to_string()));
            }
            rows.push((
                "Owner".to_string(),
                if pl.is_aws_managed() {
                    "AWS (managed list)".to_string()
                } else {
                    pl.owner_id.clone().unwrap_or_else(|| "—".to_string())
                },
            ));
            if let Some(arn) = &pl.arn {
                rows.push(("ARN".to_string(), arn.clone()));
            }
            rows
        }
        PrefixListDetailSection::Entries => match entries {
            None | Some(Lazy::Loading) => {
                vec![
                    (String::new(), String::new()),
                    ("  Loading…".to_string(), String::new()),
                ]
            }
            Some(Lazy::Error(e)) => error_rows(e),
            Some(Lazy::Loaded(list)) => {
                let mut rows = vec![(String::new(), String::new())];
                let cap = pl
                    .max_entries
                    .map(|m| format!(" of max {}", m))
                    .unwrap_or_default();
                rows.push((format!("Entries ({}{})", list.len(), cap), String::new()));
                if list.is_empty() {
                    rows.push(("  no entries".to_string(), String::new()));
                }
                for (cidr, desc) in list {
                    rows.push((format!("  {}", cidr), desc.clone()));
                }
                rows
            }
        },
        PrefixListDetailSection::Tags => tag_rows(&pl.tags),
    }
}

