pub fn route53_profile_section_lines(
    p: &crate::aws::services::route53profiles::Route53Profile,
    section: crate::aws::services::route53profiles::Route53ProfileDetailSection,
    state: Option<
        &crate::lazy::Lazy<Box<crate::aws::services::route53profiles::Route53ProfileDetail>>,
    >,
) -> Vec<(String, String)> {
    use crate::aws::services::route53profiles::Route53ProfileDetailSection as S;
    match section {
        S::Overview => {
            let mut rows = vec![
                ("Name".to_string(), p.name.clone()),
                ("ID".to_string(), p.id.clone()),
                ("ARN".to_string(), p.arn.clone()),
                ("Share Status".to_string(), p.share_status.clone()),
            ];
            match state {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("".to_string(), "".to_string()));
                    rows.push(("  Loading…".to_string(), "".to_string()));
                }
                Some(crate::lazy::Lazy::Error(err)) => {
                    rows.push(("".to_string(), "".to_string()));
                    rows.extend(error_rows(err));
                }
                Some(crate::lazy::Lazy::Loaded(d)) => {
                    rows.push(("".to_string(), "".to_string()));
                    rows.push(("Status".to_string(), d.status.clone()));
                    if !d.status_message.is_empty() {
                        rows.push(("Status Message".to_string(), d.status_message.clone()));
                    }
                    rows.push(("Owner".to_string(), d.owner_id.clone()));
                    if let Some(ct) = &d.creation_time {
                        rows.push(("Created".to_string(), ct.clone()));
                    }
                    if let Some(mt) = &d.modification_time {
                        rows.push(("Modified".to_string(), mt.clone()));
                    }
                }
            }
            rows
        }
        S::Vpcs => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match state {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Error(err)) => rows.extend(error_rows(err)),
                Some(crate::lazy::Lazy::Loaded(d)) if d.vpcs.is_empty() => {
                    rows.push(("  (no VPC associations)".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Loaded(d)) => {
                    rows.push((format!("VPCs ({})", d.vpcs.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for v in &d.vpcs {
                        // vpc_arn carries the raw vpc- token (jumpable to VPC).
                        rows.push(("VPC".to_string(), v.vpc_arn.clone()));
                        rows.push(("Status".to_string(), v.status.clone()));
                        if !v.status_message.is_empty() {
                            rows.push(("Status Message".to_string(), v.status_message.clone()));
                        }
                        rows.push(("".to_string(), "".to_string()));
                    }
                }
            }
            rows
        }
        S::Resources => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match state {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Error(err)) => rows.extend(error_rows(err)),
                Some(crate::lazy::Lazy::Loaded(d)) if d.resources.is_empty() => {
                    rows.push(("  (no resources bundled into this profile)".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Loaded(d)) => {
                    rows.push((format!("Resources ({})", d.resources.len()), "".to_string()));
                    rows.push(("".to_string(), "".to_string()));
                    for r in &d.resources {
                        // A private-hosted-zone or Resolver-rule ARN jumps via
                        // the generic classifier; DNS Firewall rule groups
                        // aren't modeled in this app, so those just display.
                        rows.push(("Resource".to_string(), r.resource_arn.clone()));
                        rows.push(("Type".to_string(), r.resource_type.clone()));
                        rows.push(("Status".to_string(), r.status.clone()));
                        if !r.status_message.is_empty() {
                            rows.push(("Status Message".to_string(), r.status_message.clone()));
                        }
                        rows.push(("".to_string(), "".to_string()));
                    }
                }
            }
            rows
        }
        S::Tags => match state {
            None | Some(crate::lazy::Lazy::Loading) => {
                vec![("  Loading…".to_string(), "".to_string())]
            }
            Some(crate::lazy::Lazy::Error(err)) => error_rows(err),
            Some(crate::lazy::Lazy::Loaded(d)) => resolver_tag_rows(&d.tags),
        },
    }
}

fn resolver_tag_rows(tags: &[(String, String)]) -> Vec<(String, String)> {
    if tags.is_empty() {
        return vec![("  (no tags)".to_string(), String::new())];
    }
    tags.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
}

/// `rules` are the sibling `ResolverRule` rows already in the list that
/// route through this endpoint (`resolver_endpoint_id == e.id`) — no fetch,
/// the VPC-pane pattern.
pub fn resolver_endpoint_section_lines(
    e: &crate::aws::services::route53resolver::ResolverEndpoint,
    section: crate::aws::services::route53resolver::ResolverEndpointDetailSection,
    state: Option<&crate::lazy::Lazy<Box<crate::aws::services::route53resolver::ResolverEndpointDetail>>>,
    rules: &[&crate::aws::services::route53resolver::ResolverRule],
) -> Vec<(String, String)> {
    use crate::aws::services::route53resolver::ResolverEndpointDetailSection as S;
    let flag = |b: Option<bool>| match b {
        Some(true) => "✓ enabled",
        Some(false) => "✗ disabled",
        None => "—",
    };
    match section {
        S::Details => {
            let mut rows = vec![
                ("Name".to_string(), e.name.clone()),
                ("ID".to_string(), e.id.clone()),
                ("Direction".to_string(), e.direction.clone()),
                ("Type".to_string(), e.endpoint_type.clone()),
                (
                    "Protocols".to_string(),
                    if e.protocols.is_empty() {
                        "Do53 (default)".to_string()
                    } else {
                        e.protocols.join(", ")
                    },
                ),
                ("Status".to_string(), e.status.clone()),
            ];
            if !e.status_message.is_empty() {
                rows.push(("Status Message".to_string(), e.status_message.clone()));
            }
            rows.push((
                "IP Address Count".to_string(),
                e.ip_address_count.to_string(),
            ));
            // host VPC id carries the raw vpc- token so Enter jumps to the VPC.
            rows.push(("Host VPC".to_string(), e.host_vpc_id.clone()));
            if !e.outpost_arn.is_empty() {
                rows.push(("Outpost".to_string(), e.outpost_arn.clone()));
                rows.push(("Instance Type".to_string(), e.preferred_instance_type.clone()));
            }
            // Feature flags: shown only when the API reported them, so an
            // endpoint from before these existed doesn't read as "disabled".
            let flags = [
                ("DNS64", e.dns64_enabled),
                ("IPv6 Internet Access", e.ipv6_internet_access_enabled),
                ("RNI Enhanced Metrics", e.rni_enhanced_metrics_enabled),
                ("Target Name Server Metrics", e.target_name_server_metrics_enabled),
            ];
            if flags.iter().any(|(_, v)| v.is_some()) {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Features".to_string(), "".to_string()));
                for (label, v) in flags {
                    if v.is_some() {
                        rows.push((label.to_string(), flag(v).to_string()));
                    }
                }
            }
            if !e.security_group_ids.is_empty() {
                rows.push(("".to_string(), "".to_string()));
                rows.push(("Security Groups".to_string(), "".to_string()));
                // each sg- id is its own row so Enter jumps to that group.
                for sg in &e.security_group_ids {
                    rows.push(("Security Group".to_string(), sg.clone()));
                }
            }
            if e.creation_time.is_some() || e.modification_time.is_some() {
                rows.push(("".to_string(), "".to_string()));
            }
            if let Some(ct) = &e.creation_time {
                rows.push(("Created".to_string(), ct.clone()));
            }
            if let Some(mt) = &e.modification_time {
                rows.push(("Modified".to_string(), mt.clone()));
            }
            rows
        }
        S::Rules => {
            let mut rows = vec![("".to_string(), "".to_string())];
            if !e.is_outbound() {
                rows.push((
                    "  — (only outbound endpoints carry rules)".to_string(),
                    "".to_string(),
                ));
                return rows;
            }
            if rules.is_empty() {
                rows.push((
                    "  (no loaded rules use this endpoint)".to_string(),
                    "".to_string(),
                ));
                return rows;
            }
            rows.push((format!("Rules ({})", rules.len()), "".to_string()));
            rows.push(("".to_string(), "".to_string()));
            for r in rules {
                // rule id carries the raw rslvr-rr- token (jumpable to the
                // Rules sub-tab via resource_jump_target's rslvr-rr- arm).
                rows.push((format!("{} {}", r.rule_type, r.domain_name), r.id.clone()));
            }
            rows
        }
        S::IpAddresses => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match state {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Error(err)) => rows.extend(error_rows(err)),
                Some(crate::lazy::Lazy::Loaded(d)) if d.ip_addresses.is_empty() => {
                    rows.push(("  (no IP addresses)".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Loaded(d)) => {
                    rows.push((
                        format!("IP Addresses ({})", d.ip_addresses.len()),
                        "".to_string(),
                    ));
                    rows.push(("".to_string(), "".to_string()));
                    for ip in &d.ip_addresses {
                        let addr = if !ip.ip.is_empty() && !ip.ipv6.is_empty() {
                            format!("{} / {}", ip.ip, ip.ipv6)
                        } else if !ip.ipv6.is_empty() {
                            ip.ipv6.clone()
                        } else {
                            ip.ip.clone()
                        };
                        rows.push(("IP".to_string(), addr));
                        // subnet id carries the raw subnet- token (jumpable).
                        rows.push(("Subnet".to_string(), ip.subnet_id.clone()));
                        rows.push(("Status".to_string(), ip.status.clone()));
                        if !ip.status_message.is_empty() {
                            rows.push(("Status Message".to_string(), ip.status_message.clone()));
                        }
                        rows.push(("".to_string(), "".to_string()));
                    }
                }
            }
            rows
        }
        S::Tags => match state {
            None | Some(crate::lazy::Lazy::Loading) => vec![("  Loading…".to_string(), "".to_string())],
            Some(crate::lazy::Lazy::Error(err)) => error_rows(err),
            Some(crate::lazy::Lazy::Loaded(d)) => resolver_tag_rows(&d.tags),
        },
    }
}

pub fn resolver_rule_section_lines(
    r: &crate::aws::services::route53resolver::ResolverRule,
    section: crate::aws::services::route53resolver::ResolverRuleDetailSection,
    state: Option<&crate::lazy::Lazy<Box<crate::aws::services::route53resolver::ResolverRuleDetail>>>,
) -> Vec<(String, String)> {
    use crate::aws::services::route53resolver::ResolverRuleDetailSection as S;
    match section {
        S::Details => {
            let mut rows = vec![
                ("Name".to_string(), r.name.clone()),
                ("ID".to_string(), r.id.clone()),
                ("Domain Name".to_string(), r.domain_name.clone()),
                ("Rule Type".to_string(), r.rule_type.clone()),
                ("Status".to_string(), r.status.clone()),
            ];
            if !r.status_message.is_empty() {
                rows.push(("Status Message".to_string(), r.status_message.clone()));
            }
            // FORWARD and DELEGATE rules both route through an outbound
            // endpoint. resolver_endpoint_id carries the raw rslvr- token
            // (jumpable to the Endpoints sub-tab via resource_jump_target's
            // rslvr- arm). Keying this on FORWARD alone once hid the endpoint
            // of every DELEGATE rule.
            if r.uses_endpoint() {
                if let Some(ep) = &r.resolver_endpoint_id {
                    rows.push(("Resolver Endpoint".to_string(), ep.clone()));
                }
            }
            if let Some(dr) = &r.delegation_record {
                rows.push(("Delegation Record".to_string(), dr.clone()));
            }
            if !r.share_status.is_empty() {
                rows.push(("Share Status".to_string(), r.share_status.clone()));
            }
            if !r.owner_id.is_empty() {
                rows.push(("Owner".to_string(), r.owner_id.clone()));
            }
            if r.creation_time.is_some() || r.modification_time.is_some() {
                rows.push(("".to_string(), "".to_string()));
            }
            if let Some(ct) = &r.creation_time {
                rows.push(("Created".to_string(), ct.clone()));
            }
            if let Some(mt) = &r.modification_time {
                rows.push(("Modified".to_string(), mt.clone()));
            }
            rows
        }
        S::Targets => {
            let mut rows = vec![("".to_string(), "".to_string())];
            // Match on the raw string so an unknown future rule type still
            // renders (as "no targets") instead of being mislabelled.
            match r.rule_type.as_str() {
                "DELEGATE" => {
                    rows.push((
                        "  — (delegation rule, no targets — see Delegation Record)".to_string(),
                        "".to_string(),
                    ));
                    return rows;
                }
                "SYSTEM" | "RECURSIVE" => {
                    rows.push((
                        format!("  — ({} rule, no targets)", r.rule_type.to_lowercase()),
                        "".to_string(),
                    ));
                    return rows;
                }
                _ => {}
            }
            if r.targets.is_empty() {
                rows.push(("  (no targets)".to_string(), "".to_string()));
                return rows;
            }
            rows.push((format!("Targets ({})", r.targets.len()), "".to_string()));
            rows.push(("".to_string(), "".to_string()));
            for t in &r.targets {
                rows.push((format!("  {}", t), "".to_string()));
            }
            rows
        }
        S::Associations => {
            let mut rows = vec![("".to_string(), "".to_string())];
            match state {
                None | Some(crate::lazy::Lazy::Loading) => {
                    rows.push(("  Loading…".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Error(err)) => rows.extend(error_rows(err)),
                Some(crate::lazy::Lazy::Loaded(d)) if d.associations.is_empty() => {
                    rows.push(("  (no associations)".to_string(), "".to_string()))
                }
                Some(crate::lazy::Lazy::Loaded(d)) => {
                    rows.push((
                        format!("VPC Associations ({})", d.associations.len()),
                        "".to_string(),
                    ));
                    rows.push(("".to_string(), "".to_string()));
                    for a in &d.associations {
                        // vpc id carries the raw vpc- token (jumpable to VPC).
                        rows.push(("VPC".to_string(), a.vpc_id.clone()));
                        rows.push(("Status".to_string(), a.status.clone()));
                        rows.push(("".to_string(), "".to_string()));
                    }
                }
            }
            rows
        }
        S::Tags => match state {
            None | Some(crate::lazy::Lazy::Loading) => vec![("  Loading…".to_string(), "".to_string())],
            Some(crate::lazy::Lazy::Error(err)) => error_rows(err),
            Some(crate::lazy::Lazy::Loaded(d)) => resolver_tag_rows(&d.tags),
        },
    }
}

fn waf_details_lines(acl: &WafWebAcl) -> Vec<(String, String)> {
    vec![
        ("Name".to_string(), acl.name.clone()),
        ("ID".to_string(), acl.id.clone()),
        ("ARN".to_string(), acl.arn.clone()),
        ("Scope".to_string(), acl.scope.clone()),
        ("".to_string(), "".to_string()),
        ("Description".to_string(), acl.description.clone()),
        ("".to_string(), "".to_string()),
    ]
}

fn waf_traffic_lines(metrics: Option<&WafMetricsState>) -> Vec<(String, String)> {
    match metrics {
        None | Some(WafMetricsState::Loading) => {
            vec![("".to_string(), "Loading traffic metrics…".to_string())]
        }
        Some(WafMetricsState::Error(e)) => {
            let mut rows = vec![("".to_string(), "".to_string())];
            rows.extend(error_rows(e));
            rows
        }
        Some(WafMetricsState::Loaded(data)) => {
            let sum = |pts: &[(f64, f64)]| -> f64 { pts.iter().map(|(_, v)| v).sum() };
            let total_allowed = sum(&data.allowed);
            let total_blocked = sum(&data.blocked);
            let total_counted = sum(&data.counted);
            let total_captcha = sum(&data.captcha);
            let total_challenge = sum(&data.challenge);
            let total =
                total_allowed + total_blocked + total_counted + total_captcha + total_challenge;

            let pct = |v: f64| -> String {
                if total > 0.0 {
                    format!("{:.1}%", v / total * 100.0)
                } else {
                    "—".to_string()
                }
            };

            let mut rows = vec![
                ("Traffic Summary".to_string(), "".to_string()),
                ("".to_string(), "".to_string()),
            ];

            // Header
            rows.push((
                " Metric                  Count         % of Total".to_string(),
                "".to_string(),
            ));
            rows.push((
                " ─────────────────────────────────────────────────".to_string(),
                "".to_string(),
            ));
            for (label, v) in [
                ("Allowed Requests", total_allowed),
                ("Blocked Requests", total_blocked),
                ("Counted Requests", total_counted),
                ("CAPTCHA Requests", total_captcha),
                ("Challenge Requests", total_challenge),
            ] {
                rows.push((
                    format!(" {:<23} {:<14}{}", label, format_count(v), pct(v)),
                    "".to_string(),
                ));
            }
            rows.push((
                " ─────────────────────────────────────────────────".to_string(),
                "".to_string(),
            ));
            rows.push((
                format!(
                    " Total                   {}",
                    format_count(total)
                ),
                "".to_string(),
            ));

            rows.push(("".to_string(), "".to_string()));
            rows.push((
                format!("Period: {} │ press m for full chart overlay", data.time_range.label()),
                "".to_string(),
            ));
            rows.push(("".to_string(), "".to_string()));

            // Per-rule range totals (managed rule-group rollups + Default_Action
            // included) — the console dashboard's "top rules" table.
            if let Some(note) = &data.rule_note {
                rows.push((format!(" ⚠ {}", note), "".to_string()));
                rows.push(("".to_string(), "".to_string()));
            }
            if !data.rule_traffic.is_empty() {
                rows.push((
                    format!("Requests by Rule ({})", data.time_range.label()),
                    "".to_string(),
                ));
                rows.push(("".to_string(), "".to_string()));
                rows.push((
                    format!(
                        " {:<34} {:>8} {:>8} {:>8} {:>8} {:>8} {:>8}",
                        "Rule", "Total", "Allow", "Block", "Count", "CAPTCHA", "Chlng"
                    ),
                    "".to_string(),
                ));
                let fmt0 = |v: f64| -> String {
                    if v > 0.0 { format_count(v) } else { "—".to_string() }
                };
                const MAX_RULE_ROWS: usize = 30;
                for r in data.rule_traffic.iter().take(MAX_RULE_ROWS) {
                    let name = if r.name.chars().count() > 34 {
                        format!("{}…", r.name.chars().take(33).collect::<String>())
                    } else {
                        r.name.clone()
                    };
                    rows.push((
                        format!(
                            " {:<34} {:>8} {:>8} {:>8} {:>8} {:>8} {:>8}",
                            name,
                            format_count(r.total()),
                            fmt0(r.allowed),
                            fmt0(r.blocked),
                            fmt0(r.counted),
                            fmt0(r.captcha),
                            fmt0(r.challenge),
                        ),
                        "".to_string(),
                    ));
                }
                if data.rule_traffic.len() > MAX_RULE_ROWS {
                    rows.push((
                        format!(" … +{} more rules", data.rule_traffic.len() - MAX_RULE_ROWS),
                        "".to_string(),
                    ));
                }
                rows.push(("".to_string(), "".to_string()));
            }

            // Per-label totals — managed rule groups emit these (bot
            // categories, attack signals); absent unless labels fired.
            if !data.label_traffic.is_empty() {
                rows.push((
                    format!("Requests by Label ({})", data.time_range.label()),
                    "".to_string(),
                ));
                rows.push(("".to_string(), "".to_string()));
                const MAX_LABEL_ROWS: usize = 20;
                for l in data.label_traffic.iter().take(MAX_LABEL_ROWS) {
                    let name = if l.name.chars().count() > 64 {
                        format!("{}…", l.name.chars().take(63).collect::<String>())
                    } else {
                        l.name.clone()
                    };
                    let mut parts: Vec<String> = Vec::new();
                    for (v, tag) in [
                        (l.allowed, "alw"),
                        (l.blocked, "blk"),
                        (l.counted, "cnt"),
                        (l.captcha, "cap"),
                        (l.challenge, "chl"),
                    ] {
                        if v > 0.0 {
                            parts.push(format!("{} {}", tag, format_count(v)));
                        }
                    }
                    rows.push((
                        format!(
                            " {} — {} ({})",
                            name,
                            format_count(l.total()),
                            parts.join(" · ")
                        ),
                        "".to_string(),
                    ));
                }
                if data.label_traffic.len() > MAX_LABEL_ROWS {
                    rows.push((
                        format!(
                            " … +{} more labels",
                            data.label_traffic.len() - MAX_LABEL_ROWS
                        ),
                        "".to_string(),
                    ));
                }
                rows.push(("".to_string(), "".to_string()));
            }

            // Sparkline-style breakdown per data point
            if !data.allowed.is_empty() || !data.blocked.is_empty() {
                rows.push(("Recent Activity".to_string(), "".to_string()));
                rows.push(("".to_string(), "".to_string()));

                let max_pts = 20;
                let spark = |pts: &[(f64, f64)]| -> String {
                    if pts.is_empty() { return "—".to_string(); }
                    let bars = "▁▂▃▄▅▆▇█";
                    let bar_chars: Vec<char> = bars.chars().collect();
                    let max_v = pts.iter().map(|(_, v)| *v).fold(0.0_f64, f64::max).max(1.0);
                    let step = pts.len().max(1) / max_pts.min(pts.len()).max(1);
                    pts.iter()
                        .step_by(step.max(1))
                        .take(max_pts)
                        .map(|(_, v)| {
                            let idx = ((v / max_v) * 7.0).round() as usize;
                            bar_chars[idx.min(7)]
                        })
                        .collect()
                };

                rows.push((format!(" Allowed   {}", spark(&data.allowed)), "".to_string()));
                rows.push((format!(" Blocked   {}", spark(&data.blocked)), "".to_string()));
                rows.push((format!(" Counted   {}", spark(&data.counted)), "".to_string()));
                if !data.captcha.is_empty() {
                    rows.push((format!(" CAPTCHA   {}", spark(&data.captcha)), "".to_string()));
                }
                if !data.challenge.is_empty() {
                    rows.push((format!(" Challenge {}", spark(&data.challenge)), "".to_string()));
                }
            }

            rows.push(("".to_string(), "".to_string()));
            rows
        }
    }
}

fn format_count(v: f64) -> String {
    let n = v as u64;
    if n >= 1_000_000 {
        format!("{:.1}M", v / 1_000_000.0)
    } else if n >= 1_000 {
        format!("{:.1}K", v / 1_000.0)
    } else {
        format!("{}", n)
    }
}

fn waf_insights_lines(
    state: Option<&Lazy<Box<WafInsights>>>,
) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    match state {
        None | Some(Lazy::Loading) => {
            rows.push(("  Aggregating sampled requests…".to_string(), "".to_string()));
            return rows;
        }
        Some(Lazy::Error(e)) => {
            rows.extend(error_rows(e));
            return rows;
        }
        Some(Lazy::Loaded(d)) => {
            rows.push(("Sampled Requests (last 3 hours)".to_string(), "".to_string()));
            rows.push(("".to_string(), "".to_string()));
            rows.push((
                "Population".to_string(),
                format!(
                    "{} requests · {} samples · {} samplers",
                    format_count(d.population as f64),
                    d.samples,
                    d.samplers
                ),
            ));
            if d.skipped_rules > 0 {
                rows.push((
                    format!(
                        "  ⚠ {} lower-priority rules not sampled (cap {})",
                        d.skipped_rules,
                        crate::aws::services::waf::MAX_INSIGHT_SAMPLERS
                    ),
                    "".to_string(),
                ));
            }
            if d.sampling_disabled > 0 {
                rows.push((
                    format!("  {} rules have sampled requests disabled", d.sampling_disabled),
                    "".to_string(),
                ));
            }
            if d.failed_samplers > 0 {
                rows.push((
                    format!("  ⚠ {} samplers failed", d.failed_samplers),
                    "".to_string(),
                ));
            }
            if d.samples == 0 {
                rows.push(("".to_string(), "".to_string()));
                rows.push((
                    "  No sampled requests in the last 3 hours.".to_string(),
                    "".to_string(),
                ));
                return rows;
            }

            let total: u64 = d.actions.iter().map(|(_, c)| c).sum::<u64>().max(1);
            rows.push(("".to_string(), "".to_string()));
            rows.push(("Actions".to_string(), "".to_string()));
            for (action, count) in &d.actions {
                rows.push((
                    action.clone(),
                    format!(
                        "{} ({:.1}%)",
                        format_count(*count as f64),
                        *count as f64 / total as f64 * 100.0
                    ),
                ));
            }

            let mut push_top = |title: &str, list: &[crate::aws::services::waf::WafInsightRow]| {
                if list.is_empty() {
                    return;
                }
                rows.push(("".to_string(), "".to_string()));
                rows.push((title.to_string(), "".to_string()));
                for r in list {
                    let key: String = if r.key.chars().count() > 70 {
                        format!("{}…", r.key.chars().take(69).collect::<String>())
                    } else {
                        r.key.clone()
                    };
                    let blocked = if r.blocked > 0 {
                        format!(" · {} blocked", format_count(r.blocked as f64))
                    } else {
                        String::new()
                    };
                    rows.push((
                        format!(
                            "  {} — {} ({:.1}%){}",
                            key,
                            format_count(r.count as f64),
                            r.count as f64 / total as f64 * 100.0,
                            blocked
                        ),
                        "".to_string(),
                    ));
                }
            };
            push_top("Top Rules", &d.top_rules);
            push_top("Top Client IPs", &d.top_ips);
            push_top("Top Countries", &d.top_countries);
            push_top("Top URIs", &d.top_uris);
            push_top("Top User Agents", &d.top_agents);
            push_top("Top Labels", &d.top_labels);

            rows.push(("".to_string(), "".to_string()));
            rows.push((
                "  Weighted from GetSampledRequests — indicative, not exact counts.".to_string(),
                "".to_string(),
            ));
        }
    }
    rows.push(("".to_string(), "".to_string()));
    rows
}

