pub fn secret_section_lines(
    secret: &SecretEntry,
    section: SecretDetailSection,
) -> Vec<(String, String)> {
    match section {
        SecretDetailSection::Details => secret_details_lines(secret),
        SecretDetailSection::Rotation => secret_rotation_lines(secret),
        SecretDetailSection::Tags => secret_tags_lines(secret),
    }
}

fn secret_details_lines(secret: &SecretEntry) -> Vec<(String, String)> {
    let mut rows = vec![];

    rows.push(("Name".to_string(), secret.name.clone()));
    if let Some(desc) = &secret.description {
        rows.push(("Description".to_string(), desc.clone()));
    }
    if !secret.arn.is_empty() {
        rows.push(("ARN".to_string(), secret.arn.clone()));
    }
    if let Some(svc) = &secret.owning_service {
        rows.push(("Managed By".to_string(), svc.clone()));
    }

    rows.push(("".to_string(), "".to_string()));
    let encryption = secret
        .kms_key_id
        .as_ref()
        .map(|k| format!("KMS ({})", k))
        .unwrap_or_else(|| "aws/secretsmanager (default)".to_string());
    rows.push(("Encryption".to_string(), encryption));

    rows.push(("".to_string(), "".to_string()));
    if !secret.created.is_empty() {
        rows.push(("Created".to_string(), secret.created.clone()));
    }
    if !secret.last_changed.is_empty() {
        rows.push(("Last Changed".to_string(), secret.last_changed.clone()));
    }
    if !secret.last_accessed.is_empty() {
        rows.push(("Last Accessed".to_string(), secret.last_accessed.clone()));
    }

    rows.push(("".to_string(), "".to_string()));
    rows.push(("Value".to_string(), "x reveal · Y copy".to_string()));

    rows.push(("".to_string(), "".to_string()));
    rows
}

fn secret_rotation_lines(secret: &SecretEntry) -> Vec<(String, String)> {
    let mut rows = vec![];

    rows.push((
        "Rotation".to_string(),
        if secret.rotation_enabled { "Enabled".to_string() } else { "Disabled".to_string() },
    ));

    if secret.rotation_enabled {
        if let Some(days) = secret.rotation_after_days {
            rows.push(("Interval".to_string(), format!("every {} days", days)));
        }
        if let Some(sched) = &secret.rotation_schedule {
            rows.push(("Schedule".to_string(), sched.clone()));
        }
        if let Some(lambda) = &secret.rotation_lambda_arn {
            let name = lambda.rsplit(':').next().unwrap_or(lambda);
            rows.push(("Rotation Lambda".to_string(), name.to_string()));
        }
    }

    rows.push(("".to_string(), "".to_string()));
    if !secret.last_rotated.is_empty() {
        rows.push(("Last Rotated".to_string(), secret.last_rotated.clone()));
    } else {
        rows.push(("Last Rotated".to_string(), "never".to_string()));
    }
    if !secret.next_rotation.is_empty() {
        rows.push(("Next Rotation".to_string(), secret.next_rotation.clone()));
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

fn secret_tags_lines(secret: &SecretEntry) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];

    if secret.tags.is_empty() {
        rows.push(("  No tags".to_string(), "".to_string()));
    } else {
        let mut sorted: Vec<(&String, &String)> = secret.tags.iter().collect();
        sorted.sort_by_key(|(k, _)| k.as_str());
        for (key, value) in sorted {
            rows.push((format!("  {}", key), value.clone()));
        }
    }

    rows.push(("".to_string(), "".to_string()));
    rows
}

// ── SSM parameter split pane ──────────────────────────────────────────────

fn render_ssm_parameter_split(app: &App, param: &SsmParameter, area: Rect, frame: &mut Frame) {
    let focused = app.details_focused;
    let footer = detail_footer(app, focused, 4, "x reveal · Y copy value");

    let mut block = theme::pane_block("SSM Parameter", focused);
    block = block.title(
        Title::from(Span::styled(footer, Style::default().fg(theme::text_dim())))
            .position(Position::Bottom)
            .alignment(Alignment::Right),
    );

    let inner = block.inner(area);
    frame.render_widget(block, area);

    let header_lines = build_ssm_param_header_lines(param);
    let header_h = header_lines.len() as u16;

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(header_h),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

    frame.render_widget(Paragraph::new(header_lines), chunks[0]);
    render_hr(chunks[1], frame);
    render_ssm_param_section_tabs(app, chunks[2], frame);
    render_hr(chunks[3], frame);
    render_split_section_body(app, chunks[4], frame);
}

fn build_ssm_param_header_lines(param: &SsmParameter) -> Vec<Line<'static>> {
    let mut lines: Vec<Line<'static>> = vec![Line::raw("")];

    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            param.name.clone(),
            Style::default()
                .fg(crate::ui::theme::text_primary())
                .add_modifier(Modifier::BOLD),
        ),
    ]));

    lines.push(Line::raw(""));
    lines.push(header_kv(
        "Type",
        &format!("{} · {} · v{}", param.param_type, param.tier, param.version),
    ));
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            "x reveal value · Y copy to clipboard",
            Style::default().fg(theme::text_dim()),
        ),
    ]));

    lines.push(Line::raw(""));
    lines
}

fn render_ssm_param_section_tabs(app: &App, area: Rect, frame: &mut Frame) {
    let tabs = descriptor_tabs(app, &crate::aws::services::ssm::SSM_PARAMETER_SECTIONS);
    render_section_tab_bar(app, area, frame, &tabs);
}

pub fn ssm_parameter_section_lines(
    param: &SsmParameter,
    section: SsmParameterDetailSection,
    detail: Option<&Lazy<SsmParamDetail>>,
) -> Vec<(String, String)> {
    match section {
        SsmParameterDetailSection::Details => ssm_param_details_lines(param),
        SsmParameterDetailSection::Value => ssm_param_value_lines(param),
        SsmParameterDetailSection::History => ssm_param_history_lines(param, detail),
        SsmParameterDetailSection::Tags => ssm_param_tags_lines(detail),
    }
}

fn ssm_param_details_lines(param: &SsmParameter) -> Vec<(String, String)> {
    let mut rows = vec![
        ("Name".to_string(), param.name.clone()),
        ("Type".to_string(), param.param_type.clone()),
        ("Tier".to_string(), param.tier.clone()),
        ("Version".to_string(), param.version.to_string()),
    ];
    if let Some(dt) = &param.data_type {
        rows.push(("Data Type".to_string(), dt.clone()));
    }
    rows.push(("".to_string(), "".to_string()));
    if !param.last_modified.is_empty() {
        rows.push(("Last Modified".to_string(), param.last_modified.clone()));
    }
    if let Some(user) = &param.last_modified_user {
        rows.push(("Modified By".to_string(), user.clone()));
    }
    rows.push(("".to_string(), "".to_string()));
    let encryption = if param.is_secure() {
        param
            .kms_key_id
            .as_ref()
            .map(|k| format!("SecureString · KMS ({})", k))
            .unwrap_or_else(|| "SecureString · aws/ssm (default)".to_string())
    } else {
        "None (plaintext)".to_string()
    };
    rows.push(("Encryption".to_string(), encryption));
    if let Some(desc) = &param.description {
        rows.push(("Description".to_string(), desc.clone()));
    }
    if let Some(pattern) = &param.allowed_pattern {
        rows.push(("Allowed Pattern".to_string(), pattern.clone()));
    }
    if !param.arn.is_empty() {
        rows.push(("".to_string(), "".to_string()));
        rows.push(("ARN".to_string(), param.arn.clone()));
    }
    rows.push(("".to_string(), "".to_string()));
    rows
}

fn ssm_param_value_lines(param: &SsmParameter) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    rows.push(("Current Value".to_string(), "x reveal · Y copy".to_string()));
    rows.push(("".to_string(), "".to_string()));
    if param.is_secure() {
        rows.push((
            "  SecureString".to_string(),
            "value is KMS-encrypted; revealed on demand only".to_string(),
        ));
    } else {
        rows.push((
            "  Plaintext".to_string(),
            "press x to view the current value in $EDITOR".to_string(),
        ));
    }
    rows.push(("".to_string(), "".to_string()));
    rows.push((
        "Version".to_string(),
        format!("v{} (see History for older versions)", param.version),
    ));
    rows.push(("".to_string(), "".to_string()));
    rows
}

fn ssm_param_history_lines(
    param: &SsmParameter,
    detail: Option<&Lazy<SsmParamDetail>>,
) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    match detail {
        None | Some(Lazy::Loading) => {
            rows.push(("  Loading history…".to_string(), "".to_string()));
        }
        Some(Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(Lazy::Loaded((history, _))) => {
            if history.is_empty() {
                rows.push(("  No history".to_string(), "".to_string()));
            } else {
                for v in history {
                    // Group header per version.
                    let mut head = format!("v{}", v.version);
                    if v.version == param.version {
                        head.push_str(" (current)");
                    }
                    if v.changed {
                        head.push_str("  · changed");
                    }
                    rows.push((head, "".to_string()));
                    if !v.last_modified.is_empty() {
                        rows.push(("  Modified".to_string(), v.last_modified.clone()));
                    }
                    if let Some(u) = &v.user {
                        rows.push(("  By".to_string(), u.clone()));
                    }
                    if !v.param_type.is_empty() {
                        rows.push(("  Type".to_string(), v.param_type.clone()));
                    }
                    if !v.labels.is_empty() {
                        rows.push(("  Labels".to_string(), v.labels.join(", ")));
                    }
                    if let Some(val) = &v.value {
                        rows.push(("  Value".to_string(), val.clone()));
                    }
                    if let Some(desc) = &v.description {
                        rows.push(("  Description".to_string(), desc.clone()));
                    }
                    rows.push(("".to_string(), "".to_string()));
                }
            }
        }
    }
    rows
}

fn ssm_param_tags_lines(detail: Option<&Lazy<SsmParamDetail>>) -> Vec<(String, String)> {
    let mut rows = vec![("".to_string(), "".to_string())];
    match detail {
        None | Some(Lazy::Loading) => {
            rows.push(("  Loading tags…".to_string(), "".to_string()));
        }
        Some(Lazy::Error(e)) => {
            rows.extend(error_rows(e));
        }
        Some(Lazy::Loaded((_, tags))) => {
            if tags.is_empty() {
                rows.push(("  No tags".to_string(), "".to_string()));
            } else {
                for (key, value) in tags {
                    rows.push((format!("  {}", key), value.clone()));
                }
            }
        }
    }
    rows.push(("".to_string(), "".to_string()));
    rows
}

